/* Ice Age Mammoth Runner — gameplay engine (canvas, no external deps).
   Modules: Config, AudioManager, ParticleManager, BackgroundTimeManager,
   GroundManager, WorldScroller, PlayerController, ObstacleController,
   DitchController, LevelOnePuzzle, LevelTwoCutPuzzle, PolygonCutManager,
   FeedbackFX, HintManager, GameFlowController. */

/* The specialised geometries the curriculum needs - heptagons, octagons,
   irregular-convex and concave shapes - are defined and verified ONCE, in
   polygons.js. The runner never re-states their coordinates: PolygonFactory below
   asks that registry for vertices by name, so there is exactly one definition of
   every polygon a phase can name. */
import { pointsOf as verifiedPoints, sidesOf as verifiedSides } from './polygons.js';
/* The delivered ice blocks, and the ring TRACED OFF EACH ONE. Generated by
   tools/build-option-shapes.mjs, which fails the build if a picture's traced side
   count or convexity disagrees with what the curriculum calls that shape — so the
   number a learner counts on screen is the number the game is checking. */
import { optionShapes } from './option-shapes.js';

export const CFG = {
  W: 1920, H: 1080,
  /* THE WALKING LINE, and it was raised from 890 to 840 for one reason: so a correct
     shape can land at EXACTLY the size it was cut.

     The chain is short and it is all arithmetic. A plug has to fit between the walking
     line and the bottom of the stage or its silhouette gets clipped — and a clipped
     silhouette is a different shape, which is how phase 1's triangle once arrived as a
     trapezoid. At 890 there were only 190px of room and the tallest three-option chunk
     is 273px, so the plug had to be scaled to about 0.79 and the learner's answer
     changed size on the way in. At 840 there are 240, `optionH` caps a chunk at 234, and
     the two now match: the fit comes out at 1.0 and nothing resizes at all.

     What else moves with it, all automatically: the character's feet, the path art
     (anchored through `path.surfaceRatio`), the obstacles, the crevasse and the water.
     The path art is 657px tall and still reaches past the bottom of the stage. The
     crevasse also gains 50px of on-screen depth, which is the one place the extra room
     is visible and it reads better for it. */
  surfaceY: 840,
  mammothX: 430,
  runSpeed: 520,
  /* THE JUMP WINDOW, widened — it was genuinely too tight, and the reason is not the
   * clearance height, which is what it looks like.
   *
   * Worked through with the old numbers: the apex is jumpVel^2/2g = 295px and a rock
   * only has to be cleared by 45% of its 140px height, so the character is above the
   * bar for 0.79s of a 0.887s flight. That part was never the problem. The rock,
   * though, crosses the danger zone — its own width plus the 136px body box — in about
   * 0.58s at 520px/s. So the press has to land inside 0.79 - 0.58 = ~0.2s. Two tenths
   * of a second is a reflex test, not a jump, and it is the first thing the game asks
   * anyone to do.
   *
   * Every term is loosened rather than one of them a lot: more airtime, a lower bar, a
   * narrower body, and more forgiving input. Together they roughly double the margin,
   * measured rather than estimated — see the note on the collider below.
   *
   * gravity is left alone: it sets the FEEL of the arc, and a floatier jump on the
   * same airtime reads as the character being lighter, which is not the fix. */
  gravity: 3000,
  jumpVel: -1470,          // apex 360px, airtime 0.98s (was 295px / 0.887s)
  coyoteMs: 150,           // pressed a moment late off the ground still counts
  bufferMs: 190,           // pressed a moment early still fires on landing
  totalDistance: 11200,
  // surfaceRatio anchors the path image to surfaceY. The art's faint top fringe starts
  // at src y~216 but its SOLID snow edge is at ~227, so the old 0.406 left the feet
  // hovering ~14px above anything solid. 0.4377 puts the solid edge just above the
  // footline so the feet read as planted in the snow.
  // tileX/tileW crop the tapered ends off the path art. It is a finished segment that
  // thins from ~160 opaque rows to ~31 at each edge, so tiling the full 1640px butted
  // two tapers together every 1837px and cut an obvious notch in the path.
  path: {
    srcW: 1640, srcH: 530, tileX: 56, tileW: 1536,
    // scale 1.12 left the path art ending at y~1065, 15px short of the screen edge,
    // showing a strip of background under it. 1.24 takes it past the bottom.
    scale: 1.24, surfaceRatio: 0.4377, contentBottom: 0.7321
  },
  // pairGap/pairScale set the difficulty of the second obstacle. At 132px apart and
  // 0.82 scale the pair could only be cleared inside a 73ms window; 100px at 0.70
  // widens that to ~180ms, against ~260ms for the single crystal.
  // Obstacles are the snow-covered rocks. height is the on-screen visible height every
  // variant is normalised to, so swapping art can never change the jump difficulty.
  // pairGap/pairScale set the second obstacle: at 132px apart and 0.82 the pair could
  // only be cleared inside a 73ms window; 100px at 0.70 widens that to ~180ms.
  /* TWO HEIGHTS ON PURPOSE.

       height      what the COLLIDER is. Never change this without meaning to change
                   how hard the jump is: the hit test is `feet > surfaceY - height*0.45`,
                   so raising it raises the bar the character has to clear.
       drawHeight  what is DRAWN. At 140 the rock stood 140px against a character whose
                   body is about 470px tall — a quarter of its height — and read as a
                   pebble rather than as something to jump. 230 reads as an obstacle.

     Keeping them apart is the whole point: the rock now LOOKS like a real obstacle
     without the jump becoming harder than it was tuned to be. */
  /* sinkRatio, not a flat `sink`. HOW FAR THE ROCK IS BURIED IN THE SNOW, as a
     fraction of its DRAWN height — 6px absolute was 4% of a 140px rock and only 2.6% of
     a 230px one, so as soon as the art got bigger the rock stopped touching the ground
     and read as a sticker laid on the path. A proportional sink keeps the same amount of
     the rock buried whatever size it is drawn at, which is what makes it sit IN the snow
     with the drift coming up around its base. Purely visual: the collider is `height`
     and is measured from surfaceY, so this cannot change the jump. */
  /* ONE ROCK, ONE JUMP, AND THE SPACING IS DERIVED RATHER THAN PICKED.

     `pairGap` was 100px — less than the character is wide. Several rocks at that
     spacing are one clump cleared by a single jump, so raising the count from two to
     four made the obstacle wider without ever asking for another jump, and `pairScale`
     shrank them to fit, which read as smaller rocks rather than more of them.

     The replacement is not a pixel constant either. What matters is TIME ON THE GROUND
     between landing from one rock and having to leave the ground for the next, and that
     falls out of the jump: airtime is 2|jumpVel|/gravity, and a leap therefore covers
     runSpeed x airtime of ground. Anything left over is running room. So the gap is
     computed in spawn() as leap + runSpeed x runRoomS, and it follows the jump
     automatically — tune the arc and the rocks re-space themselves instead of silently
     becoming a clump again.

     runRoomS is 3.4s. At the current arc that is about 2230px between rocks: land, run
     for over three seconds across open ice, then the next one comes into view and is
     jumped on its own. It was 1.2s (1134px), which read as a row of hurdles; the ask
     was a JOURNEY — rocks spread far apart the way a platformer paces them, so each
     one is an event with running in between and the stretch between puzzles shows the
     distance being covered. Nothing is cut short by the extra length: PHASE_RUN waits
     for the last rock to be passed before the next crossing, however far out it sits. */
  /* SMALLER: 80% of the delivered size. A lower rock is a shorter, more forgiving hop,
     which is what a child needs while learning the one button; the per-variant colliders
     scale with the drawn width, so nothing else has to change. */
  obstacle: { height: 112, drawHeight: 184, sinkRatio: 0.11, runRoomS: 3.4, pairScale: 1 },
  /* Shared sprite geometry. Every sheet, for every character, is rebuilt on one
     420x320 cell with the content bottom on a shared baseline — baseGap px up from
     the cell bottom — so a character is exactly the same size whichever animation is
     playing and its feet never drift between them. The old 380-wide cells clipped a
     trunk or a tail on several frames and let neighbours bleed into each other. */
  sprite: {
    /* baseGap is where the FOOT LINE sits above the cell bottom, and it is 54 rather
       than 6 because tools/slice-char.mjs now aligns every frame on its feet instead
       of on its lowest pixel — which is what stopped the character floating. A pose
       with a hanging trunk needs room BELOW the feet inside the cell (52 source px at
       the worst), and that room is what this reserves. Change it only together with
       the slicer, which prints the value it has built the sheets to. */
    /* 27, not 25: re-measured by tools/slice-char.mjs when the delivered knockout and
       idle sheets joined the set. It is the slicer's own output and the two must agree
       or the character walks above or below the snow — the tool prints the number it
       needs on every run. */
    cw: 420, ch: 320, baseGap: 27, scale: 1.12, fps: 15,
    /* THE FRIGHT'S OWN RATE. The delivered sheet is authored at 60ms a frame, so 36
       frames is 2.16s and the sheet has to be walked at 1/0.06 = 16.67fps to play at
       the speed it was drawn for. At 16 it ran 4% slow, which nobody can see; the point
       of pinning it is that CFG.timing.frightHold below is derived from this number, so
       if one changes the other has to follow. */
    tremorFps: 16.67, lookFps: 9,
    /* The delivered idle is authored at 60ms a frame like the rest, so 16.67fps plays
       it at the speed it was drawn for — 36 frames is a 2.16s breathing loop. */
    idleFps: 16.67,
    // 16 frames at 15fps is 1.07s, and the Try Again card comes in at T.knockout
    // (1100ms) — so the crash finishes playing just as the card arrives
    koFps: 15
  },

  /* The playable roster: the mammoth, and only the mammoth. The polar bear cub and the
     select screen that chose between them are gone — a screen that asks a question with
     one answer is a tap the player must make before the game will start.

     The roster stays a LIST even at one entry, because gameplay numbers (speed, gravity,
     jump, collider) are deliberately not in it: they are global, so a second explorer
     could never make the geometry easier or harder depending on who the learner liked
     the look of. Characters differ only in artwork, frame counts and reactions. */
  characters: [
    {
      id: 'mammoth', name: 'Momo', tag: 'Brave Little Explorer',
      // Selection-screen identity. The stats are flavour, not physics — every
      // explorer runs and jumps identically, because a geometry question must not
      // get easier or harder depending on who the learner liked the look of.
      theme: '#F2A93B', theme2: '#C4631B',
      blurb: 'Woolly, warm and completely unbothered by a blizzard.',
      stats: { Speed: 3, Grip: 5, Grit: 5 },
      /* THE THREE DELIVERED GIFS, and nothing else. The shiver and the knockout came
         from earlier generated grids and have been removed on request, along with the
         earlier run, jump and skid takes.

         What that costs, so it is on the record: SHAKE, LOOK_DOWN, KNOCKOUT and HURT no
         longer have art of their own and fall back to poses from the jump sheet — the
         settled grounded frame while the learner works on a puzzle, and the tall alert
         frame for a crash. Those fallbacks were already in PlayerController for exactly
         this case, so nothing breaks; the character is just less expressive in those
         three moments than it was. Add a shake/hurt GIF and they come straight back. */
      sheets: {
        run: 'assets/char/mammoth-run.webp',
        jump: 'assets/char/mammoth-jump.webp',
        skid: 'assets/char/mammoth-skid.webp',
        /* THE FRIGHT AT THE EDGE, delivered. SHAKE and LOOK_DOWN had no art at all and
           fell back to a pose out of the jump sheet — so the one beat the whole puzzle
           hangs on, the character arriving at a hole in the world and reacting to it,
           was a still frame with a procedural tremor over it. 36 frames now. */
        shake: 'assets/char/mammoth-shake.webp',
        /* THE CRASH, delivered. KNOCKOUT and HURT read this slot, and with nothing in
           it they read the fright frames BACKWARDS as an improvised recoil — a fair
           trick, and nothing like a crash. This is a whole performance: it runs, hits,
           tumbles and lands sitting down dazed with spiral eyes. */
        hurt: 'assets/char/mammoth-hurt.webp',
        /* THE IDLE SHEET, loaded for the FINALE and for nothing else.

           It was built and then held back, because LOOK_DOWN — the pose held for the
           length of a puzzle — is better served by the last frame of the delivered
           fright, which is the pose the character has just arrived at. That still
           holds; LOOK_DOWN does not use this.

           What does use it is the celebration. CELEBRATE animates off the hop arc, and
           the hop is `|sin(t*7)| * 26 * clamp(1.4 - t, 0, 1)` — so after 1.4s the hop
           is zero, `up` is zero, and the sprite sits on ONE frame for as long as the
           ending is on screen. That is the frozen character at the reward moment: the
           two friends meet and the hero stops being animated. A held pose has to keep
           breathing or it reads as a crash.

           So the 1.5MB is now paying for something. */
        idle: 'assets/char/mammoth-idle.webp',
        /* The note that used to be here explained why it was absent:
         *
         * mammoth-idle.webp is built by tools/slice-char.mjs and sits in this folder
         * ready to use. It is held back rather than wired in: LOOK_DOWN now holds the
         * final frame of the DELIVERED fright animation, which is a standing alert
         * pose the character has just arrived at, and swapping that for a neutral
         * breathing loop throws away the reaction the learner just watched.
         *
         * It is not listed here because a listed sheet is FETCHED — 1.5MB pulled down
         * on every load for something nothing draws, which on a phone is a real cost
         * for nothing. To turn it on: add the line back, add `idle: 36` to frames
         * below, and take the idleSheet branch in PlayerController's LOOK_DOWN case
         * out of its comment. */
      },
      /* Straight from tools/slice-char.mjs — the sheets are built to these counts, so
         the two move together. The run is 20 because the source art had 20 and the
         cycle is distance-driven, so it is simply smoother; nothing else changes. */
      frames: { run: 36, jump: 10, skid: 36, shake: 36, hurt: 36, idle: 36 },
      /* The knockout art has a ring of stars and spiral eyes DRAWN IN. The engine's
         own circling stars would be a second set — the fault docs/ANIMATION.md warns
         about. They were off for that reason, and then asked for by name: the sheet's
         spiral eyes read at this size as a squint, and the circling stars are the
         cartoon shorthand a child knows. On, as requested. */
      koStars: true,
      // named poses inside the jump sheet
      jumpMap: { idle: 0, crouch: 1, launch: 2, rise: 3, apex: 4, fall: 5, preLand: 6, land: 7, absorb: 8, alert: 9 },
      /* Drawn at 1.75x. The slicer's scale came down when the cell had to reserve room
         under the feet for a hanging trunk, so this makes up the difference: the
         character stands about 420px tall against a 1080 stage.

         Cosmetic only — the collider is a fixed box around mammothX and the jump
         physics are global, so this cannot make the run easier or harder. Its right
         edge lands near x 695 and the option row's left edge is held at 770, so there
         is still clear air between them; a test samples every falling chunk to prove
         it. */
      /* STRIDE IS THE CADENCE CONTROL. The run cycle is driven by distance travelled,
         not by a clock: the frame comes from runDist / stride, so stride is how far the
         world moves in one full cycle — and therefore how FAST the legs appear to go.

         At 540 the 36-frame cycle completed in about a second, which is 35 frames a
         second, and it looked like the animation was being fast-forwarded. The source
         GIF is authored at 60ms a frame, so a full cycle is 2.16s; at the default run
         speed of 520px/s that is 1120px of ground. Playing it at the rate it was drawn
         for is what makes it read as running rather than scrabbling. */
      scale: 1.75, stride: 1120,
      /* WHERE THE FEET LAND, measured off the sliced sheet: the frames whose foot line
         is deepest. It is a QUADRUPED gait with four footfalls per cycle, clustered at
         3-4, 11-12, 21-22 and 29-31 — the code used to assume two, at frame 0 and the
         halfway frame, so the crunches fired at moments when no foot was down. */
      contacts: [3, 11, 21, 30],
      voice: 'trumpet'
    }
  ],
  timing: {
    /* The run before the first crevasse, and the recovery after the first rock. Both
       roughly tripled: the puzzles were arriving so close together that the game read
       as a quiz with scenery rather than a journey with puzzles in it. */
    run1: 7000, postJump1: 4200, run2: 2600, postJump2: 1900,
    /* breakSkid is the whole stop, and it is now 2300 rather than 920 because the skid
       sheet is 36 frames mapped across it: at 920ms those played at 46fps and the
       animation looked fast-forwarded. 140ms of that is the anticipation hold, leaving
       2160ms of slide — which is exactly the source GIF's own 36 x 60ms.

       It lengthens the slide from about 240px to about 540px, so the stop reads as
       heavier. Nothing downstream needs adjusting: the crevasse is laid out from the
       distance this integrates to, and the quake still peaks on the frame the ice
       cracks and is over by the time the skid ends. */
    /* THE SKID, SHORTENED. 2300ms measured as 2.3 seconds between the ground giving
       way and the character coming to rest — long enough that the stop reads as slow
       rather than as a skid. 1400 still decelerates visibly over the whole slide (the
       curve is unchanged, only its duration) and takes nearly a second out of the wait
       before anything can be done.

       The DISTANCE travelled is the integral of the speed curve and startBreak solves
       the crevasse position from it, so the near lip stays exactly as far ahead of the
       character as it was — shortening this moves where he stops, not how much room he
       has. curriculum.spec asserts that clearance directly. */
    breakSkid: 1400, levelIntro: 420, shapeDrop: 560,
    focus: 500, split: 280, fly: 820,
    celebrate: 700, holdRepair: 500, crossfade: 4200,   // a sky change is a slow thing; 1500 read as a cut
    // the instruction holds the stage alone before the options come down
    /* HOW LONG THE SENTENCE OWNS THE STAGE, and it is a reading time rather than a
       beat. "Cut the shape with 5 sides" is six words; a child reading at two to three
       words a second needs about 2.5s for the words alone, plus a moment to take in
       what the sentence is asking. 2000 was measured against the animation it precedes
       rather than against a reader, and it cut the slower ones off mid-sentence.

       3400 is the reading time; the blocks then lower in, and by the time anything is
       cuttable the sentence has left — see the note on `instruction` in the HUD state. */
    /* HOW LONG THE INSTRUCTION HOLDS THE STAGE BEFORE THE BLOCKS COME DOWN, and this
       was the reported delay.

       Measured chain from the ground giving way: ice open at 616ms, character at rest
       at 2298ms, state change at 2315ms — seventeen milliseconds after he stops, so
       detection was never the problem — and then NOTHING until 5863ms, when the blocks
       finally began to descend. Three and a half seconds of a static sentence after the
       character had already stopped. That is this constant.

       It exists for a real reason: an instruction that appears while the blocks are
       arriving loses, because the player watches the movement instead of reading. But
       "Cut the triangle." takes well under a second and a half to read, and 3400 was
       three times what the job needs. At 1400 the sentence still has the stage to
       itself before anything moves, and the player is cutting more than two seconds
       sooner.

       The instruction does not vanish when the blocks arrive — instructionHold keeps it
       up well past this — so shortening the gap costs no reading time. It only stops
       the game standing still while the reading happens. */
    introRead: 1400,
    // how long the knockout plays before the Try Again card pops in
    /* knockout is when the character is DOWN — kept because the daze, the stars and
       the hit vignette are keyed to it. recover is when the run resumes, and it has
       to clear the delivered knockout animation: 36 frames at koFps 15 is 2400ms, so
       3000 leaves ~600ms sitting dazed before he gets up. Shorten it and the crash
       is cut off mid-tumble; there is no card to hide behind any more. */
    knockout: 1100, recover: 3000,
    // how long an instruction banner stays before sliding away
    instructionHold: 3800, instructionRemind: 2200
  },
  /* Seven phases of the same CUT mechanic, with the geometry getting richer rather
     than the interface getting harder. Difficulty never comes from speed, timers,
     tiny shapes or small hit areas — only from the polygons being asked about. */
  /* One large natural crevasse per gap — no shaped socket, because a hole cut to the
     answer's silhouette hands the learner the answer. The crevasse is far wider than
     a jump (a jump carries ~460px), has broken lips and walls that pinch and bulge,
     and holds a pool of glacial melt water at the bottom. A wrong chunk falls all
     the way into it and goes under with a splash; the right one wedges at the
     surface and the ice bridges out from both lips to meet it. */
  levelOne: {
    gapW: 620,             // one crevasse, centred on the stage
    /* TWO CREVASSES HAVE TO FIT ON THE STAGE, and at 430/150 they did not.

       The constraints are all hard: each crevasse must be over 400px wide or a jump
       clears it (a jump carries ~460px), the near lip must be at least 630px past the
       character, and the far lip must stay on a 1920 stage. 2 x 430 + 150 = 1010 from
       x 900 puts the far lip at 1910, past the 1860 the row can use. 2 x 415 + 120
       = 950 puts it at 1850, and 415 still clears the jump.

       THREE do not fit at all: even at the bare minimum, 3 x 405 + 2 x 110 = 1435 from
       x 630 lands the far lip at 2065. Two is the most a 1920 stage can hold. */
    gapWMulti: 415,        // legacy fixed width, kept for the one-ditch fallback

    /* THE DITCH IS NOW SIZED FROM THE SHAPE THAT BRIDGES IT.
     *
     * It used to be a fixed 620px (415 with two), and the answer dropped into the
     * middle of it as a small plug while drawCrossingFill closed snow around the rest
     * to make something walkable. That is why the repair read as a block dropped in a
     * hole rather than as a bridge: most of the mended span was snow the player had
     * nothing to do with.
     *
     * A ditch is now the width of the piece that spans it, less the bearing it takes
     * on each lip. The piece IS the bridge, edge to edge, and no fill is drawn.
     *
     * bearing is the overlap onto each lip, as a fraction of the piece width. A real
     * plank needs to rest on something at both ends; 0.09 each side reads as seated
     * rather than balanced, and it is what stops a hairline of daylight showing at
     * the joins when the surface bobs.
     *
     * WHY THIS DOES NOT LEAK THE ANSWER, which is the first thing to check: every
     * option in a phase is fitted to the SAME box width (seatedChunk clamps to
     * box.w), so the ditch comes out the same size whichever shape is the target. It
     * varies BETWEEN phases, because a five- or six-option row divides into narrower
     * boxes — which is the variety asked for, arrived at without the terrain saying
     * anything about which shape fits. Nothing shape-like is ever cut into the ditch:
     * only its SPAN is derived, and its lips stay the same broken ice as before. */
    /* 0.03, from 0.09. The hole is cut to the piece minus this at each end, and the
       piece cannot grow: it lands at the size it was cut, and the cavity under the
       walking line is 234px, so the tallest option is 234 tall and the row comes out
       about 243 wide. The only room left for a wider hole is the bearing itself. 9% a
       side left a 200px hole under a 243px plug; 3% leaves 228. The crossing deck and
       the snow laid over the joins are what hide a 7px seat, and they always did. */
    bearing: 0.03,
    /* THE PHASE ZOOM. The view eases in when a shape level opens so the instruction,
     * the blocks and the ditch are the whole picture, and eases back out when the run
     * resumes.
     *
     * 1.08 is not a taste call, it is the largest scale that keeps the puzzle on the
     * stage. Zooming about any point pushes the far edges outward, and the option row
     * already reaches to within 60px of the right edge: at 1.12 about the crossing the
     * rightmost block lands at x 1939 on a 1920 stage and is simply cut off. The
     * focus point is solved from that constraint in viewFocus() rather than picked, so
     * the framing cannot silently clip a block when the row width changes.
     *
     * zoomMs is slow on the way in — the world settling towards the puzzle reads as
     * the camera taking an interest — and quicker on the way out, because by then the
     * player wants to be running again. */
    zoomK: 1.08, zoomInMs: 900, zoomOutMs: 520,
    /* The most rocks one stretch may hold. Four at pairScale sits inside the run-up
       the stretch allows; beyond that they arrive faster than the jump recovers and it
       stops being a curve and becomes a wall. */
    maxRocks: 4,
    /* A FLOOR, BUT IT MUST NEVER EXCEED THE BRIDGE. It was 250 on the reasoning that
       a narrower gap reads as a crack rather than a crevasse — and at 250 it floored
       the six-option phases above their own pieces (198 and 162 wide), so the ditch
       came out 52-88px longer than the thing meant to span it. A floor that breaks
       the bridge is worse than a narrow gap.

       130 is below every piece the row can produce, so it only ever catches a
       degenerate case. The hard phases now have visibly smaller ditches than the
       easy ones, which is the variation that was asked for — and three of them in a
       row still reads as a broken stretch rather than a step. */
    ditchMin: 130,
    ditchGap: 150,         // ice island between two crevasses; wider, so a three-hole stretch reads longer
    /* THE MOUTH AND THE THROAT. The hole a piece plugs cannot be wider than the piece,
       and the piece cannot be taller than the 234px cavity, so a crevasse cut straight
       down was stuck at about 230px across — and it read as a slot, not a gap. A real
       crevasse is not straight-walled: it opens wide in the snow and ice and narrows
       below. So the hole has two widths now. The MOUTH, what the eye reads as the gap
       and what the platform art is cut back to, is `mouth` times the plug width; the
       THROAT, `throatDepth` below the walking line, is plug width minus the bearing,
       and that is where the answer wedges. The deck then closes the mouth over it.
       1.6 makes the VOID under a 3-option crossing about 366px across under a 229px neck. The rest
       of the shape is the overhang: from throatDepth the walls curl out to the void.
       Nothing is drawn around the plug; its flat edge spans the neck (see _ditchPath). */
    mouth: 1.6,
    throatDepth: 36,
    /* How far past the character the near lip opens — and, because the option row is
       centred on the crevasse, what decides how BIG an option can be.

       The row is symmetric about the crevasse and cannot reach left of
       mammothX + clearOfPlayer, so its half-width is (crevasse centre - 770). Pushing
       the crevasse right widens the row on both sides: at 240 a three-option chunk
       came out 177px wide against a 620px hole, which read as three pebbles beside a
       chasm. At 470 the same chunk is about 270px.

       It is capped so the FAR lip can never leave the stage — see layoutPhase — which
       is what stops a two-crevasse phase being pushed off the right edge. */
    clearance: 470,
    // no option may hang left of mammothX + this: a cut chunk falls toward the hole,
    // and one that hung over the character dropped ice on its head
    clearOfPlayer: 340,
    /* Deeper, because raising the walking line made room. The ice walls above the
       water now read 190px instead of 152, which is most of what makes the crevasse
       look like a crack rather than a notch. */
    waterDepth: 190,       // open water at the foot of the ice shelf
    slabW: 340, slabH: 132,
    /* The box a hanging chunk is fitted into. Nearly square rather than the old
       wide-and-flat slab, because a chunk is now scaled UNIFORMLY into it: a
       non-uniform fit gives a regular polygon unequal sides, and regularity is one
       of the things this curriculum teaches. optionH is what sets a chunk's size in
       a three-option phase; a five- or six-option row runs out of width first. */
    /* TIED TO THE CREVASSE, not chosen freely. A chunk is fitted uniformly into
       optionBox's w x h, so this is what caps a chunk's HEIGHT — and it is set to
       exactly the room between the walking line and the bottom of the stage
       (CFG.H - surfaceY - 6 = 234). That is what makes a correct shape land at 1:1:
       the block cannot be taller than the hole it has to sit in, so it never has to be
       scaled to get there. Raise it and plugs start being shrunk again. */
    optionH: 234,
    optionMargin: 20,      // clear air between neighbours, so no two chunks overlap
    rigY: 150,             // the line the ropes hang from, inside the fog bank
    /* HOW HIGH THE BLOCKS HANG. 470 left the lowest block edge at y 587 with the
       surface at 840 — 253px of empty sky between the blocks and the ground they are
       suspended over, which reads as floating rather than as hanging above a hole.
       600 closes that to about 100px: still clear of the ice, still leaving a long
       run of rope above so it plainly comes from off the top of the frame, but near
       enough that the block and the hollow beneath it belong to each other.

       DO NOT PUSH THIS PAST 746. drawHangingShapes splits into two passes at
       surfaceY - SHAPE_H * 0.4, and anything below that line is drawn BEHIND the ice
       platform so a chunk falling into a hole is properly occluded by its lip. A
       hanging block whose centre crossed that line would vanish behind the platform
       while still up in the air. */
    /* 470, from 600. The reference has the shapes hanging HIGH, in the upper third,
       on long ropes over the crossing — the blocks were sitting halfway down the
       stage on short ropes, which made the row read as a shelf. Higher also puts
       clear air between the row and the crevasse it is about. */
    optionY: 470,          // centre of a hanging chunk: far enough below the rig that
                           // there is a real length of rope to cut
    dropGravity: 2600,
    bridgeMs: 620,         // how long the ice takes to grow out to the wedged slab
    phases: [
      /* THE CURRICULUM. Seven crossings, and the whole progression is data: the
         engine reads it and never asks which phase it is playing.

           targets / distractors  internal GEOMETRY IDS, resolved through
                                  polygons.js. A phase wants every id in `targets`,
                                  cut in any order.
           ditches                how many crevasses open (1 or 2). NOT how many
                                  answers the phase wants: the repair slots are
                                  shared out across whatever crevasses there are.
           rotate                 an orientation challenge only. Side count does not
                                  depend on rotation, so this can never change what
                                  a shape IS.

         1-3 teach recognition from clean regular examples. 4 asks for a hexagon
         that happens to be irregular, 5 for a heptagon that happens to be concave.
         6 and 7 ask for EVERY pentagon and EVERY hexagon across regular,
         irregular-convex and concave examples - the lesson being that the number of
         sides is the only thing that decides. */
      { id: 1, ditches: 1, options: 3,
        targets: ['regularTriangle'],
        distractors: ['regularPentagon', 'regularHexagon'],
        rotate: 0, tutorial: true, swing: 0,
        instruction: 'Cut the triangle.' },

      { id: 2, ditches: 1, options: 3,
        targets: ['regularQuadrilateral'],
        distractors: ['regularTriangle', 'regularPentagon'],
        rotate: 0, swing: 0,
        instruction: 'Cut the quadrilateral.' },

      { id: 3, ditches: 1, options: 3,
        targets: ['regularPentagon'],
        distractors: ['regularTriangle', 'regularOctagon'],
        rotate: 0, swing: 0,
        instruction: 'Cut the pentagon.' },

      /* regularPentagon -> irregularPentagon closes a leak. The target here is an
         IRREGULAR hexagon, and with two regular distractors it was the only irregular
         shape in the row — so "cut the wonky one" passed this phase every time, without
         counting a single side. Phase 4 is the phase that introduces irregular shapes,
         so that shortcut defeated the exact lesson it exists to teach. An irregular
         distractor means irregularity no longer separates the answer from the rest and
         only the side count can. */
      { id: 4, ditches: 1, options: 3,
        targets: ['irregularConvexHexagon'],
        distractors: ['irregularPentagon', 'regularHeptagon'],
        rotate: 0, swing: 0,
        instruction: 'Cut the hexagon.' },

      /* irregularConvexHexagon -> concaveHexagon, for the same reason one phase up.
         The target is a CONCAVE heptagon and both distractors were convex, so it was
         the only concave shape in the row and "cut the dented one" always worked. A
         concave distractor puts the decision back on 7 against 6 and 8. */
      { id: 5, ditches: 1, options: 3,
        targets: ['concaveHeptagon'],
        distractors: ['concaveHexagon', 'irregularConvexOctagon'],
        rotate: 0, swing: 0,
        instruction: 'Cut the heptagon.' },

      /* TWO crevasses, and the reason it was once reduced to one no longer holds.

         It was changed to a single crevasse because three answers over two holes split
         2 and 1, and back then a plug was scaled so its width filled its SLOT — so one
         hole got two 215px plugs and the other a single 430px one, the same phase
         showing pieces of two different sizes for no reason a learner could see.

         A plug's size now comes from the CAVITY DEPTH and not from its slot width, so
         every plug is the same size however the slots are shared out. Two crevasses
         also widen the option row — the row is centred on the crevasse group, so a
         wider group means bigger, more countable shapes (a six-option chunk goes from
         127px to 142px).

         Three answers over two holes is the most the stage geometry allows; three
         separate unjumpable crevasses do not fit. Which answer lands in which hole is
         still not fixed: any wanted shape takes whichever free slot is nearest the cut. */
      { id: 6, ditches: 2, options: 5,
        targets: ['regularPentagon', 'irregularConvexPentagon', 'concavePentagon'],
        /* irregularHexagon -> concaveHexagon. Both distractors were convex while one
           of the three targets is a concave pentagon, so concavity identified one of
           the three answers for free. A concave distractor removes that. */
        distractors: ['concaveHexagon', 'regularQuadrilateral'],
        rotate: 0, swing: 0,
        instruction: 'Cut all the pentagons.' },

      { id: 7, ditches: 2, options: 6,
        targets: ['irregularConvexHexagon', 'concaveHexagon', 'regularHexagon'],
        distractors: ['concaveHeptagon', 'irregularPentagon', 'regularOctagon'],
        rotate: 0, swing: 0,
        instruction: 'Cut all the hexagons.' }
    ],
    // which phases are preceded by a rock to jump, so it never becomes every phase
    /* WHICH PHASES GET A ROCK STRETCH BEFORE THEM, and there are more of them now:
       with only two, the escalating count had nowhere to escalate to and topped out at
       two rocks. Six stretches let it run 2, 3, 4 and then hold at the cap, which is
       the curve that was asked for. Phase 1 has none: the tutorial teaches the jump on
       a single rock before any phase, and stacking a stretch in front of the first
       puzzle as well would put two rock runs back to back before any cutting. */
    jumpBefore: [2, 3, 4, 5, 6, 7],
    /* One entry per phase. A different phase count moves this array with it, and
       nothing else: every other per-phase number is inside the phase itself. */
    /* HOW LONG THE MAMMOTH RUNS before each crevasse. Roughly tripled from
       2600-3400ms: at that pace one puzzle ended and the next began before the run
       had established itself, and the sky — which advances with phases repaired —
       barely had time to move between them. Eight seconds is long enough to watch the
       journey and short enough that a learner never waits for the next thing to do. */
    runMs: [7500, 8500, 8000, 9000, 8000, 9000, 8500]
  },
  /* THE MUSIC BED. One looping track under everything.

     gain is deliberately low. It shares a bus with sounds that carry information — the
     rope parting, the wrong chunk hitting the water, the crossing sealing — and a bed
     loud enough to notice is loud enough to bury them. It also fades in rather than
     starting on the beat, because the first thing that happens after a tap should be
     the game, not a song.

     duck is how far it drops when the ice gives way, so the rumble owns that moment. */
  music: { src: 'assets/audio/bgm-ice-hunt.mp3', gain: 0.17, duck: 0.35, fadeMs: 2200 },

  /* RECORDED SOUND, over the top of the synthesised palette.

     The delivered files are all LONGER THAN THE EVENTS THEY ARE FOR — 5.2s of
     footsteps for a footfall, 2.0s of UI taps for one tap, a 3.0s whoosh for a 0.5s
     jump. Playing a whole file per event would overlap itself into mush. So a cue
     names a file and how long a bite to take out of it, and where from:

       onset   the file holds several separate hits. Their start times are found at
               load time from the waveform's own energy, and each play takes the next
               one round-robin — which also means a run cycle uses different footsteps
               in turn rather than the same one over and over.
       window  the file is one continuous sound and the cue plays it from `at`.

     `rate` is the spread of playback-rate jitter, because the same sample at the same
     pitch twice in a row is instantly recognisable as a sample.

     Cues with no file here keep the synthesised version: the skid, the shiver, the
     splash and the rope parting are all still generated. Nothing goes quiet if a file
     fails to load either — every cue falls back to the synth. */
  sfx: {
    step:   { src: 'assets/audio/freesound_community-foot_steps_snow_heavy-38297.mp3',
              mode: 'onset', dur: 0.40, gain: 0.42, rate: 0.10 },
    jump:   { src: 'assets/audio/dragon-studio-heavy-whoosh-06-414584.mp3',
              mode: 'onset', dur: 0.55, gain: 0.50, rate: 0.06 },
    land:   { src: 'assets/audio/universfield-ground-impact-352053.mp3',
              mode: 'onset', dur: 0.75, gain: 0.55, rate: 0.06 },
    // the shape wedging home: the heaviest thing in the game
    wedge:  { src: 'assets/audio/dragon-studio-heavy-boulder-thud-515257.mp3',
              mode: 'onset', dur: 1.10, gain: 0.62, rate: 0.05 },
    rumble: { src: 'assets/audio/themediaguy-earthquake-rumble-amp-cracking-379298.mp3',
              mode: 'window', at: 0, dur: 2.60, gain: 0.55, rate: 0.02 },
    ui:     { src: 'assets/audio/floraphonic-punchy-taps-ui-5-183901.mp3',
              mode: 'onset', dur: 0.22, gain: 0.45, rate: 0.08 }
  },
  /* WHERE THE HITS ARE, for the build that cannot work them out for itself.
     Filled in by tools/bake-onsets.mjs between the markers below — see SFX_HITS. */
  hint: { slotMs: 7000, idleMs: 13000, showMs: 1300 },
  cut: { vertexSnap: 34 },

  /* ---------------- THE COMEDY ----------------

     Every number the character's cartoon reactions are built from, in one place so
     the performance can be tuned without hunting through the renderer.

     WHY IT IS PROCEDURAL. The delivered art is three GIFs — run, jump, skid — and the
     shiver sheet was removed on request. So `SHAKE` had no frames of its own and, worse,
     exited on its FIRST FRAME: the state's exit test was `t > (F.shake ? F.shake/fps : 0)`,
     which with no sheet is `t > 0`. The mammoth reached the crevasse, was put into a
     fright state, and left it again before a single frame was drawn — there was no
     reaction to the hole at all.

     Rather than ask for more art, the fright is animated ON TOP of the frames that do
     exist: a knock-kneed sideways tremble, a nervous roll, and a jelly squash, all
     driven off one decaying amplitude. That is how a cartoon shiver is actually built,
     it costs no assets, and it cannot fall out of sync with a sheet because there is
     no sheet to sync to.

     NOTHING HERE TOUCHES GAMEPLAY. It is all in the draw transform and the particle
     layer: the collider is a fixed box around mammothX, the jump physics are global,
     and the cut hit test is against the rope. A learner cannot be made to miss by a
     wobble. */
  comedy: {
    /* THE HANGING SWAY. One shared angle for every option, pivoting from the rig line
       off the top of the screen — see rigSwing(). Slow and small: 1.3 degrees over a
       4.5s cycle carries the bottom of a block about 11px, which reads as weight on a
       rope without making a shape harder to count. Per-option phases were what made the
       row look messy, so there is deliberately no per-shape variation here at all. */
    swayHz: 0.22, swayRad: 0.022,
    tremorHz: 9.5,        // knock-knees frequency. Above ~12 it reads as video noise
    scareDecay: 1.35,     // seconds for a full fright to fall away
    shakeHoldMs: 1250,    // how long the fright state holds when there is no shake art
    peerQuiver: 0.17,     // the tremble never quite stops while he is over the hole
    recoilPx: 26,         // the double take: back off the lip...
    recoilMs: 260,
    peerPx: 15,           // ...then lean in for a look
    gulpEvery: 2.3,       // a swallow, so a long think never reads as a hung game
    sweatEvery: 0.42,
    wobbleX: 5.6,         // px of sideways knock at full fright, before sprite scale
    wobbleRot: 0.05,      // radians of nervous roll
    wobbleSq: 0.05,       // jelly squash, as a fraction
    /* A swipe that misses every rope makes the ropes it passed near jiggle, so a miss
       is never silent. The radius is wide on purpose — 240 is most of the 293px gap
       between two ropes in a three-option phase, so a stroke ANYWHERE in the row gets
       an answer, which is the whole point. */
    jiggleRadius: 240, jiggleDecay: 2.2
  },

  /* THE JUICE. What separates a platformer that feels good from one that merely
     works is almost never the animation — it is what happens in the ~150ms AROUND
     an impact. Three things do most of that work and all three were missing:

       hit-stop   the whole simulation stops dead for a few frames on impact. It
                  reads as weight, because a heavy thing meeting another heavy thing
                  is the one moment real motion briefly stops. This is the single
                  biggest change in here and it costs nothing to draw.
       punch      the view scales up a hair and settles, so the impact reaches the
                  frame itself and not only the object inside it.
       ring       one expanding hoop on the impact frame, which is the cheapest way
                  to say "that hit HERE" and reads even at phone size.

     NO PICKUP TOKENS. A spinning gold coin leaping out of each correct answer was
     tried and taken out on request. It was the most literally Mario thing in here and
     it was the wrong borrowing: a collectable implies a score, a score implies a
     counter, and this game deliberately has no HUD to put one in. It also put the one
     warm-yellow object in the world on top of the learner's answer at the exact
     moment the answer is the thing to look at. The reward beat is carried by what was
     already there and belongs to the ice: the glint ring, the frost, and the sound.

     Numbers are deliberately small. Hit-stop past ~120ms stops reading as impact
     and starts reading as a dropped frame; a punch past ~3% reads as the camera
     lurching. Everything here is scaled down or off under reduced motion. */
  juice: {
    stopWedge: 62,        // ms frozen when a correct chunk seats
    stopSplash: 44,       // ms frozen when a wrong chunk hits the water
    stopHit: 96,          // ms frozen when the character walks into the rock
    stopBreak: 110,       // ms frozen on the frame the ice gives way
    stopMax: 130,         // hard ceiling: no event may freeze longer than this
    punchWedge: 0.018, punchHit: 0.026, punchBreak: 0.03, punchWin: 0.022,
    punchMs: 300
  },
  colors: {
    paleIce: '#DDF7FF', lightIce: '#A9E7FA', cyanIce: '#68C9EE',
    edge: '#2D82B5', deepEdge: '#1B5E8C',
    snow: '#F5FCFF',
    amber: '#F2A93B', frost: '#EAF9FF'
  },
  phases: [
    /* light/dim describe the colour of the sky's own light and how much of it there
       is. Weather drawn over these skies takes its colour from here — a fixed white
       cloud over the night sky is why the first attempt at generated clouds had to be
       taken out again. */
    { key: 'bgDawn',         src: 'assets/sky/01-dawn.webp',          at: 0.00, label: 'Dawn',          light: [255, 216, 178], dim: 0.82 },
    { key: 'bgEarlyMorning', src: 'assets/sky/02-early-morning.webp', at: 0.10, label: 'Early morning', light: [255, 236, 208], dim: 0.94 },
    { key: 'bgMorning',      src: 'assets/sky/03-morning.webp',       at: 0.23, label: 'Morning',       light: [244, 252, 255], dim: 1.00 },
    { key: 'bgMidday',       src: 'assets/sky/04-midday.webp',        at: 0.38, label: 'Midday',        light: [255, 255, 255], dim: 1.00 },
    { key: 'bgAfternoon',    src: 'assets/sky/05-afternoon.webp',     at: 0.52, label: 'Afternoon',     light: [255, 246, 228], dim: 0.96 },
    { key: 'bgSunset',       src: 'assets/sky/06-sunset.webp',        at: 0.65, label: 'Sunset',        light: [255, 198, 154], dim: 0.80 },
    { key: 'bgDusk',         src: 'assets/sky/07-dusk.webp',          at: 0.78, label: 'Dusk',          light: [201, 203, 238], dim: 0.58 },
    { key: 'bgNight',        src: 'assets/sky/08-night.webp',         at: 0.90, label: 'Night',         light: [143, 166, 200], dim: 0.34 }
  ],
  /* NOT the curriculum. Every phase's instruction, targets and distractors live in
     CFG.levelOne.phases and nowhere else — this array used to carry a second copy of
     level 1's, which is how two definitions of the same level drift apart.

     It survives only for the PARKED level 2 (drafts/level-2.draft.js), which reads
     levels[1]; the first entry is a placeholder holding that index and is read by
     nothing. */
  levels: [
    { id: 1, mechanic: 'hanging-shape-cut' },
    { id: 2, instruction: 'Cut the shape along its diagonal.', mechanic: 'polygon-diagonal-cut', polygon: 'hexagon', sides: 6 }
  ]
};

const T = CFG.timing;
const C = CFG.colors;
const clamp = (v, a, b) => v < a ? a : v > b ? b : v;
const lerp = (a, b, t) => a + (b - a) * t;
const easeOut = t => 1 - Math.pow(1 - t, 3);
const easeInOut = t => t < 0.5 ? 4 * t * t * t : 1 - Math.pow(-2 * t + 2, 3) / 2;
const easeBackOut = t => { const c = 1.4; const u = t - 1; return 1 + (c + 1) * u * u * u + c * u * u; };
const rand = (a, b) => a + Math.random() * (b - a);

/* ---------------- geometry helpers ---------------- */
/* Deterministic hash from a world x, so no facet or icicle crawls between frames.
   At module scope because GroundManager needs it too — it used to live inside
   createGame(), where the ground manager (a top-level class) could not reach it. */
function iceHash(x, salt) {
  const v = Math.sin(x * 0.0173 + salt * 12.9898) * 43758.5453;
  return v - Math.floor(v);
}

function centroid(pts) {
  let x = 0, y = 0; for (const p of pts) { x += p.x; y += p.y; }
  return { x: x / pts.length, y: y / pts.length };
}
/* ---------------- PolygonFactory ----------------
   Polygon identity comes from geometry — the number of straight sides and corners —
   never from colour, size or rotation. Every shape is built as an ordered vertex
   ring inscribed in a w x h box, then optionally rotated and given a small radial
   jitter. Jitter is capped low enough that a convex ring stays convex, so the
   factory can never emit a self-intersecting or malformed polygon. */
export const PolygonFactory = {
  sides: { triangle: 3, square: 4, rectangle: 4, quadrilateral: 4, trapezoid: 4, pentagon: 5, hexagon: 6 },

  /** The ring for a name, or null if it is not one of ours.

      THE ARTWORK'S OWN OUTLINE COMES FIRST. The options are painted ice blocks now,
      and the engine does everything from the ring: it seats the block flat-side up,
      swells it until that edge spans the crevasse, clips it to the hole, and hangs the
      rope from the middle of its top edge. If the ring were polygons.js's ideal
      geometry while the picture was a hand-drawn version of it, the rope would attach
      to thin air and the plug would not fit. So the ring is the one traced off the
      picture, and polygons.js remains the fallback and the independent check. */
  verified(kind) {
    const art = optionShapes[kind];
    if (art && art.points && art.points.length >= 3) return art.points;
    const pts = verifiedPoints(kind);
    return pts && pts.length >= 3 ? pts : null;
  },

  /** The delivered block for a name: its texture and the box the ring fills. */
  art(kind) { return optionShapes[kind] || null; },

  /** Whether a name resolves to a real polygon at all — used to fail loudly on a
      typo in the curriculum rather than silently drawing the fallback pentagon. */
  knows(kind) { return !!this.verified(kind) || this.sides[kind] !== undefined; },

  /** Vertex count that defines this polygon. Taken from the artwork's own traced ring
      where there is artwork, because that is what is on screen to be counted; the
      build refuses to generate a ring whose count disagrees with polygons.js. */
  sidesOf(kind) {
    const art = optionShapes[kind];
    if (art) return art.sides;
    return verifiedSides(kind) || this.sides[kind] || 0;
  },

  /** Regular-ish ring for an n-gon, flat side up, inscribed in w x h. */
  ring(n, w, h, flatTop) {
    const pts = [];
    // start angle puts a flat edge along the top when asked
    const a0 = flatTop ? -Math.PI / 2 - Math.PI / n : -Math.PI / 2;
    for (let i = 0; i < n; i++) {
      const a = a0 + (i * 2 * Math.PI) / n;
      pts.push({ x: Math.cos(a), y: Math.sin(a) });
    }
    return this.fit(pts, w, h);
  },

  /** Scale a unit-ish ring so its bounds exactly fill w x h, centred on origin. */
  fit(pts, w, h) {
    const b = polyBounds(pts);
    const sx = b.w > 0 ? w / b.w : 1;
    const sy = b.h > 0 ? h / b.h : 1;
    const cx = (b.x0 + b.x1) / 2, cy = (b.y0 + b.y1) / 2;
    return pts.map(p => ({ x: (p.x - cx) * sx, y: (p.y - cy) * sy }));
  },

  /** Rotate a ring by degrees about the origin. */
  turn(pts, deg) {
    const r = deg * Math.PI / 180, c = Math.cos(r), s = Math.sin(r);
    return pts.map(p => ({ x: p.x * c - p.y * s, y: p.x * s + p.y * c }));
  },

  /** Scale a ring UNIFORMLY so it fits INSIDE w x h, centred on the origin. Unlike
      fit(), which stretches a ring to fill the box exactly, this preserves the
      shape's proportions — so equal sides stay equal and a regular polygon stays
      regular. Every verified geometry goes through here. */
  fitInside(pts, w, h) {
    const b = polyBounds(pts);
    const k = Math.min(b.w > 0 ? w / b.w : 1, b.h > 0 ? h / b.h : 1);
    const cx = (b.x0 + b.x1) / 2, cy = (b.y0 + b.y1) / 2;
    return pts.map(p => ({ x: (p.x - cx) * k, y: (p.y - cy) * k }));
  },

  /** Build a named polygon. opt: { rotate (deg), irregular (0..0.16) } */
  make(kind, w, h, opt) {
    const o = opt || {};
    /* A VERIFIED geometry is used exactly as defined: scaled uniformly to fit the
       box, and rotated if the phase asks for an orientation challenge. `irregular`
       is deliberately ignored here — radial jitter on a shape that was built to be
       concave, or to be irregular in a specific checked way, would change the very
       property it exists to demonstrate, and could push it past its verification. */
    const ver = this.verified(kind);
    if (ver) {
      const pts = this.fitInside(ver, w, h);
      return o.rotate ? this.turn(pts, o.rotate) : pts;
    }
    let pts;
    switch (kind) {
      case 'triangle': pts = [{ x: 0, y: -h / 2 }, { x: w / 2, y: h / 2 }, { x: -w / 2, y: h / 2 }]; break;
      case 'square': { const s = Math.min(w, h) / 2; pts = [{ x: -s, y: -s }, { x: s, y: -s }, { x: s, y: s }, { x: -s, y: s }]; break; }
      case 'rectangle':
      case 'quadrilateral': pts = [{ x: -w / 2, y: -h / 2 }, { x: w / 2, y: -h / 2 }, { x: w / 2, y: h / 2 }, { x: -w / 2, y: h / 2 }]; break;
      case 'trapezoid': pts = [{ x: -w * 0.29, y: -h / 2 }, { x: w * 0.29, y: -h / 2 }, { x: w / 2, y: h / 2 }, { x: -w / 2, y: h / 2 }]; break;
      // shoulders high so the apex lands near a regular pentagon's 108 degrees
      case 'pentagon': pts = [{ x: -w / 2, y: -h / 2 }, { x: w / 2, y: -h / 2 }, { x: w / 2, y: -h * 0.1 }, { x: 0, y: h / 2 }, { x: -w / 2, y: -h * 0.1 }]; break;
      case 'hexagon': pts = [{ x: -w * 0.27, y: -h / 2 }, { x: w * 0.27, y: -h / 2 }, { x: w / 2, y: 0 },
                             { x: w * 0.27, y: h / 2 }, { x: -w * 0.27, y: h / 2 }, { x: -w / 2, y: 0 }]; break;
      default: pts = this.ring(5, w, h, true);
    }

    // controlled irregularity: nudge each vertex along its own radius only, which
    // keeps the winding order and cannot cross an edge at these magnitudes
    const jit = clamp(o.irregular || 0, 0, 0.16);
    if (jit > 0) {
      let seed = (o.seed || 1) * 9277 + 1;
      const rnd = () => (seed = (seed * 9301 + 49297) % 233280) / 233280;
      pts = pts.map(p => {
        const k = 1 + (rnd() * 2 - 1) * jit;
        return { x: p.x * k, y: p.y * k };
      });
    }

    if (o.rotate) pts = this.turn(pts, o.rotate);
    return pts;
  },

  /** Re-centre on the bounding box, so a shape's centre is also its geometric middle
      even after irregular jitter has pushed vertices around. */
  center(pts) {
    const b = polyBounds(pts);
    const cx = (b.x0 + b.x1) / 2, cy = (b.y0 + b.y1) / 2;
    return pts.map(p => ({ x: p.x - cx, y: p.y - cy }));
  },

  /** A chunk of glacier ice in the shape being asked about: canonical orientation
      (a triangle points up, a trapezoid has its short side up), re-centred, and
      never pre-rotated — display rotation is applied by the renderer so a chunk can
      right itself on the way down. */
  chunk(kind, w, h, opt) {
    return this.center(this.make(kind, w, h, Object.assign({}, opt, { rotate: 0 })));
  },

  /* How a chunk should SIT in a gap.
     Returns the rotation that puts the polygon's longest edge horizontal along the
     TOP, and the scale that makes that edge span `span`. A flat side up gives the
     character something to cross, and for a triangle it puts the single point down,
     which is how a wedge actually sits. Scaling is uniform: the piece stays the shape
     the learner picked, rather than being stretched to plug a hole. */
  seat(pts, span) {
    let bi = 0, best = -1;
    for (let i = 0; i < pts.length; i++) {
      const a = pts[i], b = pts[(i + 1) % pts.length];
      const len = Math.hypot(b.x - a.x, b.y - a.y);
      if (len > best) { best = len; bi = i; }
    }
    const a = pts[bi], b = pts[(bi + 1) % pts.length];
    // rotate that edge to horizontal
    let rot = -Math.atan2(b.y - a.y, b.x - a.x);
    const turn = (r) => pts.map(q => ({
      x: q.x * Math.cos(r) - q.y * Math.sin(r),
      y: q.x * Math.sin(r) + q.y * Math.cos(r)
    }));
    // ...and make sure it ends up at the top, not the bottom
    let out = turn(rot);
    const edgeY = (out[bi].y + out[(bi + 1) % out.length].y) / 2;
    const cy = polyBounds(out).y0 + polyBounds(out).h / 2;
    if (edgeY > cy) { rot += Math.PI; out = turn(rot); }
    return { rot, scale: best > 0 ? span / best : 1, pts: this.center(out) };
  },

  /** The edge a seated shape is resting its top on: the one whose midpoint is
      highest. For anything that has been through seat() this is the flat top, and its
      length is what has to span the crevasse. */
  topEdge(pts) {
    let bi = 0, best = Infinity;
    for (let i = 0; i < pts.length; i++) {
      const a = pts[i], b = pts[(i + 1) % pts.length];
      const my = (a.y + b.y) / 2;
      if (my < best) { best = my; bi = i; }
    }
    const a = pts[bi], b = pts[(bi + 1) % pts.length];
    return { i: bi, len: Math.hypot(b.x - a.x, b.y - a.y) };
  },

  /** Width of a built ring, used to size a ditch to the shape that repairs it. */
  widthOf(pts) { return polyBounds(pts).w; }
};

function shapePoly(kind, w, h) {
  const hw = w / 2, hh = h / 2;
  switch (kind) {
    // Shoulders sit high so the two lower edges meet at ~107 degrees — close to a
    // regular pentagon's 108. With the old shoulders at +hh*0.25 the apex was 146
    // degrees, near enough to flat that the shape read as a quadrilateral.
    case 'pentagon': return [{ x: -hw, y: -hh }, { x: hw, y: -hh }, { x: hw, y: -hh * 0.2 }, { x: 0, y: hh }, { x: -hw, y: -hh * 0.2 }];
    case 'trapezoid': return [{ x: -hw * 0.58, y: -hh }, { x: hw * 0.58, y: -hh }, { x: hw, y: hh }, { x: -hw, y: hh }];
    case 'hexagon': return [{ x: -hw * 0.55, y: -hh }, { x: hw * 0.55, y: -hh }, { x: hw, y: 0 }, { x: hw * 0.55, y: hh }, { x: -hw * 0.55, y: hh }, { x: -hw, y: 0 }];
    case 'triangle': return [{ x: 0, y: -hh }, { x: hw, y: hh }, { x: -hw, y: hh }];
    case 'square': return [{ x: -hh, y: -hh }, { x: hh, y: -hh }, { x: hh, y: hh }, { x: -hh, y: hh }];
    default: return [{ x: -hw, y: -hh }, { x: hw, y: -hh }, { x: hw, y: hh }, { x: -hw, y: hh }];
  }
}
function regularHexagon(R) {
  const pts = [];
  for (let i = 0; i < 6; i++) { const a = (i * 60) * Math.PI / 180; pts.push({ x: R * Math.cos(a), y: R * Math.sin(a) }); }
  return pts;
}
function traceRing(ctx, pts, ox = 0, oy = 0) {
  ctx.beginPath();
  pts.forEach((p, i) => i ? ctx.lineTo(p.x + ox, p.y + oy) : ctx.moveTo(p.x + ox, p.y + oy));
  ctx.closePath();
}
function polyBounds(pts) {
  let x0 = 1e9, y0 = 1e9, x1 = -1e9, y1 = -1e9;
  for (const p of pts) { x0 = Math.min(x0, p.x); y0 = Math.min(y0, p.y); x1 = Math.max(x1, p.x); y1 = Math.max(y1, p.y); }
  return { x0, y0, x1, y1, w: x1 - x0, h: y1 - y0 };
}
function segIntersect(a, b, c, d) {
  const d1 = (b.x - a.x) * (c.y - a.y) - (b.y - a.y) * (c.x - a.x);
  const d2 = (b.x - a.x) * (d.y - a.y) - (b.y - a.y) * (d.x - a.x);
  const d3 = (d.x - c.x) * (a.y - c.y) - (d.y - c.y) * (a.x - c.x);
  const d4 = (d.x - c.x) * (b.y - c.y) - (d.y - c.y) * (b.x - c.x);
  return ((d1 > 0) !== (d2 > 0)) && ((d3 > 0) !== (d4 > 0));
}

/* Measures an image's actual opaque bounds once, so art can be seated on the ground
   exactly without hand-tuning a contentBottom constant for every new asset. */
function measureContent(img) {
  if (!img || !img.width) return null;
  const c = document.createElement('canvas');
  c.width = img.width; c.height = img.height;
  const g = c.getContext('2d');
  g.drawImage(img, 0, 0);
  let d;
  try {
    d = g.getImageData(0, 0, c.width, c.height).data;
  } catch (e) {
    /* THE WHOLE IMAGE, rather than nothing.

       Drawing a file:// image onto a canvas TAINTS it, so getImageData throws a
       SecurityError whenever index.html is opened off the disk. This used to return
       null, and the only caller — ObstacleController — treats null as "skip this
       art", so it ended up with an empty `kinds` list: the rocks were invisible while
       still colliding, which is about the worst way for that to fail.

       Falling back to the full image rect means the crop includes the art's own
       transparent padding, so the rock is normalised to CFG.obstacle.height including
       that padding and comes out a little smaller on screen. That is a cosmetic
       difference in the file:// build only, and it is a great deal better than a rock
       you cannot see. Served over http:// this branch is never taken. */
    return {
      x0: 0, x1: c.width - 1, y0: 0, y1: c.height - 1,
      w: c.width, h: c.height, bottom: 1, approx: true
    };
  }
  let x0 = 1e9, x1 = -1, y0 = 1e9, y1 = -1;
  for (let y = 0; y < c.height; y++) {
    for (let x = 0; x < c.width; x++) {
      const i = (y * c.width + x) * 4;
      if (d[i + 3] > 40) {
        if (x < x0) x0 = x; if (x > x1) x1 = x;
        if (y < y0) y0 = y; if (y > y1) y1 = y;
      }
    }
  }
  if (x1 < 0) return null;
  return { x0, x1, y0, y1, w: x1 - x0 + 1, h: y1 - y0 + 1, bottom: (y1 + 1) / c.height };
}

/* ---------------- ice material painter ---------------- */
// A solid, high-contrast variant for the pieces the learner actually picks up. The
// default pale ice all but disappeared against a bright cyan sky.
const ICE_PIECE = { top: '#FFFFFF', mid: '#BFE7FA', bot: '#5FBEE6', edge: '#2A6E9E', lw: 5, lift: true };
function paintIce(ctx, pts, opt = {}) {
  const b = polyBounds(pts);
  const g = ctx.createLinearGradient(0, b.y0, 0, b.y1);
  g.addColorStop(0, opt.top || C.paleIce);
  g.addColorStop(0.55, opt.mid || C.lightIce);
  g.addColorStop(1, opt.bot || C.cyanIce);
  ctx.save();
  const lift = opt.lift ? 1.7 : 1;
  ctx.shadowColor = `rgba(9,42,80,${0.35 * lift})`;
  ctx.shadowBlur = 18 * lift; ctx.shadowOffsetY = 8 * lift;
  traceRing(ctx, pts); ctx.fillStyle = g; ctx.fill();
  ctx.restore();
  // internal facet
  ctx.save();
  traceRing(ctx, pts); ctx.clip();
  ctx.beginPath();
  ctx.moveTo(b.x0 + b.w * 0.18, b.y0 - 10);
  ctx.lineTo(b.x0 + b.w * 0.52, b.y1 + 10);
  ctx.lineTo(b.x0 + b.w * 0.30, b.y1 + 10);
  ctx.lineTo(b.x0 - 10, b.y0 + b.h * 0.42);
  ctx.closePath();
  ctx.fillStyle = 'rgba(255,255,255,0.34)'; ctx.fill();
  ctx.beginPath();
  ctx.moveTo(b.x1 - b.w * 0.10, b.y0 - 10);
  ctx.lineTo(b.x1 + 10, b.y0 + b.h * 0.30);
  ctx.lineTo(b.x1 + 10, b.y1 + 10);
  ctx.lineTo(b.x1 - b.w * 0.34, b.y1 + 10);
  ctx.closePath();
  ctx.fillStyle = 'rgba(45,130,181,0.16)'; ctx.fill();
  ctx.restore();
  ctx.lineJoin = 'round'; ctx.lineCap = 'round';
  traceRing(ctx, pts);
  ctx.strokeStyle = opt.edge || C.edge; ctx.lineWidth = opt.lw || 4; ctx.stroke();
  // frost highlight along top edge
  ctx.save();
  traceRing(ctx, pts); ctx.clip();
  ctx.beginPath();
  ctx.moveTo(b.x0, b.y0 + 6); ctx.lineTo(b.x1, b.y0 + 6);
  ctx.strokeStyle = 'rgba(255,255,255,0.65)'; ctx.lineWidth = 5; ctx.stroke();
  ctx.restore();
}

/* ---------------- AudioManager ----------------
   All sound is synthesised — no audio files to load, nothing to go missing, and the
   whole palette is tuned together. Two rules keep it feeling like a game rather than
   a pile of beeps:

     * everything pitched sits on a C major pentatonic scale, so no two sounds
       playing at once can clash, and rewards can climb the scale as the learner
       gets further;
     * every hit has a body (a short noise burst shaped by a filter) AND a voice (a
       pitched blip), because a game sound that is only one of the two reads as
       either a thud or a beep.

   Nothing here waits on user input except the AudioContext itself, which browsers
   will not start until a gesture — start() is called from the first tap. */
/* THE ONSET TIMES, BAKED.
 *
 * A recorded cue takes a short bite out of a file that is much longer than the event —
 * 5.2s of footsteps for one footfall — starting at a hit. AudioManager._onsets() finds
 * those hits from the waveform's own energy, which needs the file decoded, which needs
 * fetch + decodeAudioData.
 *
 * A file:// page has neither. fetch against file:// is refused outright, so opening
 * index.html off the disk — which is the supported way to run this game — used to lose
 * all six delivered recordings and fall back to the synthesised palette without saying
 * so. The files never change, though, so the analysis does not have to happen at run
 * time: tools/bake-onsets.mjs runs the game's own _onsets over http once and writes the
 * numbers in here, and the disk build plays the same bites through <audio> elements,
 * which need no decoding at all.
 *
 * Regenerate with:  node tools/bake-onsets.mjs && node tools/build-bundle.mjs
 */
/* BAKED-ONSETS-START */
export const SFX_HITS = {
  step: [0.12, 1.28, 2.67, 3.97],
  jump: [0.2],
  land: [0.32],
  wedge: [0.32, 0.74],
  rumble: [0],
  ui: [0.01],
};
/* BAKED-ONSETS-END */

class AudioManager {
  constructor() { this.ctx = null; this.master = null; this.duck = 1; this.enabled = true; this.streak = 0; }

  /* THE SOUND KIT (js/sfx.js, supplied) — the cartoon voice for everything the six
     recordings do not cover.

     WHAT IT REPLACES. Every synthesised stand-in below that the kit has a better
     recipe for now goes through the kit first: bonk, slice, the splat of a chunk
     hitting the water, the falling whistle, the bloop of a chunk arriving, the
     boings, the whiff of a missed jump, the glints, the prize, the chord for a right
     answer, the level fanfare, the rock's approach tick, and the click and landing
     when the recordings are not available. The kit's recipes are measured — each
     carries a loudness trim derived offline (files/calibration.json), so the mix is
     balanced by measurement rather than by ear, and it caps concurrent copies of a
     sound at three with the oldest stolen, so a cue fired fifty times cannot pile
     up. Pitch is jittered on every shot, and everything pitched sits on one
     pentatonic key so no two cues can clash.

     WHAT IT DOES NOT REPLACE. The six delivered recordings stay primary for their
     events (a real footfall, whoosh, thud, rumble and tap); the kit is their
     fallback, never layered on top — layering was the "sounds overlap" complaint.
     The character's own comedy cues (gasp, gulp, toot, wobble, knees, double-take)
     stay on the local palette, which was tuned to the fright animation frame by
     frame. And the kit's sad trombone is never used: a wrong answer gets the soft
     `wrong`, because this game does not laugh at the learner.

     TWO CONTEXTS, ONE SWITCH. The kit owns its AudioContext and this manager owns
     the recordings and the music bed in another; the sound toggle mutes both, and
     the kit's master sits at 0.85 against this one's 0.5, so the comedy leads the mix and
     the recordings sit under it. Music ducking stays here (setDuck), where the bed is. */
  kitBoot() {
    const K = window.SFX;
    if (this._kitReady || !K || typeof K.play !== 'function') return;
    try {
      if (typeof K.unlock === 'function') K.unlock();
      if (typeof K.key === 'function') K.key('C pentatonic');
      if (typeof K.configure === 'function') K.configure({ maxVoices: 3 });
      /* 0.85, not 0.5. At 0.5 the kit sat under the recordings and the bed and the game
         sounded polite; the ask was for the effects to be EVIDENT and comic. The kit has
         its own limiter and measured trims, so a hot master does not clip. */
      if (typeof K.volume === 'function') K.volume(0.85);
      if (typeof K.mute === 'function') K.mute(!this.enabled);
      this._kitReady = true;
    } catch (e) { /* the local palette below still plays */ }
  }
  /** Play a kit cue; false when the kit is absent, so the caller falls through. */
  kit(name, opts) {
    const K = window.SFX;
    if (!this.enabled || !K || typeof K.play !== 'function') return false;
    if (!this._kitReady) this.kitBoot();
    try { K.play(name, opts); return true; } catch (e) { return false; }
  }
  kitMute(m) {
    const K = window.SFX;
    if (K && typeof K.mute === 'function') { try { K.mute(!!m); } catch (e) { /* no kit */ } }
  }
  /** A speech bubble arriving. */
  popIn() { if (this.kit('pop')) return; this.bloop(); }
  /** A stamp landing on the ending panel — a coin, because it is a collection. */
  stamp() { if (this.kit('coin')) return; this._note(7, 0.12, 0.05, 'triangle'); }
  start() {
    if (this.ctx || !this.enabled) return;
    const AC = window.AudioContext || window.webkitAudioContext;
    if (!AC) { this.enabled = false; return; }
    this.ctx = new AC();
    /* 0.7, from 0.5: the six recordings carry gains of 0.42-0.62 and sat under the kit
       (master 0.85) so far that a footfall or the whoosh barely registered next to a boing.
       The compressor below is what keeps a hot master from clipping. */
    this.master = this.ctx.createGain(); this.master.gain.value = 0.7;

    // A gentle limiter on the bus. Several ice chips plus a splash plus a reward
    // arpeggio can land in the same 200ms, and without this they add up and clip.
    const comp = this.ctx.createDynamicsCompressor();
    comp.threshold.value = -14; comp.knee.value = 22;
    comp.ratio.value = 5; comp.attack.value = 0.004; comp.release.value = 0.16;
    this.master.connect(comp); comp.connect(this.ctx.destination);

    // noise buffer, reused by every body
    const len = this.ctx.sampleRate * 2;
    const buf = this.ctx.createBuffer(1, len, this.ctx.sampleRate);
    const d = buf.getChannelData(0);
    for (let i = 0; i < len; i++) d[i] = Math.random() * 2 - 1;
    this.noise = buf;

    /* The music, routed through the SAME bus as everything else, which is what makes
       it obey the mute and the duck without any code of its own. A media element is
       used rather than a decoded buffer so a five-megabyte track streams instead of
       being held in memory, and it loops seamlessly because the element loops. */
    this.kitBoot();
    this.startMusic();
    this.loadSfx();

    // ambience: filtered noise wind, with a slow LFO so it breathes.
    // Quieter now there is a music bed: the two are both "the air", and at the old
    // level they fought each other.
    this.windGain = this.ctx.createGain(); this.windGain.gain.value = 0.034;
    const wf = this.ctx.createBiquadFilter(); wf.type = 'lowpass'; wf.frequency.value = 520; wf.Q.value = 0.6;
    const ws = this.ctx.createBufferSource(); ws.buffer = buf; ws.loop = true;
    ws.connect(wf); wf.connect(this.windGain); this.windGain.connect(this.master); ws.start();
    this.wind = ws;
    const lfo = this.ctx.createOscillator(); lfo.frequency.value = 0.09;
    const lg = this.ctx.createGain(); lg.gain.value = 0.03;
    lfo.connect(lg); lg.connect(this.windGain.gain); lfo.start();
  }
  /** The looping bed. Safe to call twice; does nothing without an AudioContext. */
  startMusic() {
    if (!this.ctx || this.music) return;
    const M = CFG.music;
    if (!M || !M.src) return;

    /* TWO WAYS TO PLAY THE BED, because off the disk only one of them works.
     *
     * The version before this one gave up entirely on file:// and the reasoning was
     * half right. It IS true that ctx.createMediaElementSource() needs CORS a file://
     * page cannot satisfy — that call taints the graph and the element goes silent. It
     * does NOT follow that the music cannot play, and that is the step that was missed:
     * the AudioContext is only there to give the bed its own fader. An <audio> element
     * loading a file next to the page plays perfectly well on its own.
     *
     * The cost of the shortcut was the whole soundtrack. Anyone opening index.html by
     * double-clicking it — which is the supported way to run this game — got silence,
     * with nothing logged to say why.
     *
     * So: routed through the graph where that is allowed, and played directly where it
     * is not. Everything downstream reads this.music.gain being null as "this one is
     * driven by element volume", so ducking and fading work either way. */
    const direct = typeof location !== 'undefined' && location.protocol === 'file:';
    try {
      const el = new Audio(M.src);
      el.loop = true;
      el.preload = 'auto';
      if (direct) {
        el.volume = 0;                        // faded in below
        this.music = { el, gain: null };
      } else {
        el.crossOrigin = 'anonymous';
        const src = this.ctx.createMediaElementSource(el);
        const g = this.ctx.createGain();
        g.gain.value = 0;                     // faded in below
        src.connect(g); g.connect(this.master);
        this.music = { el, gain: g };
      }
      // a browser will refuse this until a gesture; start() is called from the first tap
      const p = el.play();
      if (p && p.catch) p.catch(() => {});
      this._musicTo(M.gain, M.fadeMs);
    } catch (e) {
      this.music = null;                      // never let the bed break the game
    }
  }
  /* Load every cue's file once and find its hits. Fired from start(), so it happens
     after the first gesture and never blocks the art preload. A failure is silent by
     design: `this.sfx[name]` simply stays undefined and the cue keeps its synth. */
  async loadSfx() {
    if (!this.ctx || this.sfxLoading) return;
    /* NOT OFF THE DISK. fetch() refuses the file scheme outright — "URL scheme 'file'
       is not supported" — so opening index.html from disk logged one console error per
       cue for six cues that could never load. Every cue already falls back to the
       synthesised version when its file is missing, which is exactly the right
       behaviour here; this just stops the game asking for something it cannot have and
       filling the console on the way. */
    if (typeof location !== 'undefined' && location.protocol === 'file:') {
      /* OFF THE DISK THE RECORDINGS STILL PLAY — they just cannot go through the graph.
         fetch + decodeAudioData are both refused here, so instead each cue gets a small
         pool of <audio> elements, which load a neighbouring file perfectly well. A play
         seeks to a baked hit and stops after the cue's own duration, which is the same
         bite the decoded path takes; the pool is what lets two footfalls overlap.

         ONE ELEMENT PER CUE, not a pool. A pool of three was tried first, so that two
         footfalls could overlap — and three elements pointed at the same src start three
         concurrent loads of the same file, which the browser resolves by ABORTING the
         redundant ones. That is a real failed request each time, and the disk-build test
         rightly refuses to pass with any. Overlap is worth very little here anyway: the
         cues that repeat quickly are footsteps, which are sequential by nature, and a
         re-triggered footstep restarting is indistinguishable from a new one.

         What is lost against the http build: the per-play pitch jitter (an element has
         playbackRate but shifting pitch with it is a different effect), sample-accurate
         scheduling, and overlapping repeats. What is gained is the delivered sound
         instead of none. */
      this.sfxLoading = true;
      this.sfxEl = {};
      for (const [name, cue] of Object.entries(CFG.sfx || {})) {
        const el = new Audio(cue.src);
        el.preload = 'auto';
        el.volume = Math.min(1, cue.gain || 0.5);
        this.sfxEl[name] = { cue, hits: SFX_HITS[name] || [cue.at || 0], el, next: 0 };
      }
      return;
    }
    this.sfxLoading = true;
    this.sfx = this.sfx || {};
    const byUrl = new Map();
    for (const [name, cue] of Object.entries(CFG.sfx || {})) {
      try {
        if (!byUrl.has(cue.src)) {
          byUrl.set(cue.src, (async () => {
            const res = await fetch(cue.src);
            if (!res.ok) throw new Error(res.status + ' ' + cue.src);
            return this.ctx.decodeAudioData(await res.arrayBuffer());
          })());
        }
        const buf = await byUrl.get(cue.src);
        this.sfx[name] = { cue, buf, hits: cue.mode === 'onset' ? this._onsets(buf) : [cue.at || 0], next: 0 };
      } catch (e) {
        /* left undefined on purpose — the synthesised cue takes over */
      }
    }
  }

  /** Where the separate hits are in a file, from the waveform's own energy.

      A short-window RMS envelope, then every point where it climbs past a fraction of
      the file's peak having been quiet just before. That is what makes one 5-second
      recording of footsteps usable as a footstep: the alternative is guessing evenly
      spaced offsets, and half of those land in the silence between steps. */
  _onsets(buf) {
    const d = buf.getChannelData(0);
    const sr = buf.sampleRate;
    const win = Math.max(1, Math.round(sr * 0.01));
    const n = Math.floor(d.length / win);
    const env = new Float32Array(n);
    let peak = 0;
    for (let i = 0; i < n; i++) {
      let s = 0;
      for (let k = 0; k < win; k++) { const v = d[i * win + k]; s += v * v; }
      env[i] = Math.sqrt(s / win);
      if (env[i] > peak) peak = env[i];
    }
    if (peak <= 0) return [0];
    const open = peak * 0.24, shut = peak * 0.10;
    const hits = [];
    let armed = true, lastAt = -1;
    for (let i = 1; i < n; i++) {
      if (armed && env[i] > open) {
        const t = (i * win) / sr;
        // never two hits inside 90ms: that is one attack, not two
        if (lastAt < 0 || t - lastAt > 0.09) { hits.push(Math.max(0, t - 0.01)); lastAt = t; }
        armed = false;
      } else if (!armed && env[i] < shut) armed = true;
    }
    return hits.length ? hits : [0];
  }

  /** Play a cue from its file. Returns false if there is no sample for it. */
  _play(name) {
    if (this.sfxEl && this.sfxEl[name]) return this._playEl(name);
    const s = this.sfx && this.sfx[name];
    if (!s || !this.ctx) return false;
    const { cue, buf, hits } = s;
    const at = hits[s.next % hits.length];
    s.next++;
    const dur = Math.min(cue.dur, Math.max(0.02, buf.duration - at));
    if (dur <= 0.02) return false;
    const t = this.ctx.currentTime;
    const src = this.ctx.createBufferSource();
    src.buffer = buf;
    src.playbackRate.value = 1 + (Math.random() * 2 - 1) * (cue.rate || 0);
    const g = this.ctx.createGain();
    // a short ramp at each end, or slicing mid-waveform clicks
    const ramp = Math.min(0.012, dur / 4);
    g.gain.setValueAtTime(0, t);
    g.gain.linearRampToValueAtTime(cue.gain, t + ramp);
    g.gain.setValueAtTime(cue.gain, t + dur - ramp);
    g.gain.linearRampToValueAtTime(0, t + dur);
    src.connect(g); g.connect(this.master);
    src.start(t, at, dur);
    src.stop(t + dur + 0.02);
    return true;
  }

  /* One bite from the cue's element. The HIT still round-robins, so a run cycle uses
     each of the four recorded footsteps in turn rather than the same one over and over —
     which is most of what the onset slicing was for. */
  _playEl(name) {
    const s = this.sfxEl[name];
    if (!s || !this.enabled) return false;
    const el = s.el;
    const at = s.hits[s.next % s.hits.length];
    s.next++;
    try {
      el.currentTime = at;
      el.volume = Math.min(1, s.cue.gain || 0.5);   // effects are never ducked; only the bed is
      const p = el.play();
      if (p && p.catch) p.catch(() => {});
      clearTimeout(el.__stop);
      el.__stop = setTimeout(() => { try { el.pause(); } catch (e) { /* detached */ } },
                             Math.max(40, s.cue.dur * 1000));
    } catch (e) {
      return false;                            // a cue that will not play is not fatal
    }
    return true;
  }

  resume() {
    if (this.ctx && this.ctx.state === 'suspended') this.ctx.resume();
    if (this.music && this.music.el.paused && this.enabled) {
      const p = this.music.el.play();
      if (p && p.catch) p.catch(() => {});
    }
  }
  /* THE BED'S LEVEL, for both kinds of music handle. With a gain node it is a smooth
     ramp on the audio thread; without one there is no such thing for element volume, so
     it is stepped on a timer — 20 steps is well under what anyone hears as a stair, and
     the timer is replaced rather than stacked so two overlapping fades cannot fight. */
  _musicTo(target, ms) {
    const m = this.music;
    if (!m) return;
    if (m.gain) {
      m.gain.gain.setTargetAtTime(target, this.ctx.currentTime, Math.max(0.02, ms / 3000));
      return;
    }
    clearInterval(this._musicFade);
    const from = m.el.volume, steps = 20, dt = Math.max(16, ms / steps);
    let i = 0;
    this._musicFade = setInterval(() => {
      i++;
      const u = i / steps;
      try { m.el.volume = Math.max(0, Math.min(1, from + (target - from) * u)); } catch (e) { /* detached */ }
      if (i >= steps) clearInterval(this._musicFade);
    }, dt);
  }

  setDuck(v) {
    if (!this.master) return;
    /* THE MUSIC DUCKS; THE EFFECTS DO NOT. This used to scale the master (0.5 * v) as well,
       which pulled every recorded and synthesised cue down to 80% for the whole of a
       puzzle while the kit — in its own context — stayed at full. The fit sound, played
       during a puzzle, therefore sat at a different level from the same sound elsewhere:
       one of the two causes of it being heard as inconsistent. The note below already
       said the effects should stay where they are; now they do. */
    /* The music drops FURTHER than the bus does. Ducking everything equally just makes
       the whole mix quieter; pulling the bed down and leaving the sound effects where
       they are is what clears space for the ice cracking. */
    if (this.music) {
      const M = CFG.music;
      const want = v >= 1 ? M.gain : M.gain * (M.duck + (1 - M.duck) * v);
      this._musicTo(want, 200);
    }
    this.duck = v;
  }

  /* ---- primitives ---- */

  /** C major pentatonic, indexable in both directions from C5. */
  _hz(step) {
    const P = [0, 2, 4, 7, 9];
    const oct = Math.floor(step / 5), i = ((step % 5) + 5) % 5;
    return 523.25 * Math.pow(2, oct + P[i] / 12);
  }

  /** A noise body: the physical part of a hit. */
  _noise(dur, freq, type, gain, q, delay, sweepTo) {
    if (!this.ctx) return;
    const t = this.ctx.currentTime + (delay || 0);
    const s = this.ctx.createBufferSource(); s.buffer = this.noise;
    s.playbackRate.value = 0.8 + Math.random() * 0.4;      // never twice the same
    const f = this.ctx.createBiquadFilter();
    f.type = type || 'bandpass'; f.frequency.setValueAtTime(freq, t); f.Q.value = q || 1.2;
    if (sweepTo) f.frequency.exponentialRampToValueAtTime(Math.max(60, sweepTo), t + dur);
    const g = this.ctx.createGain();
    g.gain.setValueAtTime(0, t);
    g.gain.linearRampToValueAtTime(gain, t + 0.012);
    g.gain.exponentialRampToValueAtTime(0.0001, t + dur);
    s.connect(f); f.connect(g); g.connect(this.master);
    s.start(t); s.stop(t + dur + 0.05);
  }

  /** A pitched voice: the character of a hit. */
  _tone(freq, dur, gain, type, slide, delay) {
    if (!this.ctx) return;
    const t = this.ctx.currentTime + (delay || 0);
    const o = this.ctx.createOscillator(); o.type = type || 'sine';
    const g = this.ctx.createGain();
    o.frequency.setValueAtTime(freq, t);
    if (slide) o.frequency.exponentialRampToValueAtTime(Math.max(40, slide), t + dur);
    g.gain.setValueAtTime(0, t);
    g.gain.linearRampToValueAtTime(gain, t + 0.008);
    g.gain.exponentialRampToValueAtTime(0.0001, t + dur);
    o.connect(g); g.connect(this.master);
    o.start(t); o.stop(t + dur + 0.05);
  }

  /* A WOBBLING VOICE — the one thing the palette had no way to make, and the thing
     cartoon sound is built out of. A second oscillator drives the first one's FREQUENCY
     rather than its volume, so the pitch itself shakes: that is a boing, a sproing, a
     rubbery wobble, depending only on how fast and how deep.

     depth is in Hz of swing, rate in Hz of shake. A slide can run underneath it, which
     is what turns a wobble into a spring landing or a spring launching. */
  _warble(freq, dur, gain, type, slide, depth, rate, delay) {
    if (!this.ctx) return;
    const t = this.ctx.currentTime + (delay || 0);
    const o = this.ctx.createOscillator(); o.type = type || 'sine';
    o.frequency.setValueAtTime(freq, t);
    if (slide) o.frequency.exponentialRampToValueAtTime(Math.max(40, slide), t + dur);
    // the shake, decaying with the note so it does not buzz on the tail
    const lfo = this.ctx.createOscillator(); lfo.type = 'sine';
    lfo.frequency.setValueAtTime(rate || 14, t);
    const lg = this.ctx.createGain();
    lg.gain.setValueAtTime(depth || 40, t);
    lg.gain.exponentialRampToValueAtTime(0.5, t + dur);
    lfo.connect(lg); lg.connect(o.frequency);
    const g = this.ctx.createGain();
    g.gain.setValueAtTime(0, t);
    g.gain.linearRampToValueAtTime(gain, t + 0.01);
    g.gain.exponentialRampToValueAtTime(0.0001, t + dur);
    o.connect(g); g.connect(this.master);
    o.start(t); o.stop(t + dur + 0.05);
    lfo.start(t); lfo.stop(t + dur + 0.05);
  }

  /* A SLIDE WHISTLE. A pure tone gliding between two pitches with a breath of noise
     tracking it — the noise is most of why it reads as a whistle and not as a synth
     sweep. Up is anticipation, down is something on its way to a comic landing. */
  _slide(from, to, dur, gain, delay) {
    this._tone(from, dur, gain, 'sine', to, delay);
    this._tone(from * 2, dur, gain * 0.18, 'sine', to * 2, delay);   // a little air on top
    this._noise(dur, from * 1.4, 'bandpass', gain * 0.30, 6, delay, to * 1.4);
  }

  /** A note on the scale, optionally after a delay. Used for every reward. */
  _note(step, dur, gain, type, delay) {
    this._tone(this._hz(step), dur, gain, type || 'triangle', 0, delay);
    // a quiet octave above gives the blip some sparkle without raising the level
    this._tone(this._hz(step + 5), dur * 0.7, gain * 0.32, 'sine', 0, delay);
  }

  /* ---- world ---- */
  step() {
    if (this._play('step')) return;
    // snow crunch, alternating so a run cycle has a left/right feel
    this._alt = !this._alt;
    this._noise(0.075, this._alt ? 1250 : 880, 'bandpass', 0.055, 2.4);
  }
  jump() {
    /* The delivered whoosh is the weight and the boing is the comedy; they layer
       rather than replace, so the jump still sounds like a heavy animal leaving the
       ground and also like a cartoon. */
    this.boing();
    if (this._play('jump')) return;
    this._noise(0.22, 700, 'bandpass', 0.075, 0.9, 0, 2600);   // whoosh up
    this._tone(330, 0.17, 0.05, 'triangle', 700);              // the little "hup"
  }
  land() {
    this.boingDown();
    if (this._play('land')) return;
    if (this.kit('land')) return;
    this._noise(0.2, 420, 'lowpass', 0.13, 0.7, 0, 150);
    this._tone(150, 0.13, 0.05, 'sine', 90);
  }
  crystal() {
    if (this.kit('anticipate')) return;     // a rising 'uh-oh' as the rock comes into range
    // obstacle telegraph: two notes DOWN, so it reads as a warning, not a reward
    this._note(7, 0.16, 0.028, 'sine');
    this._note(4, 0.2, 0.022, 'sine', 0.1);
  }
  bonk() {
    if (this.kit('bonk')) return;
    this._tone(190, 0.24, 0.11, 'sine', 84);
    this._tone(96, 0.3, 0.07, 'square', 60);
    this._noise(0.14, 520, 'bandpass', 0.06, 1.1);
    this.sproing();                       // and it bounces off, because it is a cartoon
  }
  rumble() {
    if (this._play('rumble')) return;
    this._tone(52, 1.6, 0.17, 'sine', 32);
    this._tone(78, 1.2, 0.06, 'triangle', 40);
    this._noise(1.5, 190, 'lowpass', 0.1, 0.5, 0, 70);
  }
  crack() {
    this._noise(0.09, 5200, 'highpass', 0.16, 1.0);            // the snap
    this._noise(0.34, 2100, 'bandpass', 0.11, 3.2, 0.03);      // the tail
    this._tone(760, 0.11, 0.04, 'triangle', 240);
  }

  /* ---- the puzzle ---- */
  slice() {
    if (this.kit('slice', { vary: 0 })) return;          // the same snip every time
    // cutting the icicle stem: a bright shing, then the stem giving way
    this._noise(0.1, 6200, 'highpass', 0.11, 0.9);
    this._tone(1560, 0.09, 0.04, 'triangle', 2400);
    this._noise(0.2, 1500, 'bandpass', 0.06, 2.2, 0.05, 480);
  }
  /** The chunk seating across the chasm — heavy, and clearly a good outcome. The two
      notes on the scale stay even when the recorded thud plays: the thud is the weight
      and the notes are what say it was the RIGHT answer. */
  wedge() {
    /* CONSTANT EVERY TIME. This used to be the recorded boulder thud once it had
       finished decoding and a synth stand-in until then — so the first right answer
       of a session often sounded different from the second, reported as the fit sound
       'not being constant'. The kit's thud is synthesised, so it is always there and
       always the same; the recording is layered under it when it is ready, for body. */
    this.kit('land', { pitch: 0.72, volume: 0.9, vary: 0 });   // vary 0: identical every time
    this._play('wedge');
  }
  /** The ice bridging out and closing over: a rising frost shimmer. */
  seal() {
    this._noise(0.55, 3200, 'bandpass', 0.05, 1.0, 0, 7200);
    [0, 2, 4, 5].forEach((s, i) => this._note(s + 5, 0.22, 0.03, 'sine', i * 0.075));
  }
  /** A wrong chunk hitting the melt water. */
  splash() {
    if (this.kit('splat')) return;
    // the impact, then the water closing over it, then bubbles
    this._noise(0.13, 2600, 'bandpass', 0.15, 0.8, 0, 420);
    this._noise(0.42, 900, 'lowpass', 0.11, 0.6, 0.04, 260);
    this._tone(420, 0.22, 0.05, 'sine', 130);
    this._tone(190, 0.4, 0.04, 'sine', 70, 0.06);
    for (let i = 0; i < 4; i++) {
      this._tone(300 + Math.random() * 500, 0.1, 0.022, 'sine', 900, 0.18 + i * 0.075);
    }
  }
  plop() { this.splash(); }
  clunk() { this.wedge(); }
  /** A chunk arriving on its stem. */
  pop() { this.bloop(); }

  /* ---- rewards and refusals ---- */
  /** Phase cleared. Climbs the scale on a streak, so getting further sounds better. */
  /* THE FIT — the right answer landing. ONE sound, IDENTICAL in every phase: the kit's
     'correct' at a fixed pitch with the jitter off. It used to be the phase-done chord
     with a pitch that rose with the phase number and the kit's +/-5% jitter on top, and
     in the three-answer phases the first two fits got no chord at all — three reasons the
     fit did not sound the same from level to level. */
  fit() {
    if (this.kit('correct', { pitch: 1, vary: 0 })) return;
    this._note(0, 0.2, 0.05); this._note(4, 0.24, 0.045, 'triangle', 0.09);
  }
  /** The whole phase mended: a level-up, distinct from the per-fit chord. */
  success(streak = 0) {
    if (this.kit('levelUp', { vary: 0 })) return;
    const s = clamp(streak === undefined ? this.streak : streak, 0, 5);
    this.streak = s + 1;
    const base = s;
    [0, 2, 4, 7].forEach((iv, i) => this._note(base + iv, 0.34, 0.052, 'triangle', i * 0.085));
    this._noise(0.5, 4800, 'bandpass', 0.035, 1.2, 0.05);
  }
  /** Wrong answer. Soft and short: a nudge, never a buzzer. */
  reject() {
    if (this.kit('wrong')) return;
    this.streak = 0;
    this._note(2, 0.13, 0.05);
    this._note(0, 0.2, 0.042, 'triangle', 0.1);
    this._noise(0.12, 900, 'bandpass', 0.035, 1.4);
  }

  /* ---- interface ---- */
  ui() {
    if (this._play('ui')) return;
    if (this.kit('click')) return;
    this._tone(1050, 0.05, 0.05, 'triangle', 1500);
    this._noise(0.05, 3000, 'bandpass', 0.03, 2);
  }
  swap() { this._noise(0.24, 900, 'bandpass', 0.06, 0.9, 0, 3200); this._note(5, 0.18, 0.04); }
  fanfare() { if (this.kit('powerUp', { vary: 0 })) return; [0, 4, 7, 9, 12].forEach((iv, i) => this._note(iv, 0.4, 0.05, 'triangle', i * 0.08)); }

  /* ---- the comedy ----
     Four cues for the cartoon reactions. All synthesised: they are small, they have
     to be pitched against the ice palette rather than against a stock library, and a
     recorded gulp at a fixed pitch played twenty times a run is instantly a sample. */

  /** The fright, on the frame he sees the hole: a comical woodblock knock plus a
      swallowed squeak sliding DOWN, which is what reads as "oh no" rather than "ta-da". */
  gasp() {
    if (this.kit('squeak')) return;   // the fright, as a cartoon squeak
    /* Three layers over about a second and a half, which is roughly the length of the
       delivered fright sheet — so the sound lasts as long as the animation instead of
       being over before the character has finished reacting. */
    this.wobble();                                         // the knees going
    this.knees();                                          // and knocking together
    this.doubleTake();                                     // he looks, then looks again
    this._tone(880, 0.1, 0.05, 'triangle', 300);           // the squeak, sliding down
    this._noise(0.14, 1600, 'bandpass', 0.05, 3.4);         // the intake of breath
    this._tone(196, 0.16, 0.05, 'sine', 130, 0.05);
  }
  /** A swallow. Two short blips a semitone apart, low and soft — the classic gulp. */
  gulp() {
    this._tone(150, 0.07, 0.055, 'sine', 92);
    this._tone(122, 0.1, 0.045, 'sine', 78, 0.075);
  }
  /** A swipe that cut nothing. Air, and no pitch at all: a note would read as a
      verdict, and missing a rope is not a wrong answer. */
  whiff() {
    if (this.kit('swoosh')) return;
    this._noise(0.16, 1400, 'bandpass', 0.055, 0.7, 0, 420);
  }
  /** The mammoth, tapped. Its own voice — a little trumpet, up then up again. */
  toot() {
    if (this.kit('honk')) return;   // a trunk toot IS a honk
    this._tone(392, 0.14, 0.055, 'sawtooth', 523);
    this._tone(523, 0.2, 0.05, 'sawtooth', 587, 0.1);
    this._noise(0.1, 900, 'bandpass', 0.03, 1.2, 0.02);
  }
  /* THE WHOLE CROSSING MENDED. A rising phrase on the scale, ending held — the one
     unambiguously triumphant sound in the game, and the only place it plays.

     It is not the pickup ding it started as. That was a bright two-note square-wave
     blip fired on every single correct answer, i.e. a coin sound, and it went with the
     coins. On the ice palette a square wave that brash also sat outside the rest of
     the mix rather than on top of it; this is the same idea voiced in the game's own
     language, and it plays once per crossing instead of once per cut. */
  prize() {
    if (this.kit('gem')) return;
    [0, 4, 7, 12].forEach((iv, i) => {
      this._tone(this._hz(iv + 12), 0.14, 0.038, 'square', 0, i * 0.062);
    });
    this._tone(this._hz(19), 0.42, 0.03, 'triangle', 0, 0.25);
  }
  /* ---- the cartoon layer ----

     A note on where these are ALLOWED to fire, because it is a design rule and not a
     preference: the comedy lands on the WORLD and on the CHARACTER — jumps, bumps,
     wobbles, things falling in water — and never on the learner being wrong. A sad
     trombone on a wrong answer is the obvious cartoon joke and it is the one cue this
     game must not have: the child is the one who was wrong, and a laugh at that moment
     is a laugh at them. reject() stays the soft two-note nudge it has always been. */

  /** The spring in a cartoon jump: pitch shooting up while it shakes. */
  boing() {
    if (this.kit('boing')) return;
    this._warble(210, 0.26, 0.055, 'triangle', 660, 90, 17);
  }
  /** Coming down: the same spring, compressing. Under the recorded impact, not over. */
  boingDown() {
    if (this.kit('boing', { pitch: 0.8 })) return;
    this._warble(540, 0.2, 0.04, 'triangle', 170, 70, 19);
  }
  /** Bouncing off the rock. A springier, sillier bonk than the thud alone. */
  sproing() {
    if (this.kit('boing', { pitch: 1.25 })) return;
    this._warble(330, 0.42, 0.06, 'triangle', 118, 130, 13);
    this._warble(660, 0.3, 0.022, 'sine', 240, 80, 21, 0.04);
  }
  /** Something on its way down to a comic landing. */
  slideDown() {
    if (this.kit('fallingWhistle')) return;
    this._slide(1250, 250, 0.42, 0.05);
  }
  /** A bubble surfacing: the chunk arriving on its rope. */
  bloop() {
    if (this.kit('bubble')) return;
    this._tone(320, 0.13, 0.05, 'sine', 900);
    this._noise(0.05, 1800, 'bandpass', 0.025, 3, 0.01);
  }
  /** Rubbery: the character wobbling on the spot when the ground scares it. */
  wobble() {
    this._warble(150, 0.5, 0.038, 'sine', 128, 26, 8);
  }
  /** Skidding to a halt at the edge, feet going nowhere. Sized to the delivered
      36-frame skid, which plays across CFG.timing.breakSkid — so the squeal lasts the
      whole slide instead of being a blip at the start of it. */
  skid() {
    this._noise(2.0, 1750, 'bandpass', 0.055, 9, 0, 480);    // the feet, all the way down
    this._warble(820, 1.9, 0.028, 'sawtooth', 240, 60, 22);  // the comic squeal, sliding
    this._noise(0.3, 420, 'lowpass', 0.05, 0.8, 1.9, 160);   // the thump of coming to rest
  }
  /* THE KNEES KNOCKING, for the fright at the edge. Six low woodblock-ish taps a beat
     apart, alternating pitch — the cartoon shorthand for legs that have stopped
     cooperating. Spread across about a second so it lasts as long as the delivered
     fright animation, and deliberately soft because it plays under the gasp. */
  knees() {
    if (this.kit('ratchet')) return;   // knees knocking: a rattle
    for (let i = 0; i < 6; i++) {
      const t = i * 0.17;
      this._tone(96 + (i % 2) * 26, 0.06, 0.035, 'square', 62, t);
      this._noise(0.05, 340, 'bandpass', 0.02, 2.4, t);
    }
  }

  /* A DOUBLE-TAKE. He looks, then looks again — two rising blips with the second one
     higher and a beat late, which is how a take reads in sound. */
  doubleTake() {
    if (this.kit('cuckoo')) return;   // the classic double-take
    this._tone(420, 0.09, 0.04, 'triangle', 700);
    this._tone(560, 0.12, 0.045, 'triangle', 980, 0.16);
    this._noise(0.06, 2200, 'bandpass', 0.02, 3, 0.16);
  }

  /** A glint of light, for the sparkle burst. */
  twinkle() {
    if (this.kit('sparkle')) return;
    [12, 16, 19].forEach((s, i) => this._note(s, 0.16, 0.026, 'sine', i * 0.055));
  }
}
/* ---------------- ParticleManager ---------------- */
class ParticleManager {
  constructor() { this.list = []; }
  spawn(n, fn) { for (let i = 0; i < n; i++) { const p = this.list.find(q => q.dead) || (this.list.push({ dead: true }), this.list[this.list.length - 1]); Object.assign(p, { dead: false, life: 1, t: 0 }, fn(i)); } }
  /* A CARTOON POOF. Four overlapping white discs with a soft blue rim, thrown up and out
     from the feet, swelling as they thin and drifting UP — a cloud, not a spray of dots.
     This is the dust every cartoon impact has: the skid, the landing, the crash, the
     plug arriving, a footfall. `size` scales the whole cloud. */
  poof(x, y, n = 5, size = 1) {
    this.spawn(n, i => {
      const a = -Math.PI / 2 + (i / Math.max(1, n - 1) - 0.5) * 2.4 + rand(-0.25, 0.25);
      const v = rand(70, 160) * size;
      return {
        x: x + rand(-16, 16) * size, y: y + rand(-6, 2),
        vx: Math.cos(a) * v * 1.5, vy: Math.sin(a) * v * 0.5 - 24,
        r: rand(10, 19) * size, dur: rand(0.5, 0.9), kind: 'puff', swell: rand(1.5, 2.2)
      };
    });
  }
  snowPuff(x, y, n = 6, spread = 1) {
    this.spawn(n, () => ({ x: x + rand(-16, 16), y: y + rand(-8, 4), vx: rand(-90, 90) * spread, vy: rand(-160, -50) * spread, r: rand(5, 13), dur: rand(0.45, 0.8), kind: 'snow' }));
  }
  skid(x, y, n = 10) {
    this.spawn(n, () => ({ x: x + rand(-10, 40), y: y + rand(-6, 2), vx: rand(60, 300), vy: rand(-140, -30), r: rand(4, 10), dur: rand(0.4, 0.7), kind: 'snow' }));
  }
  chips(x, y, n = 8, vy0 = -60) {
    this.spawn(n, () => ({ x: x + rand(-70, 70), y: y + rand(-10, 20), vx: rand(-70, 70), vy: rand(vy0, vy0 + 90), r: rand(4, 10), dur: rand(0.7, 1.2), kind: 'ice', rot: rand(0, 6.28), vr: rand(-4, 4) }));
  }
  /* A WRONG CHUNK HITTING THE MELT WATER — a crown, which is what a splash is.
   *
   * The version before this read as a clump of white shards hanging near the top of
   * the hole, and every part of that was a separate decision going wrong together:
   *
   *   it was thrown from the crevasse MOUTH, not the water. That was right when the
   *   pool was not drawn at all and a splash inside the hole was a few invisible
   *   pixels; the pool is painted now and its surface is plainly visible, so the
   *   splash was happening about 180px above the thing it was supposedly splashing.
   *
   *   every droplet left from x +/- 30 within a +/- 43 degree fan at a similar speed,
   *   so 22 of them travelled as one blob instead of spreading.
   *
   *   each one is stretched along its own velocity, and at 900px/s that turns a
   *   droplet into a long thin spike — which on an ice stage reads as a shard.
   *
   * A real splash is three things at once, so this makes three: a narrow CROWN thrown
   * almost straight up from the impact point, a wide low SHEET of fast droplets going
   * sideways, and slow round FOAM that lingers where the surface broke. Speeds vary by
   * a factor of four inside each group, which is what stops them moving as one object. */
  splash(x, y, n = 20) {
    const crown = Math.max(3, Math.round(n * 0.45));
    const sheet = Math.max(3, Math.round(n * 0.35));
    const foam = Math.max(2, n - crown - sheet);

    // the crown: up and slightly out, tall and thin, the tallest part of the splash
    this.spawn(crown, i => {
      const a = -Math.PI / 2 + (i / crown - 0.5) * 0.9;
      const v = 300 + Math.random() * 640;
      return {
        x: x + rand(-22, 22), y: y + rand(-4, 6),
        vx: Math.cos(a) * v * 0.5, vy: Math.sin(a) * v,
        r: rand(5, 12), dur: rand(0.55, 0.95), kind: 'water', foam: 0
      };
    });
    // the sheet: low and wide, thrown out along the surface both ways
    this.spawn(sheet, i => {
      const side = i % 2 ? 1 : -1;
      const a = -Math.PI / 2 + side * (0.75 + Math.random() * 0.55);
      const v = 340 + Math.random() * 520;
      return {
        x: x + side * rand(6, 34), y: y + rand(-2, 8),
        vx: Math.cos(a) * v, vy: Math.sin(a) * v * 0.72,
        r: rand(3, 8), dur: rand(0.45, 0.8), kind: 'water', foam: 0
      };
    });
    // the foam: slow, round, and it stays near the break in the surface
    this.spawn(foam, () => ({
      x: x + rand(-46, 46), y: y + rand(-2, 12),
      vx: rand(-70, 70), vy: rand(-190, -60),
      r: rand(7, 16), dur: rand(0.6, 1.1), kind: 'water', foam: 1
    }));
  }
  /* CONFETTI, for finishing the journey.

     Thrown across the WHOLE width from above the top of the frame, not from a point:
     a burst from one place is an impact, and confetti has to rain on everything for
     the moment to read as a celebration rather than as one more hit effect.

     Each piece is a flat rectangle that TUMBLES — the width is squeezed on a cosine
     exactly as the reward token was, because a spinning flake seen edge-on is a line
     and that squeeze is the whole illusion. Without it they fall as coloured bricks.

     Staggered by `delay` rather than all released together, so it falls as a shower
     over a couple of seconds instead of one sheet crossing the screen. */
  confetti(stageW, n = 80, big = false) {
    const hue = ['#FFC93C', '#FF7BAC', '#5AD2F4', '#8CE07A', '#FFF2B8', '#C58CFF'];
    this.spawn(n, i => ({
      x: Math.random() * stageW,
      y: -40 - Math.random() * 260,
      vx: rand(-70, 70),
      vy: rand(150, 330),
      r: big ? rand(14, 28) : rand(7, 15),      // big: the ending's pieces have to read from the sofa
      dur: big ? rand(3.2, 5.2) : rand(2.4, 4.2),
      kind: 'confetti',
      rot: rand(0, 6.28), vr: rand(-5, 5),
      sp: rand(1.6, 3.4),
      col: hue[i % hue.length],
      delay: Math.random() * 1.9
    }));
  }
  /* A SHOCK RING: one expanding hoop on the frame an impact happens. It is the
     cheapest possible way to say "that hit here", and unlike a particle spray it
     reads at a glance even at phone size. */
  ring(x, y, r0 = 26, r1 = 190) {
    this.spawn(1, () => ({ x, y, vx: 0, vy: 0, r: r0, r1, dur: 0.42, kind: 'ring' }));
  }
  frost(x, y, n = 4) {
    this.spawn(n, () => ({ x: x + rand(-24, 24), y: y + rand(-24, 24), vx: rand(-30, 30), vy: rand(-40, -8), r: rand(2.5, 5.5), dur: rand(0.5, 0.9), kind: 'frost' }));
  }
  /* COMICAL SWEAT. Flicked off the head, up and away, then falls. One bead at a time
     rather than a spray: a shower of them reads as rain, and the joke is one bead. */
  sweat(x, y, n = 1) {
    this.spawn(n, () => ({
      x: x + rand(-10, 10), y: y + rand(-8, 8),
      vx: rand(90, 210), vy: rand(-300, -190),
      r: rand(6, 9.5), dur: rand(0.55, 0.8), kind: 'sweat',
      rot: 0, vr: 0
    }));
  }
  /* A GLINT. Four-pointed stars that pop and shrink away — the reward beat, and the
     one thing on screen that says "that was right" in the language of a game rather
     than of a worksheet. */
  sparkle(x, y, n = 8, spread = 150) {
    this.spawn(n, i => {
      const a = (i / n) * 6.2832 + rand(-0.3, 0.3);
      const v = spread * rand(0.55, 1.35);
      return {
        x: x + rand(-14, 14), y: y + rand(-14, 14),
        vx: Math.cos(a) * v, vy: Math.sin(a) * v - 90,
        r: rand(7, 15), dur: rand(0.5, 0.95), kind: 'sparkle',
        rot: rand(0, 6.28), vr: rand(-2.4, 2.4)
      };
    });
  }
  update(dt) {
    for (const p of this.list) {
      if (p.dead) continue;
      p.t += dt;
      if (p.t >= p.dur) { p.dead = true; continue; }
      // a sparkle is a glint of light, so it drifts rather than falls
      if (p.kind === 'ring') { p.life = 1 - p.t / p.dur; continue; }
      /* A staggered start. The piece exists from the beginning — so it is counted and
         pooled like everything else — but does not move or draw until its delay is up,
         which is what turns one sheet of confetti into a shower. */
      if (p.kind === 'puff') {
        // a poof slows, drifts up and swells as it thins; it never falls
        p.vx *= (1 - 2.6 * dt); p.vy = p.vy * (1 - 2.6 * dt) - 34 * dt;
        p.x += p.vx * dt; p.y += p.vy * dt;
        p.life = 1 - p.t / p.dur;
        continue;
      }
      if (p.kind === 'confetti') {
        if (p.delay > 0) { p.delay -= dt; p.life = 1; continue; }
        p.vy += 190 * dt;                    // light: it drifts down, it does not drop
        p.vx *= (1 - 0.6 * dt);              // and air resistance takes the sideways off
        p.x += p.vx * dt; p.y += p.vy * dt;
        p.rot += p.vr * dt;
        p.life = 1 - p.t / p.dur;
        continue;
      }
      p.vy += (p.kind === 'ice' ? 900 : p.kind === 'water' ? 1500
             : p.kind === 'sparkle' ? 90 : p.kind === 'sweat' ? 1100 : 520) * dt;
      p.x += p.vx * dt; p.y += p.vy * dt;
      if (p.vr) p.rot += p.vr * dt;
      p.life = 1 - p.t / p.dur;
    }
  }
  draw(ctx) {
    for (const p of this.list) {
      if (p.dead) continue;
      ctx.globalAlpha = clamp(p.life * 1.2, 0, 1);
      if (p.kind === 'ice') {
        ctx.save(); ctx.translate(p.x, p.y); ctx.rotate(p.rot || 0);
        ctx.fillStyle = C.lightIce; ctx.beginPath();
        ctx.moveTo(0, -p.r); ctx.lineTo(p.r * 0.8, 0); ctx.lineTo(0, p.r); ctx.lineTo(-p.r * 0.8, 0); ctx.closePath(); ctx.fill();
        ctx.restore();
      } else if (p.kind === 'puff') {
        /* Rim first as larger discs, then the white on top, so the outline wraps the
           UNION of the lobes with no lines through the cloud. */
        const k = 1 + (1 - p.life) * (p.swell || 1.6), R = p.r * k;
        ctx.globalAlpha = clamp(p.life * 1.15, 0, 1) * 0.94;
        ctx.save(); ctx.translate(p.x, p.y);
        const lobes = [[0, 0, 1], [-0.74, 0.2, 0.74], [0.76, 0.16, 0.7], [0.06, -0.52, 0.66]];
        ctx.fillStyle = 'rgba(112,168,218,0.7)'; ctx.beginPath();
        for (const [ox, oy, rr] of lobes) { ctx.moveTo(ox * R + rr * R + 2.4, oy * R); ctx.arc(ox * R, oy * R, rr * R + 2.4, 0, 6.2832); }
        ctx.fill();
        ctx.fillStyle = '#FFFFFF'; ctx.beginPath();
        for (const [ox, oy, rr] of lobes) { ctx.moveTo(ox * R + rr * R, oy * R); ctx.arc(ox * R, oy * R, rr * R, 0, 6.2832); }
        ctx.fill();
        ctx.restore();
      } else if (p.kind === 'water') {
        /* FOAM IS ROUND AND WATER IS A DROPLET. The stretch is capped at 0.55 of the
           radius and scaled off a much higher speed divisor, because the old 1.6x
           stretch at 700px/s turned a fast droplet into a spike — and a white spike on
           an ice stage reads as a shard of ice, which is the wrong substance entirely.
           Foam does not stretch at all: it is churned surface, not a droplet in flight. */
        const sp = Math.hypot(p.vx, p.vy) || 1;
        ctx.save();
        ctx.translate(p.x, p.y);
        if (p.foam) {
          const gg = ctx.createRadialGradient(-p.r * 0.3, -p.r * 0.3, 0, 0, 0, p.r);
          gg.addColorStop(0, 'rgba(255,255,255,0.98)');
          gg.addColorStop(0.6, 'rgba(233,249,255,0.85)');
          gg.addColorStop(1, 'rgba(168,222,247,0.35)');
          ctx.fillStyle = gg;
          ctx.beginPath(); ctx.arc(0, 0, p.r, 0, 6.2832); ctx.fill();
        } else {
          ctx.rotate(Math.atan2(p.vy, p.vx));
          const g = ctx.createLinearGradient(-p.r, 0, p.r, 0);
          g.addColorStop(0, 'rgba(255,255,255,0.96)');
          g.addColorStop(0.55, 'rgba(214,241,253,0.92)');
          g.addColorStop(1, 'rgba(104,201,238,0.8)');
          ctx.fillStyle = g;
          ctx.beginPath();
          ctx.ellipse(0, 0, p.r * (1 + Math.min(0.55, sp / 1600)), p.r * 0.78, 0, 0, 6.2832);
          ctx.fill();
        }
        ctx.restore();
      } else if (p.kind === 'sweat') {
        /* A cartoon bead: a teardrop with a white catchlight, tipped along its travel
           so it reads as flicked off rather than dropped. */
        ctx.save();
        ctx.translate(p.x, p.y);
        ctx.rotate(Math.atan2(p.vy, p.vx) + Math.PI / 2);
        ctx.fillStyle = 'rgba(150,222,250,0.95)';
        ctx.beginPath();
        ctx.moveTo(0, -p.r * 1.5);
        ctx.quadraticCurveTo(p.r, -p.r * 0.2, p.r * 0.75, p.r * 0.55);
        ctx.quadraticCurveTo(0, p.r * 1.35, -p.r * 0.75, p.r * 0.55);
        ctx.quadraticCurveTo(-p.r, -p.r * 0.2, 0, -p.r * 1.5);
        ctx.closePath();
        ctx.fill();
        ctx.strokeStyle = 'rgba(255,255,255,0.85)'; ctx.lineWidth = 2; ctx.stroke();
        ctx.fillStyle = 'rgba(255,255,255,0.9)';
        ctx.beginPath(); ctx.ellipse(-p.r * 0.24, -p.r * 0.1, p.r * 0.2, p.r * 0.34, 0, 0, 6.2832); ctx.fill();
        ctx.restore();
      } else if (p.kind === 'confetti') {
        if (p.delay > 0) continue;           // not released yet
        /* THE TUMBLE IS THE WIDTH, the same trick the reward token used: a flat piece
           turning on its long axis is full width one moment and a line the next. */
        const face = Math.cos(p.t * (p.sp || 2) * 6.2832);
        ctx.save();
        ctx.translate(p.x, p.y);
        ctx.rotate(p.rot || 0);
        ctx.fillStyle = p.col || '#FFC93C';
        ctx.globalAlpha = clamp(p.life * 1.6, 0, 1);
        ctx.fillRect(-p.r * 0.5, -p.r * 0.34 * Math.abs(face) - 0.5,
                     p.r, Math.max(1.2, p.r * 0.68 * Math.abs(face)));
        ctx.restore();
      } else if (p.kind === 'ring') {
        /* An expanding hoop, thinning as it goes. Warm rather than white: white on an
           ice stage disappears into it, and this has to be seen for four frames. */
        const e = 1 - p.life;
        const r = lerp(p.r, p.r1 || 190, easeOut(e));
        ctx.save();
        ctx.globalAlpha = (1 - e) * 0.7;
        ctx.strokeStyle = '#FFE9A8';
        ctx.lineWidth = lerp(14, 1.5, e);
        ctx.beginPath(); ctx.arc(p.x, p.y, r, 0, 6.2832); ctx.stroke();
        ctx.restore();
      } else if (p.kind === 'sparkle') {
        // a four-pointed glint, brightest at birth and shrinking as it fades
        const s = p.r * (0.45 + p.life * 0.85);
        ctx.save();
        ctx.translate(p.x, p.y);
        ctx.rotate(p.rot || 0);
        const gg = ctx.createRadialGradient(0, 0, 0, 0, 0, s);
        gg.addColorStop(0, 'rgba(255,255,255,0.95)');
        gg.addColorStop(1, 'rgba(255,236,170,0)');
        ctx.fillStyle = gg;
        ctx.beginPath(); ctx.arc(0, 0, s, 0, 6.2832); ctx.fill();
        ctx.fillStyle = 'rgba(255,252,232,0.95)';
        ctx.beginPath();
        ctx.moveTo(0, -s * 1.7); ctx.lineTo(s * 0.28, -s * 0.28);
        ctx.lineTo(s * 1.7, 0); ctx.lineTo(s * 0.28, s * 0.28);
        ctx.lineTo(0, s * 1.7); ctx.lineTo(-s * 0.28, s * 0.28);
        ctx.lineTo(-s * 1.7, 0); ctx.lineTo(-s * 0.28, -s * 0.28);
        ctx.closePath(); ctx.fill();
        ctx.restore();
      } else {
        ctx.fillStyle = p.kind === 'frost' ? C.frost : C.snow;
        ctx.beginPath(); ctx.arc(p.x, p.y, p.r, 0, 6.2832); ctx.fill();
      }
    }
    ctx.globalAlpha = 1;
  }
  clear() { this.list.length = 0; }
}

/* ---------------- BackgroundTimeManager ---------------- */
class BackgroundTimeManager {
  constructor(images) {
    this.images = images; this.index = 0;
    this.a = CFG.phases[0].key; this.b = null; this.fade = 0;
  }
  phaseFor(p) {
    let idx = 0;
    for (let i = 0; i < CFG.phases.length; i++) if (p >= CFG.phases[i].at) idx = i;
    return idx;
  }
  update(dt, progress) {
    const want = this.phaseFor(progress);
    if (want !== this.index && !this.b) {
      this.index = want; this.b = CFG.phases[want].key; this.fade = 0;
    }
    if (this.b) {
      this.fade += dt * 1000 / T.crossfade;
      if (this.fade >= 1) { this.a = this.b; this.b = null; this.fade = 0; }
    }
  }
  get label() { return CFG.phases[this.index].label; }

  /** The colour and strength of the sky's light right now, crossfade included, so
      anything drawn over the sky can be lit by it instead of guessing. */
  light() {
    /* LIT FROM THE SKY THAT IS STILL SHOWING. `index` is moved to the NEW phase the moment
       a crossfade begins, so reading A off it lit everything with the destination sky's
       light on the first frame of the fade — at dusk->night the fog, clouds and frost
       dropped to night's 0.34 dim in one frame while the picture behind them was still
       dusk, then the two lerp arguments were identical for the rest of the fade. That
       was the pop in the day-to-night change. A is the OUTGOING sky (`this.a`); B the
       incoming; the light crosses with the picture. */
    const A = CFG.phases.find(q => q.key === this.a) || CFG.phases[this.index];
    const B = this.b ? CFG.phases.find(q => q.key === this.b) : null;
    const la = A.light || [255, 255, 255], da = A.dim === undefined ? 1 : A.dim;
    if (!B) return { c: la, dim: da };
    const f = easeInOut(clamp(this.fade, 0, 1));
    const lb = B.light || [255, 255, 255], db = B.dim === undefined ? 1 : B.dim;
    return { c: [lerp(la[0], lb[0], f), lerp(la[1], lb[1], f), lerp(la[2], lb[2], f)],
             dim: lerp(da, db, f) };
  }
  draw(ctx, worldX, reduced) {
    const drift = reduced ? 0 : -46 - 46 * Math.sin(worldX * 0.00008);
    const w = CFG.W * 1.05, h = CFG.H * 1.05;
    const x = drift, y = -(h - CFG.H) / 2;
    const ia = this.images[this.a];
    if (ia) ctx.drawImage(ia, x, y, w, h);
    if (this.b && this.images[this.b]) {
      ctx.globalAlpha = easeInOut(clamp(this.fade, 0, 1));
      ctx.drawImage(this.images[this.b], x, y, w, h);
      ctx.globalAlpha = 1;
    }
  }
  reset() { this.index = 0; this.a = CFG.phases[0].key; this.b = null; this.fade = 0; }
}

/* ---------------- Atmosphere (aurora / snowfall) ---------------- */
class Atmosphere {
  constructor() {
    const mk = (n, cfg) => Array.from({ length: n }, () => ({
      x: rand(0, 1920), y: rand(-80, 1080),
      r: rand(cfg.r0, cfg.r1), fall: rand(cfg.f0, cfg.f1),
      sway: rand(cfg.s0, cfg.s1), ph: rand(0, 6.283), a: rand(cfg.a0, cfg.a1), par: cfg.par
    }));
    this.far = mk(34, { r0: 0.9, r1: 1.7, f0: 16, f1: 26, s0: 5, s1: 12, a0: 0.16, a1: 0.3, par: 0.12 });
    this.mid = mk(22, { r0: 1.6, r1: 2.6, f0: 30, f1: 46, s0: 9, s1: 18, a0: 0.28, a1: 0.44, par: 0.26 });
    this.near = mk(9, { r0: 3.0, r1: 4.6, f0: 62, f1: 92, s0: 16, s1: 30, a0: 0.3, a1: 0.46, par: 0.5 });
    this.aur = [
      { y: 330, amp: 26, freq: 0.0019, sp: 0.22, h: 250, c: [116, 255, 190], a: 0.15 },
      { y: 286, amp: 20, freq: 0.0027, sp: -0.18, h: 210, c: [108, 214, 255], a: 0.10 },
      { y: 246, amp: 15, freq: 0.0035, sp: 0.29, h: 170, c: [200, 152, 255], a: 0.07 }
    ];
    /* A few small banks, high up. Deliberately few: the painted skies already have
       weather in them, and this layer only has to make the sky move. Each one's lobes
       are fixed at construction so a cloud keeps its shape as it drifts. */
    this.clouds = Array.from({ length: 4 }, (_, i) => {
      let seed = i * 977 + 41;
      const rnd = () => (seed = (seed * 9301 + 49297) % 233280) / 233280;
      return {
        x: rand(-200, 2100), y: 96 + rnd() * 210,
        s: 0.5 + rnd() * 0.42,
        sp: 5 + rnd() * 7,                       // its own drift, px/s
        par: 0.05 + rnd() * 0.05,                // and a little world parallax
        a: 0.09 + rnd() * 0.08,
        lobes: Array.from({ length: 5 }, (_, j) => ({
          dx: (j - 2) * (44 + rnd() * 22),
          dy: (rnd() - 0.5) * 22,
          r: 36 + rnd() * 36 - Math.abs(j - 2) * 8
        }))
      };
    });
    /* Blown snow. It arrives in GUSTS — a constant stream of streaks reads as rain,
       and rain is the wrong weather. */
    this.wind = Array.from({ length: 16 }, (_, i) => ({
      y: rand(120, 980), len: rand(80, 260), sp: rand(560, 1180),
      a: rand(0.05, 0.15), ph: rand(0, 6.283), bow: rand(4, 16)
    }));
    this.gust = 0;
    this.intensity = 0; this.flash = 0; this.px = 960;
  }
  // only x is used — the aurora bulges toward the pointer's column (see drawAurora)
  pointer(x) { this.px = x; }
  pulse() { this.flash = 1; }
  update(dt, progress) {
    const target = (clamp((progress - 0.66) / 0.12, 0, 1) * 0.5 + clamp((progress - 0.84) / 0.06, 0, 1) * 0.5) * 0.8;
    this.intensity = lerp(this.intensity, target, clamp(dt * 1.4, 0, 1));
    this.flash = Math.max(0, this.flash - dt * 1.5);
    // one gust roughly every nine seconds, building and dying rather than switching
    this.gustT = (this.gustT || 0) + dt;
    const cyc = (this.gustT % 9) / 9;
    this.gust = Math.max(0, Math.sin(cyc * Math.PI * 2)) * 0.85 + 0.15;
    for (const c of this.clouds) {
      c.x -= c.sp * dt;
      if (c.x < -420) c.x += 2740;
    }
  }

  /* A COLD HAZE low in the sky, thickest at the horizon. This is what makes a white
     field read as frozen rather than merely bright, and it costs one gradient. */
  drawFrost(ctx, light) {
    const [r, gg, b] = light.c;
    /* Deliberately shallow. This is one full-width alpha-blended fill, and on a machine
       with no GPU it measured 15ms a frame at 190px tall - more than the whole rest of
       the render put together. At 110px it costs half that and reads the same, because
       what a cold haze has to do happens in the last stretch of air above the horizon. */
    const y0 = CFG.surfaceY - 150, h = 110;
    /* Built once per colour, not once per frame: the colour only moves during a sky
       crossfade, so it is keyed on the light and reused the rest of the time. */
    const key = (r | 0) + ',' + (gg | 0) + ',' + (b | 0);
    if (this._frostKey !== key) {
      const gr = ctx.createLinearGradient(0, y0, 0, y0 + h);
      gr.addColorStop(0, 'rgba(' + key + ',0)');
      gr.addColorStop(0.72, 'rgba(' + key + ',1)');
      gr.addColorStop(1, 'rgba(' + key + ',0.5)');
      this._frost = gr; this._frostKey = key;
    }
    ctx.globalAlpha = 0.11 * light.dim;
    ctx.fillStyle = this._frost;
    ctx.fillRect(0, y0, CFG.W, h);
    ctx.globalAlpha = 1;
  }

  /* Small, soft, translucent banks. Built from stacked radial falloffs, because a
     cloud has no edge — the hard-lobed version this replaces looked like cotton wool
     stuck on the sky. */
  /* Each cloud is drawn ONCE into its own small canvas — its lobes never change, only
     where it is. Live, five radial gradients per cloud per frame were re-rasterised
     for a sky that had not moved.

     It is cached IN THE SKY'S COLOUR, keyed on that colour rounded to 16 levels, so it
     rebuilds a handful of times over a whole run instead of 60 times a second. Caching
     it white and only scaling alpha would be cheaper again and would bring back the
     exact fault that had generated clouds deleted once before: white banks floating
     over a violet dusk. */
  _cloudArt(c, key, rgb) {
    if (c.art && c.artKey === key) return c.art;
    let x0 = Infinity, x1 = -Infinity, y0 = Infinity, y1 = -Infinity;
    for (const l of c.lobes) {
      const rr = l.r * c.s;
      x0 = Math.min(x0, l.dx * c.s - rr); x1 = Math.max(x1, l.dx * c.s + rr);
      y0 = Math.min(y0, l.dy * c.s - rr); y1 = Math.max(y1, l.dy * c.s + rr);
    }
    const ox = x0 - 2, oy = y0 - 2;
    const cv = document.createElement('canvas');
    cv.width = Math.max(1, Math.ceil(x1 - ox) + 2);
    cv.height = Math.max(1, Math.ceil(y1 - oy) + 2);
    const g = cv.getContext('2d');
    g.translate(-ox, -oy);
    const col = rgb.map(v => v | 0).join(',');
    for (const l of c.lobes) {
      const rr = l.r * c.s;
      if (rr <= 0) continue;
      const lx = l.dx * c.s, ly = l.dy * c.s;
      const gr = g.createRadialGradient(lx, ly - rr * 0.25, 0, lx, ly, rr);
      gr.addColorStop(0, 'rgba(' + col + ',1)');
      gr.addColorStop(0.55, 'rgba(' + col + ',0.5)');
      gr.addColorStop(1, 'rgba(' + col + ',0)');
      g.fillStyle = gr;
      g.beginPath(); g.arc(lx, ly, rr, 0, 6.2832); g.fill();
    }
    c.art = { canvas: cv, ox, oy };
    c.artKey = key;
    return c.art;
  }
  drawClouds(ctx, worldX, light, reduced) {
    if (light.dim < 0.4) return;              // at night there is nothing to light them
    const rgb = light.c;
    // quantised to 16 levels: enough to follow a crossfade, coarse enough to cache
    const key = rgb.map(v => (v | 0) >> 4).join('.');
    ctx.save();
    for (const c of this.clouds) {
      const x = c.x - (reduced ? 0 : worldX * c.par) % 2740;
      if (x < -420 || x > CFG.W + 420) continue;
      const art = this._cloudArt(c, key, rgb);
      ctx.globalAlpha = c.a * light.dim;
      ctx.drawImage(art.canvas, Math.round(x + art.ox), Math.round(c.y + art.oy));
    }
    ctx.globalAlpha = 1;
    ctx.restore();
  }

  /* Blown snow: long thin streaks, bowed slightly by their own speed, arriving in
     gusts. Drawn as lines rather than particles because at this speed real blown snow
     IS a line — a dot moving that fast is a line for the eye anyway. */
  /* Flat strokes, not gradients. One linear gradient per streak was 26 gradient
     objects a frame; at these widths and opacities a plain stroke is
     indistinguishable, and the taper that mattered comes from drawing the bright core
     shorter than the body. */
  drawWind(ctx, worldX, t, light, reduced) {
    if (reduced) return;
    const g = this.gust;
    if (g < 0.06) return;
    ctx.save();
    ctx.lineCap = 'round';
    ctx.strokeStyle = '#FFFFFF';
    for (const w of this.wind) {
      const x = CFG.W + 200 - ((t * w.sp + w.ph * 900) % (CFG.W + 520));
      const a = w.a * g * light.dim;
      if (a < 0.012) continue;
      const len = w.len * (0.6 + g * 0.6);
      ctx.lineWidth = 1.5 + g * 1.1;
      ctx.globalAlpha = a * 0.5;
      ctx.beginPath();
      ctx.moveTo(x, w.y);
      ctx.quadraticCurveTo(x + len * 0.5, w.y + w.bow * 0.5, x + len, w.y + w.bow);
      ctx.stroke();
      // a shorter, brighter core, which is what gives a streak its direction
      ctx.globalAlpha = a;
      ctx.beginPath();
      ctx.moveTo(x + len * 0.26, w.y + w.bow * 0.26);
      ctx.lineTo(x + len * 0.7, w.y + w.bow * 0.7);
      ctx.stroke();
    }
    ctx.globalAlpha = 1;
    ctx.restore();
  }
  drawAurora(ctx, t, reduced) {
    const I = this.intensity;
    if (I < 0.02) return;
    const boost = 1 + this.flash * 0.5;
    ctx.save();
    ctx.globalCompositeOperation = 'lighter';
    ctx.filter = `blur(${reduced ? 9 : 15}px)`;
    for (let bi = 0; bi < this.aur.length; bi++) {
      const b = this.aur[bi];
      const yAt = (x) => {
        const bulge = Math.exp(-Math.pow((x - this.px) / 300, 2)) * 30;
        const wob = reduced ? 0
          : Math.sin(x * b.freq + t * b.sp * 2.0) * b.amp + Math.sin(x * b.freq * 2.6 - t * b.sp * 1.3) * b.amp * 0.42;
        return b.y + wob - bulge;
      };
      const step = 44;
      const path = new Path2D();
      path.moveTo(-80, yAt(-80));
      for (let x = -80; x <= CFG.W + 80; x += step) path.lineTo(x, yAt(x));
      for (let x = CFG.W + 80; x >= -80; x -= step) path.lineTo(x, yAt(x) - b.h);
      path.closePath();
      const [r, g, bl] = b.c;
      const shimmer = 0.68 + 0.32 * Math.sin(t * (0.55 + bi * 0.22) + bi * 2.1);
      const a = b.a * I * boost * shimmer;
      const gr = ctx.createLinearGradient(0, b.y - b.h - b.amp, 0, b.y + b.amp + 10);
      gr.addColorStop(0, `rgba(${r},${g},${bl},0)`);
      gr.addColorStop(0.4, `rgba(${r},${g},${bl},${(a * 0.42).toFixed(3)})`);
      gr.addColorStop(0.82, `rgba(${r},${g},${bl},${a.toFixed(3)})`);
      gr.addColorStop(1, `rgba(${r},${g},${bl},0)`);
      ctx.fillStyle = gr;
      ctx.fill(path);
    }
    // soft light shafts (kept very low so the sky stays the background)
    for (let i = 0; i < 3; i++) {
      const sx = (i * 421 + 140 + (reduced ? 0 : Math.sin(t * 0.18 + i * 1.7) * 90)) % (CFG.W + 200) - 100;
      const sa = 0.035 * I * boost * (0.4 + 0.6 * Math.abs(Math.sin(t * 0.5 + i * 2.3)));
      const cy = 250 + (i % 3) * 34;
      const rg = ctx.createRadialGradient(sx, cy, 0, sx, cy, 190);
      rg.addColorStop(0, `rgba(200,255,235,${sa.toFixed(3)})`);
      rg.addColorStop(1, 'rgba(200,255,235,0)');
      ctx.fillStyle = rg;
      ctx.save(); ctx.translate(sx, cy); ctx.scale(0.34, 1.25);
      ctx.beginPath(); ctx.arc(0, 0, 190, 0, 6.2832); ctx.fill(); ctx.restore();
    }
    ctx.filter = 'none';
    ctx.restore();
  }
  drawSnow(ctx, worldX, t, reduced, layers) {
    const damp = reduced ? 0.35 : 1;
    ctx.save();
    for (const layer of layers) {
      for (const f of layer) {
        const y = ((f.y + t * f.fall * damp) % 1180 + 1180) % 1180 - 100;
        const drift = Math.sin(t * 0.6 + f.ph) * f.sway;
        const x = ((f.x - worldX * f.par * 0.35 + drift) % 2000 + 2000) % 2000 - 40;
        ctx.globalAlpha = f.a * (0.75 + 0.25 * Math.sin(t * 1.6 + f.ph));
        ctx.fillStyle = '#FFFFFF';
        ctx.beginPath(); ctx.arc(x, y, f.r, 0, 6.2832); ctx.fill();
      }
    }
    ctx.restore();
    ctx.globalAlpha = 1;
  }
  drawBack(ctx, worldX, t, reduced, light) {
    /* Order matters: haze sits furthest back, then the cloud banks over it, then the
       far and mid snow, then the wind streaking through all of it. */
    const L = light || { c: [255, 255, 255], dim: 1 };
    this.drawFrost(ctx, L);
    this.drawClouds(ctx, worldX, L, reduced);
    this.drawSnow(ctx, worldX, t, reduced, [this.far, this.mid]);
    this.drawWind(ctx, worldX, t, L, reduced);
  }
  drawFront(ctx, worldX, t, reduced) {
    this.drawSnow(ctx, worldX, t, reduced, [this.near]);
  }
}

/* For each frame in a horizontal strip, how many pixels of empty space sit below the
   lowest opaque pixel. Walks up from the bottom and stops at the first opaque row, so
   it reads about ten rows per frame in practice. Returns null if the sheet is missing
   or cannot be read, and every caller falls back to the shared baseGap. */
function measureFootlines(img, frames) {
  if (!img || !frames) return null;
  const CW = CFG.sprite.cw, CH = CFG.sprite.ch;
  try {
    const c = document.createElement('canvas');
    c.width = img.naturalWidth || img.width;
    c.height = img.naturalHeight || img.height;
    if (!c.width || !c.height) return null;
    const g = c.getContext('2d', { willReadFrequently: true });
    g.drawImage(img, 0, 0);
    const out = [];
    for (let f = 0; f < frames; f++) {
      const x0 = f * CW;
      if (x0 + CW > c.width) { out.push(CFG.sprite.baseGap); continue; }
      let gap = CFG.sprite.baseGap;
      // a generous cap: past this the frame is empty and the fallback is right
      const limit = Math.min(CH, 160);
      for (let up = 0; up < limit; up++) {
        const y = Math.min(c.height, CH) - 1 - up;
        if (y < 0) break;
        const row = g.getImageData(x0, y, CW, 1).data;
        let hit = false;
        for (let i = 3; i < row.length; i += 4) if (row[i] > 12) { hit = true; break; }
        if (hit) { gap = up; break; }
      }
      out.push(gap);
    }
    return out;
  } catch (e) {
    return null;                          // never let a measurement break the game
  }
}

/* HOW FAR A HIT PUSHES HIM BACK, in px. 34 is about a fifth of his body width:
   enough to read as being stopped by something solid at the size he is drawn, and not
   so far that he appears to bounce off. */
const CM_KNOCK = 34;

/* WHERE THE COLLISION ACTUALLY IS IN THE DELIVERED KNOCKOUT SHEET.
 *
 * The 36 frames are a whole shot, not just the hit: 0-17 are the character TROTTING
 * IN, 18-23 are the clash — head snapping back, trunk thrown up, debris — 24-29 the
 * tumble, and 30-35 the dazed sit.
 *
 * Played from frame 0, the moment of impact therefore showed a RUN pose, and kept
 * showing run poses for eighteen frames while the character stood embedded in the
 * rock. That is why the crash did not read as a crash: the animation had not got to it
 * yet. Everything else about the impact — the hold, the punch, the recoil, the
 * particles — was landing on a frame of someone jogging.
 *
 * The run-in is unusable here by definition: by the time this state begins the
 * character has ALREADY hit the rock, so the approach is in the past. Starting at the
 * clash is not trimming the animation, it is starting it in the right place. */
const KO_CLASH = 18;
const KO_LAST = 35;
const KO_KNOCK = 150;       // px he is thrown back by a knockout, so the sit clears the rock         // the dazed sit, held

/* ---------------- PlayerController ---------------- */
/* Drives whichever character the player picked. Sheets and frame counts come from
   the character definition; every gameplay number stays global so the choice is
   cosmetic and no explorer is easier to play than another. */
class PlayerController {
  constructor(audio, particles, character, images) {
    this.audio = audio; this.particles = particles;
    this.setCharacter(character, images);
    this.reset();
  }
  setCharacter(character, images) {
    this.char = character;
    const img = k => images[character.id + ':' + k] || null;
    this.sheet = img('run'); this.jumpSheet = img('jump');
    this.skidSheet = img('skid'); this.shakeSheet = img('shake');
    this.idleSheet = img('idle');          // the standing loop for LOOK_DOWN
    this.hurtSheet = img('hurt');          // optional; falls back to reversed shake
    /* NO per-frame correction any more, and that is a fix rather than a removal.

       This used to measure each frame's lowest opaque pixel and lift the cell by the
       difference, to rescue sheets whose frames were not on a shared baseline. But the
       lowest pixel is not the feet: in a head-down pose it is the tip of the trunk, and
       "correcting" on it hoisted that frame up to 52px into the air — the character
       looked as though it were floating above the path and changing size between poses.

       tools/slice-char.mjs now finds the real foot line in every frame (the lowest row
       still carrying a quarter of the frame's width, so a trunk or a tail cannot be
       mistaken for a foot) and bakes every frame onto one shared row. So there is
       nothing left to correct, and correcting anyway would put the fault back. */
    this.footline = null;
    /* Frame counts, with the slots that no longer have art at zero rather than
       undefined — every `Math.min(F.x - 1, ...)` downstream would otherwise produce
       NaN and pick frame NaN. */
    this.F = Object.assign({ run: 0, jump: 0, skid: 0, shake: 0, hurt: 0 }, character.frames);
    this.J = character.jumpMap;
    this.scale = character.scale || CFG.sprite.scale;
    // world distance one full run cycle covers, which also sets the cycle's cadence
    this.stride = character.stride || 520;
    /* The frames a foot actually lands on. Without a list, fall back to the old
       assumption of two contacts at the start and the midpoint. */
    this.contacts = character.contacts && character.contacts.length
      ? character.contacts.slice()
      : [0, Math.floor((character.frames.run || 12) / 2)];
    this.koStars = !!character.koStars;
  }
  reset() {
    this.state = 'RUN'; this.t = 0; this.y = 0; this.vy = 0;
    this.airborne = false; this.lastGround = 0; this.bufferedJump = -1;
    this.squash = 1; this.tilt = 0; this.hop = 0;
    this.runDist = 0; this.lastStepFrame = -1;
    this.skidP = 0; this.sprayClock = 0; this.breath = 0; this.hopRising = false;
    /* THE CARTOON LAYER. One decaying amplitude (`scare`) drives a sideways knock, a
       nervous roll and a jelly squash; `lean` is the double take, `gulp` the swallow.
       All of it is applied in draw() and none of it is read by the collider. */
    this.scare = 0; this.tremorT = 0; this.lean = 0; this.leanWant = 0;
    this.gulp = 0; this.gulpClock = 0; this.sweatClock = 0;
    this.wobX = 0; this.wobRot = 0; this.wobSq = 0;
    this.knock = 0;                  // backward recoil from an impact, in px
  }
  /** 0..1 through the slide — drives which skid frame is showing. */
  setSkidProgress(p) { this.skidP = clamp(p, 0, 1); }
  setState(s) { if (this.state !== s) { this.state = s; this.t = 0; } }

  /** A SHUDDER, with no change of state. For the moment the ice cracks under him
      while he is still sliding, for a chunk hitting the water, and for a bump — the
      body reacts without interrupting whatever it was doing. */
  /* A JOLT NOW ACTUALLY MOVES HIM, and it had stopped.

     This only ever raised `scare`, which drove the procedural shudder — and that was
     removed once the delivered fright animation arrived. So the comment at the impact
     site promising "the wince carries on shaking after the hit" became false and the
     collision quietly lost its physical beat: the character stopped dead against the
     rock with no reaction, which is most of why the clash did not read.

     `knock` is a backward displacement that spikes on the hit and eases out. It is the
     single clearest statement that he ran into something solid — a body that stops
     without recoiling has not been hit, it has simply stopped. scare stays because the
     sweat and the gulp still read it. */
  jolt(power = 1) {
    const p = clamp(power, 0, 1.4);
    this.scare = Math.max(this.scare, p);
    this.knock = Math.max(this.knock || 0, p * CM_KNOCK);
  }

  /** THE FRIGHT: he has stopped, and he can see how wide the hole is.
      Enters SHAKE — which now holds for a real length of time rather than exiting on
      its first frame — and starts the double take, back off the lip and then in for
      a look. */
  startle(power = 1) {
    this.jolt(power);
    this.lean = 0;
    this.gulpClock = CFG.comedy.gulpEvery * 0.45;   // the first gulp lands during the shake
    this.setState('SHAKE');
    this.audio.gasp();
  }
  canJump(now) {
    return !this.airborne || (now - this.lastGround) < CFG.coyoteMs;
  }
  requestJump(now) {
    if (this.state !== 'RUN' && this.state !== 'JUMP_START' && this.state !== 'JUMP_AIR' && this.state !== 'LAND') return false;
    if (this.canJump(now) && !this.airborne) { this.doJump(); return true; }
    this.bufferedJump = now; return false;
  }
  doJump() {
    this.vy = CFG.jumpVel; this.airborne = true; this.setState('JUMP_START');
    if (this.onJump) this.onJump();
    /* STRETCH off the ground, not squash. It set 0.92 — shorter — which is the pose
       for LANDING, so the launch and the landing were doing the same thing and neither
       read as either. The crouch is already in the art (J.crouch); what the launch
       needs is the stretch that follows it. */
    this.squash = 1.13; this.audio.jump();
    this.particles.poof(CFG.mammothX - 10, CFG.surfaceY, 4, 0.8);
  }
  update(dt, now, moving, speed) {
    this.t += dt;
    /* The run cycle advances with DISTANCE TRAVELLED, not with wall time. Driven by
       a clock, the legs cycle at a fixed rate while the ground scrolls at whatever
       speed the run is set to, so the feet slide along the snow — the animation reads
       as skating rather than running. Tying the frame to ground travel means one
       stride always covers the same distance and the feet stay planted at any speed.
       `stride` is the world distance one full cycle covers, per character. */
    if (this.state === 'RUN' && moving) {
      const v = CFG.runSpeed * (speed === undefined ? 1 : speed);
      this.runDist += v * dt;

    }
    if (this.airborne) {
      this.vy += CFG.gravity * dt;
      this.y += this.vy * dt;
      if (this.state === 'JUMP_START' && this.t > 0.08) this.setState('JUMP_AIR');
      if (this.y >= 0) {
        this.y = 0; this.vy = 0; this.airborne = false; this.lastGround = now;
        /* A KNOCKOUT SURVIVES THE LANDING.

           This branch runs whatever state the character is in, so it used to overwrite
           KNOCKOUT with LAND — and LAND then falls through to IDLE_LOOK a fifth of a
           second later. Hitting the rock MID-AIR is the normal way to fail a jump, so
           the normal failure threw away the entire crash performance: the Try Again
           card is timed to arrive at 1.1s, by which point the character was standing
           there calmly as though nothing had happened.

           He still falls on real physics and still thumps into the snow. He just keeps
           the pose he was knocked into. */
        if (this.state !== 'KNOCKOUT') {
          // a real squash on arrival: with volume preserved on X this is the weight
          this.setState('LAND'); this.squash = 0.82;
        }
        this.audio.land(); this.particles.poof(CFG.mammothX, CFG.surfaceY, 6, 1.15);
      }
    } else {
      if (this.bufferedJump > 0 && now - this.bufferedJump < CFG.bufferMs &&
        (this.state === 'RUN' || this.state === 'LAND')) { this.bufferedJump = -1; this.doJump(); }
      if (this.state === 'LAND' && this.t > 0.18) this.setState(moving ? 'RUN' : 'IDLE_LOOK');
    }
    /* Footfalls are fired by the CYCLE, not by a timer. On a timer the crunch and the
       snow puff drift out of phase with the legs, which is most of why a run reads as
       fake. A quadruped cycle has two contacts, so the sound lands twice per stride
       at the same frames every time. */
    /* Footfalls fire on the frames a foot is actually DOWN, read from the character's
       measured contact list. Two things this fixes: the crunch used to be hard-coded to
       two contacts a cycle when this gait has four, and it fired on frame 0 and the
       midpoint whether or not a foot was there — so the sound and the legs were simply
       unrelated. Now the sample lands with the hoof. */
    if (this.state === 'RUN' && moving) {
      const f = Math.floor((this.runDist / this.stride) * this.F.run) % this.F.run;
      if (this.contacts.includes(f)) {
        if (f !== this.lastStepFrame) {
          this.lastStepFrame = f;
          this.audio.step();
          this.particles.skid(CFG.mammothX - 40, CFG.surfaceY, 1);
        }
      } else {
        this.lastStepFrame = -1;
      }
    }
    // spray is time-based, not per-frame, so a 144Hz display gets the same amount as a 60Hz one
    if (this.state === 'SKID_STOP') {
      this.sprayClock += dt;
      while (this.sprayClock > 0.06) {
        this.sprayClock -= 0.06;
        this.particles.skid(CFG.mammothX - 60, CFG.surfaceY, 1);
        this.particles.poof(CFG.mammothX - 74, CFG.surfaceY, 1, 0.75);   // a trail of little clouds behind the skidding feet
      }
    } else this.sprayClock = 0;
    /* Once the tremble has played out, settle into peering into the crevasse.

       THE `: 0` USED TO BE A BUG. With no shake sheet this read `t > 0`, so the
       fright state was left on the frame after it was entered and the mammoth never
       visibly reacted to the hole at all. The fallback is now a real duration, which
       is what the procedural shudder below plays across. */
    if (this.state === 'SHAKE' &&
        this.t > (this.F.shake ? this.F.shake / CFG.sprite.tremorFps
                               : CFG.comedy.shakeHoldMs / 1000)) this.setState('LOOK_DOWN');

    /* ---- NO PROCEDURAL SHUDDER ----
     *
     * There used to be one: a sideways knock, a nervous roll and a jelly squash, all
     * driven off a decaying `scare` amplitude and applied ON TOP of whatever frame was
     * showing. Its own comment gave the reason it existed — "because the fright has no
     * art of its own" — and that reason is gone: there is a delivered 36-frame fright
     * animation now, and the character reacts to the hole in the art itself.
     *
     * Two performances of the same beat played at once do not add up, they fight. The
     * drawn reaction has its own timing and weight; a sine wave shoving the whole
     * sprite sideways over it reads as the picture vibrating rather than the animal
     * being frightened. Removed on that basis, not as a tidy-up.
     *
     * `scare` itself stays, and still decays: it is read by the sweat beads and by the
     * gulp clock below, which are separate cues and not a second copy of the fright.
     * The wobble fields stay at zero so the renderer needs no special case.
     *
     * The screen shake and the earthquake are NOT this. They move the camera on impact,
     * they are not a character animation, and they are untouched. */
    const CM = CFG.comedy;
    this.tremorT += dt;
    this.scare = Math.max(0, this.scare - dt / CM.scareDecay);
    const peering = this.state === 'SHAKE' || this.state === 'LOOK_DOWN';
    this.wobX = 0; this.wobRot = 0; this.wobSq = 0;
    /* DECAYS, it does not reset. Zeroing it here — which is what the first version
       of this did — cancels the recoil on the very next frame after the hit, so the
       displacement is set and then thrown away before it is ever drawn. It eases out
       over about a third of a second instead. */
    // held while he is down, so the knocked-out pose stays clear of the rock; eases back after
    const down = this.state === 'KNOCKOUT' || this.state === 'HURT';
    if (this.knock > 0 && !down) this.knock = Math.max(0, this.knock - dt * CM_KNOCK * 3.1);

    /* AND NO PROCEDURAL DOUBLE TAKE while the fright is playing, for the same reason:
       the delivered animation already recoils and settles, so sliding the sprite
       backwards then forwards on top of it moved the character against its own feet.
       SURPRISED keeps its recoil — that state has no art of its own. */
    this.leanWant = this.state === 'SURPRISED' ? -CM.recoilPx * 0.7 : 0;
    this.lean = lerp(this.lean, this.leanWant, clamp(dt * 4, 0, 1));

    /* A SWALLOW, on a slow clock, for as long as he is over the hole. The learner can
       sit on this pose for minutes; a breath alone is not enough to keep it alive, and
       a gulp is the one idle beat that stays funny on the twentieth repeat. */
    if (peering) {
      this.gulpClock += dt;
      if (this.gulpClock > CM.gulpEvery) { this.gulpClock = 0; this.gulp = 1; this.audio.gulp(); }
    } else this.gulpClock = 0;
    this.gulp = Math.max(0, this.gulp - dt * 2.6);

    /* Beads flicked off the head — only while he is STOPPED and rattled. Gating on
       the amplitude alone threw sweat during the skid, which is both wrong (the joke
       is the moment he stops and looks) and the one place it cost measurable frame
       time, because the skid is already the busiest frame in the game.

       It reads `scare` directly now. It used to read `amp`, which was the shudder's
       own amplitude — scare plus a residual quiver while peering — and that local
       went with the shudder. Leaving the reference behind threw once per frame for
       the whole fright, and because the throw aborted update() partway the fright
       never advanced past its first frame: the delivered animation looked frozen.
       The threshold is lowered to 0.2 to match, since the old value included the
       0.17 quiver that no longer exists. */
    if (peering && this.scare > 0.2) {
      this.sweatClock += dt;
      if (this.sweatClock > CM.sweatEvery) {
        this.sweatClock = 0;
        this.particles.sweat(CFG.mammothX + 82, this.feetY - 296, 1);
      }
    } else this.sweatClock = 0;
    // a mid-run wince recovers by itself, so the run is never left stuck in HURT
    if (this.state === 'HURT' && moving && this.t > 0.55) this.setState('RUN');
    // A knockout holds its last frame instead of looping: the learner may sit on
    // this pose until they press Try Again, and a looping wince reads as a twitch.
    /* FIVE WRITE-ONLY FIELDS HAVE BEEN REMOVED FROM THIS BLOCK, and it is worth saying
       what they were, because they look like features rather than dead weight:

         trunkLift  0..1, meant to raise the trunk on a celebrate and a surprise
         eye        1..1.5, meant to widen the eye on a surprise
         knockT     the knockout's own clock
         stepClock  a footfall timer, superseded by the distance-driven contact list
         runClock   "still used for the idle timers", said its comment. Nothing read it.

       The first two could never have worked: the character is delivered as whole-body
       frames, so there is no trunk and no eye for the renderer to move independently.
       All five were computed every frame, some through a lerp, and read by nothing.
       The expressive beats they were reaching for are now real, and procedural: the
       hop below, and the shudder / double take / gulp in the block above. */
    if (this.state === 'CELEBRATE') {
      const hopPrev = this.hop;
      this.hop = Math.abs(Math.sin(this.t * 7)) * 26 * clamp(1.4 - this.t, 0, 1);
      // hopRising IS read — it picks the rising or falling jump frame, see draw()
      this.hopRising = this.hop >= hopPrev;
    } else if (this.state === 'SURPRISED') {
      this.hop = 0;
    } else {
      this.hop = lerp(this.hop, 0, dt * 10);
    }
    /* Breathing on the held poses. LOOK_DOWN, IDLE_LOOK and SURPRISED each play
       their sheet once and then hold a single frame — and the learner can sit on
       LOOK_DOWN for a minute while they think about the shape. A character frozen
       stone-still for that long reads as a hung game. Pre-rendered frames cannot
       supply this, so it is procedural: a slow rise and fall with a matching
       narrowing, about 3px on a 290px character. */
    const held = this.state === 'LOOK_DOWN' || this.state === 'IDLE_LOOK' ||
                 this.state === 'SURPRISED' || this.state === 'KNOCKOUT';
    this.breath = held ? lerp(this.breath || 0, Math.sin(this.t * 1.75), clamp(dt * 6, 0, 1))
                       : lerp(this.breath || 0, 0, clamp(dt * 8, 0, 1));
    // snappier recovery: a squash that eases back slowly reads as a wobble in the art
    this.squash = lerp(this.squash, 1, clamp(dt * 12, 0, 1));
    // the skid sheet already carries the backward lean, so don't rotate on top of it
    const wantTilt = this.state === 'JUMP_AIR' ? (this.vy < 0 ? -0.1 : 0.05) : 0;
    this.tilt = lerp(this.tilt, wantTilt, dt * 7);
  }
  get feetY() { return CFG.surfaceY + this.y - this.hop; }
  /* `bare` draws the character ALONE — no contact shadow. The tutorial re-draws him on
     its focus canvas and puts a glow round whatever has alpha there; a shadow ellipse
     under his feet would have glowed as a second, floating shape. */
  draw(ctx, t, bare) {
    const img = this.sheet;
    const x = CFG.mammothX, y = this.feetY;
    const CW = CFG.sprite.cw, CH = CFG.sprite.ch, S = this.scale;

    if (!bare) {
    // Soft contact shadow. A flat hard-edged ellipse read as a grey decal sitting on
    // the snow, which made the character look pasted on; a radial falloff centred at
    // the footline reads as contact instead.
    const shA = clamp(1 + this.y / 260, 0.15, 1);
    const sx0 = x + 4, sy0 = CFG.surfaceY + 2;
    const rx = 92 * shA, ry = 15 * shA;
    ctx.save();
    ctx.translate(sx0, sy0);
    ctx.scale(1, ry / rx);
    const rg = ctx.createRadialGradient(0, 0, 0, 0, 0, rx);
    rg.addColorStop(0, `rgba(18,59,104,${(0.34 * shA).toFixed(3)})`);
    rg.addColorStop(0.5, `rgba(18,59,104,${(0.19 * shA).toFixed(3)})`);
    rg.addColorStop(0.8, `rgba(18,59,104,${(0.06 * shA).toFixed(3)})`);
    rg.addColorStop(1, 'rgba(18,59,104,0)');
    ctx.fillStyle = rg;
    ctx.beginPath(); ctx.arc(0, 0, rx, 0, 6.2832); ctx.fill();
    ctx.restore();
    }
    if (!img) return;

    const J = this.J, SP = CFG.sprite, F = this.F;
    let sheet = this.jumpSheet || img, f = J.idle;
    switch (this.state) {
      case 'RUN':
        sheet = img;
        f = Math.floor((this.runDist / this.stride) * F.run) % F.run;
        break;
      case 'JUMP_START': f = this.t < 0.045 ? J.crouch : J.launch; break;
      case 'JUMP_AIR':
        f = this.vy < -420 ? J.rise : this.vy < 160 ? J.apex : this.vy < 760 ? J.fall : J.preLand; break;
      case 'LAND': f = this.t < 0.09 ? J.land : J.absorb; break;
      case 'SKID_STOP':
        if (this.skidSheet) { sheet = this.skidSheet; f = Math.min(F.skid - 1, Math.floor(this.skidP * F.skid)); }
        else f = J.crouch;
        break;
      // Both play the sheet through ONCE and hold the last frame — a looping tremble
      // read as a twitch, and the learner may sit on this pose for minutes.
      case 'SHAKE':
        if (this.shakeSheet && F.shake) { sheet = this.shakeSheet; f = Math.min(F.shake - 1, Math.floor(this.t * SP.tremorFps)); }
        else f = J.alert;
        break;
      case 'LOOK_DOWN':
        /* HOLDS THE FINAL FRAME OF THE DELIVERED FRIGHT. That frame is the pose the
           character has just settled into after reacting to the hole, so holding it is
           continuous with what the learner watched — this state is where the reaction
           ENDS, not a second performance of it.

           A looping breathing idle was tried here and held back: there is a delivered
           idle sheet ready to go (see the note in CFG.characters.sheets), and replacing
           the arrived-at pose with a neutral loop discards the reaction. Turn it on by
           uncommenting the branch below and listing the sheet.

           Deliberately not `alert` as the last resort: the learner may sit here for
           minutes, and a startled face held that long reads as the game having hung. */
        // if (this.idleSheet && F.idle) {
        //   sheet = this.idleSheet; f = Math.floor(this.t * SP.idleFps) % F.idle;
        // } else
        if (this.shakeSheet && F.shake) { sheet = this.shakeSheet; f = F.shake - 1; }
        else f = J.idle;
        break;
      // Winces on impact. Uses a dedicated hurt sheet if one is ever added, and
      // otherwise reads the head-down shake frames backwards as a recoil.
      case 'KNOCKOUT': {
        /* FROM THE CLASH, not from the start of the sheet — see KO_CLASH. The impact
           has already happened by the time this state is entered, so the frames of
           the character trotting in are behind us; playing them put a run pose on the
           frame of the collision. Runs clash -> tumble -> dazed sit, then holds. */
        const src = this.hurtSheet || this.shakeSheet;
        const nf = this.hurtSheet ? F.hurt : F.shake;
        if (src && nf) {
          sheet = src;
          if (this.hurtSheet) {
            const last = Math.min(nf - 1, KO_LAST);
            f = Math.min(last, KO_CLASH + Math.floor(this.t * SP.koFps));
          } else {
            // no dedicated hurt art: read the tremble backwards so it reads as a recoil
            f = nf - 1 - Math.min(nf - 1, Math.floor(this.t * SP.koFps));
          }
        } else f = J.alert;
        break;
      }
      case 'HURT':
        /* The wince a running character takes on the third strike. Same reasoning as
           KNOCKOUT: start at the clash, and stop before the tumble — this state
           returns to RUN by itself, so a somersault would be cut off halfway. */
        if (this.hurtSheet && F.hurt) {
          sheet = this.hurtSheet;
          const stop = Math.min(F.hurt - 1, KO_CLASH + 8);
          f = Math.min(stop, KO_CLASH + Math.floor(this.t * SP.tremorFps));
        }
        else if (this.shakeSheet && F.shake) {
          sheet = this.shakeSheet;
          const k = Math.min(F.shake - 1, Math.floor(this.t * SP.tremorFps));
          f = F.shake - 1 - k;
        } else f = J.alert;
        break;
      case 'SURPRISED': f = J.alert; break;
      case 'IDLE_LOOK':
        /* THE DELIVERED IDLE ANIMATION, not a pose borrowed from the jump sheet.

           This read `f = J.idle`, which is one frame of the JUMP sheet picked because
           it happens to be a settled grounded pose. It was the only thing available
           when there was no idle art — but it means the character stands stock still in
           a pose drawn for a different purpose, and against the newer delivered sheets
           it reads as older, stiffer art. The idle sheet is loaded now (it was brought
           in for the finale), so this uses it and the character breathes. */
        if (this.idleSheet && F.idle) {
          sheet = this.idleSheet;
          f = Math.floor(this.t * SP.idleFps) % F.idle;
        } else f = J.idle;
        break;
      case 'CELEBRATE': {
        /* A real hop, read off the hop arc. The old version picked between two
           frames on `hop > 8`, and because hop is |sin(t*7)| that threshold is
           crossed about fourteen times a second — the sprite flickered between two
           poses instead of hopping. */
        const up = clamp(this.hop / 26, 0, 1);
        /* ONCE THE HOP IS SPENT, BREATHE. The hop decays to nothing at t = 1.4s, after
           which `up` is 0 and this expression returns the same frame forever — so the
           character froze mid-celebration and stayed frozen for as long as the ending
           was on screen, which is precisely the moment he should look most alive.
           The delivered idle sheet loops instead. */
        if (this.t > 1.4 && this.idleSheet && F.idle) {
          sheet = this.idleSheet;
          f = Math.floor(this.t * SP.idleFps) % F.idle;
          break;
        }
        f = this.t < 0.09 ? J.crouch
          : up > 0.72 ? J.apex
          : up > 0.3 ? (this.hopRising ? J.rise : J.fall)
          : (this.hopRising ? J.launch : J.land);
        break;
      }
    }

    this.lastFrame = f;
    this.lastSheet = sheet === this.sheet ? 'run' : sheet === this.jumpSheet ? 'jump'
      : sheet === this.skidSheet ? 'skid' : sheet === this.shakeSheet ? 'shake'
      : sheet === this.hurtSheet ? 'hurt' : sheet === this.idleSheet ? 'idle' : '?';
    /* GROUNDED poses are placed on THIS frame's own footline. A run cycle's vertical
       variation is the bob and has to be kept, and an airborne frame's tucked legs are
       the art; but a pose the character holds while standing still has no business
       floating, and LOOK_DOWN holds one for as long as the puzzle takes. */
    const GROUNDED = this.state === 'SKID_STOP' || this.state === 'SHAKE' ||
                     this.state === 'LOOK_DOWN' || this.state === 'KNOCKOUT' ||
                     this.state === 'SURPRISED' || this.state === 'IDLE_LOOK' ||
                     this.state === 'CELEBRATE';
    // the art is aligned on its own foot line, so nothing needs lifting
    const lift = 0;

    const br = this.breath || 0;
    /* THE CARTOON TRANSFORM, over the top of the sheet's own frame.

       Everything here is drawn about the FOOT LINE — the translate lands on feetY and
       the scales happen after it — so a squash keeps the feet planted and a stretch
       grows upward, which is what squash and stretch mean. The one exception is
       `wobX`, which moves him sideways on purpose: knees knocking is a sideways
       motion, and the contact shadow above is deliberately NOT wobbled, so the feet
       read as skidding under a body that cannot keep still.

       VOLUME IS PRESERVED. `squash` used to scale Y alone, so a landing made him
       shorter without making him wider and read as the sprite being resized rather
       than as weight arriving. Taking the inverse square root on X is the standard
       constant-area cheat and it is what turns the same number into an impact. */
    const sq = this.squash * (1 + br * 0.006) * (1 - this.wobSq) * (1 - this.gulp * 0.05);
    const sqX = (1 - br * 0.008) * (1 + this.wobSq * 0.85) / Math.sqrt(Math.max(0.35, sq));
    ctx.save();
    // knock is subtracted: a recoil is backward, which is left on this stage
    ctx.translate(x + this.wobX + this.lean - this.knock, y - br * 3 + this.gulp * 3);
    ctx.rotate(this.tilt + this.wobRot);
    // the breath narrows as it lifts, the way a chest does
    ctx.scale(sqX, sq);
    // the sheets carry a small gap under the footline so nothing is clipped, so the
    // cell is dropped by that gap to put the content baseline on feetY
    ctx.drawImage(sheet, f * CW, 0, CW, CH,
                  -CW * S / 2, -CH * S + CFG.sprite.baseGap * S + lift, CW * S, CH * S);
    ctx.restore();
  }
}

/* ---------------- GroundManager (path tiles + gaps) ---------------- */
class GroundManager {
  constructor(img) {
    this.img = img;
    const p = CFG.path;
    this.src = { x: p.tileX, w: p.tileW, h: p.srcH };
    this.tw = Math.round(p.tileW * p.scale);   // tile width of the CROPPED span
    this.th = Math.round(p.srcH * p.scale);
    this.ty = CFG.surfaceY - p.surfaceRatio * this.th;
    /* WHERE THE PATH ART'S CONTENT ACTUALLY ENDS — y 1033 of a 1080 stage. The image is
       657px tall but its painted rock stops at contentBottom (73.2%) and the rest is
       transparent, so this is the line below which there was nothing but the stage's own
       background until drawDeepWater() put the sea there. Kept as a measurement: it is
       what says whether the water is still needed if surfaceY or the art ever change. */
    this.contentY = this.ty + p.contentBottom * this.th;
    this.gaps = [];
  }
  reset() { this.gaps = []; }
  addGap(g) { this.gaps.push(g); return g; }

  /* Every open crevasse, repaired or not, in screen space. A repaired one stays cut
     out of the path: the ice bridge spanning it is drawn on top, and the melt water
     is still visible far below — which is what makes the repair read as a bridge
     over a chasm rather than as ground that was never broken. */
  openGaps(worldX) {
    return this.gaps.filter(g => g.open > 0.01)
      .map(g => ({ x0: g.x0 - worldX, x1: g.x1 - worldX, g }));
  }


  /* A natural crevasse, not a socket. The lips are broken snow, the walls pinch in
     towards the middle depth and open out again, and the whole thing is generated
     once from the gap's own position so it never jitters between frames. Nothing
     about its outline hints at which shape repairs it. */
  _profile(g) {
    if (g.prof) return g.prof;
    let seed = Math.abs(Math.round(g.x0)) % 9973 + 17;
    const rnd = () => (seed = (seed * 9301 + 49297) % 233280) / 233280;
    const N = 22;
    const top = Array.from({ length: N + 1 }, (_, i) => {
      const u = i / N;
      const edge = Math.min(u, 1 - u);
      /* THE TOP EDGE NEVER GOES BELOW THE WALKING LINE, and that is what removed the
         sharp spikes hanging off the lip.

         They were never drawn by this game — they are the PATH ARTWORK's own icicle
         fringe. The path is clipped to everything OUTSIDE the crevasse, so wherever
         this profile dipped under surfaceY the artwork below the line survived the
         clip, and what showed was a row of icicles cut off flat: hard-edged triangles
         that read as sharp vectors stuck to the lip.

         The old range was -9..+21, so most of the span sat below the line. Now it is
         -15..-2: always above it, so the fringe is always clipped away, and the lip
         still varies enough to read as broken rather than as a ruled edge. */
      /* -9..-2 across the neck (was -15..-2): the plug now seats 9px proud of the walking
         line so its own edge covers this chew — a deeper bite showed as a dark sliver
         above the answer. Still always ABOVE surfaceY, which is load-bearing: see above. */
      return { u, dy: edge < 0.05 ? -3 - rnd() * 4 : -9 + rnd() * 7 };
    });
    /* THIRTEEN POINTS WITH ROCK-SCALE JITTER, not seven on a smooth curve. The wall is
       stacked boulders now, and a boulder wall has no smooth line down it: each course
       sits a little in or out of the last. The pinch toward mid-depth is kept under the
       jitter, so the crack still narrows and opens like a crack. */
    const wall = () => Array.from({ length: 13 }, (_, i) => {
      const v = i / 12;
      if (v < 0.02 || v > 0.98) return { v, f: 0 };
      return { v, f: Math.sin(v * Math.PI) * (0.05 + rnd() * 0.06) + (rnd() - 0.5) * 0.07 };
    });
    g.prof = { top, L: wall(), R: wall() };
    return g.prof;
  }

  /** One path describes the crevasse; every layer inside it is clipped to that path. */
  _ditchPath(x0, x1, g) {
    const pr = this._profile(g);
    const w = x1 - x0, y0 = CFG.surfaceY, yB = CFG.H + 80, span = yB - y0;
    const p = new Path2D();
    /* AN UNDERCUT, which is the one shape that lets the gap be BIG and the plug fit it
       with nothing added. The plug cannot be wider than about 243 (see §10), so the
       OPENING at the surface is plug-wide — the neck, `g.throat` — and the size lives
       BELOW: from `throatDepth` down the walls flare out to the full width of the
       record (the void), so the lips overhang a wide dark chasm. The plug's flat edge
       spans the neck exactly, resting on the lips by the bearing, and nothing has to
       be drawn over it. A wide MOUTH with the plug in a narrower throat was the
       previous shape; it needed an ice collar to close the shoulders, and the collar
       read as snow laid over the answer. */
    const mk = g && g.throat ? (g.x1 - g.x0) / g.throat : 1;
    const ins = mk > 1 ? w * (1 - 1 / mk) / 2 : 0;          // half the overhang, each side
    const T = CFG.levelOne.throatDepth || 0, tv = span > 0 ? (T + 60) / span : 0;
    const nx0 = x0 + ins, nx1 = x1 - ins, nw = nx1 - nx0;     // the neck
    p.moveTo(nx0, y0 + pr.top[0].dy);
    /* THE TOP EDGE IS CURVED, not a polyline — a quadratic through the midpoints of the
       chewed profile turns every corner into a rounded bite. It runs across the neck. */
    for (let i = 0; i < pr.top.length - 1; i++) {
      const a = pr.top[i], b = pr.top[i + 1];
      const ax = nx0 + nw * a.u, bx = nx0 + nw * b.u;
      p.quadraticCurveTo(ax, y0 + a.dy, (ax + bx) / 2, y0 + (a.dy + b.dy) / 2);
    }
    { const last = pr.top[pr.top.length - 1]; p.lineTo(nx0 + nw * last.u, y0 + last.dy); }
    // right side: down the neck, then the overhang curls out to the void wall
    p.lineTo(nx1, y0);
    p.lineTo(nx1, y0 + T);
    if (ins > 0) p.quadraticCurveTo(nx1 + ins * 0.15, y0 + T + 52, x1, y0 + T + 60);
    for (const q of pr.R) if (q.v > tv) p.lineTo(x1 - w * q.f, y0 + span * q.v);
    p.lineTo(x1, yB);
    p.lineTo(x0, yB);
    for (let i = pr.L.length - 1; i >= 0; i--) { const q = pr.L[i]; if (q.v > tv) p.lineTo(x0 + w * q.f, y0 + span * q.v); }
    if (ins > 0) p.quadraticCurveTo(nx0 - ins * 0.15, y0 + T + 52, nx0, y0 + T);
    else p.lineTo(nx0, y0 + T);
    p.lineTo(nx0, y0);
    p.closePath();
    return p;
  }

  /** Water surface height at a screen x, so ripples and splashes agree on one line. */
  waterY(x, t) {
    const wy = CFG.surfaceY + CFG.levelOne.waterDepth;
    return wy + Math.sin(x * 0.028 + t * 1.7) * 2.4 + Math.sin(x * 0.0105 - t * 1.05) * 1.7;
  }

  /** A chunk went in: ring out from the entry point and throw a crown of droplets. */
  addSplash(g, x, t) {
    if (!g.splashes) g.splashes = [];
    g.splashes.push({ x, t0: t, drops: Array.from({ length: 14 }, (_, i) => ({
      a: -Math.PI / 2 + (i / 13 - 0.5) * 2.1,
      v: 130 + (i % 5) * 46,
      r: 3 + (i % 4)
    })) });
    if (g.splashes.length > 4) g.splashes.shift();
  }

  drawDitch(ctx, worldX, t) {
    const L1 = CFG.levelOne;
    for (const s of this.openGaps(worldX)) {
      const w = (s.x1 - s.x0) * s.g.open;
      if (!(w > 1)) continue;
      const cx = (s.x0 + s.x1) / 2;
      const x0 = cx - w / 2, x1 = cx + w / 2;
      const wy = CFG.surfaceY + L1.waterDepth;
      ctx.save();
      ctx.clip(this._ditchPath(x0, x1, s.g));

      /* --- THE INSIDE OF THE CREVASSE ---

         All of this detail was here before and almost none of it was visible. The
         reason was where it sat: the wall light was 74px wide on a 620px hole and the
         ice ledges were 34px triangles at the very edges, so 88% of the width was one
         flat navy fill and the thing read as a dark hole cut in a paper background
         rather than as a crack in ice.

         So the depth cues now run across the WHOLE width, in the order a real crevasse
         reads: an overhang shadow with a hard top edge, a far wall you can see, vertical
         ice facets down it, icicles hanging off the lip, and cold vapour coming out. */

      // the body of the crack — brighter at depth, because the water bounces light up
      const g1 = ctx.createLinearGradient(0, CFG.surfaceY - 20, 0, wy);
      g1.addColorStop(0, '#0E3358');
      g1.addColorStop(0.40, '#123F69');
      g1.addColorStop(0.82, '#1C5F8E');
      g1.addColorStop(1, '#2A7BA8');
      ctx.fillStyle = g1; ctx.fillRect(x0 - 6, CFG.surfaceY - 40, w + 12, wy - CFG.surfaceY + 60);
      /* THE WALLS ARE ROCK — the platform's own stone base, tiled down each side of the
         hole and fading into the dark as it goes — see _wallArt. Before this the
         interior was the gradient above and nothing else, and however the lips were
         dressed the hole read as a shape cut out of paper: a crevasse is a break in
         something, and the something has to be visible in its walls. Each wall takes
         at most 38% of the width, so the middle stays dark and deep; its inner edge is
         the boulders' own silhouettes, not a straight line. */
      /* THE FAR WALL. Between the two side walls there used to be nothing but the
         gradient above — most of the mouth was one flat colour, and a flat colour with
         soft edges is exactly what a hole cut out of a picture looks like. A crack has
         a back: you look INTO it and see stone all the way across. So the same rock
         band is tiled across the whole interior first, smaller and pulled toward the
         dark so it reads as farther away, with the shadow of the snow overhang laid
         under the lip. The side walls then sit in front of it, brighter and closer. */
      const back = this._backArt(Math.round(w / 24) * 24);
      if (back) {
        ctx.drawImage(back.canvas, 0, 0, back.w, back.h, Math.round(x0 - 8), CFG.surfaceY - 24, Math.round(w + 16), back.h);
        const sh = ctx.createLinearGradient(0, CFG.surfaceY - 24, 0, CFG.surfaceY + 70);
        sh.addColorStop(0, 'rgba(3,16,38,0.72)'); sh.addColorStop(1, 'rgba(3,16,38,0)');
        ctx.fillStyle = sh; ctx.fillRect(x0 - 8, CFG.surfaceY - 24, w + 16, 94);
      }
      const wallW = Math.round(Math.min(150, Math.max(56, w * 0.38)));
      const wl = this._wallArt('l', wallW), wr = this._wallArt('r', wallW);
      if (wl && wr) {
        const top = CFG.surfaceY - 14;
        ctx.drawImage(wl.canvas, Math.round(x0 - 10), top);
        ctx.save();
        ctx.translate(Math.round(x1 + 10), 0);
        ctx.scale(-1, 1);
        ctx.drawImage(wr.canvas, 0, top);
        ctx.restore();
      }
      /* MIST off the melt water, thickening toward the bottom. Depth reads as loss of
         contrast with distance; the stone lower down fades into cold haze the way the
         bottom of a real crevasse does, and it is what makes the drop read as deep. */
      const mist = ctx.createLinearGradient(0, wy - 150, 0, wy + 10);
      mist.addColorStop(0, 'rgba(176,222,246,0)'); mist.addColorStop(0.7, 'rgba(176,222,246,0.28)'); mist.addColorStop(1, 'rgba(196,232,250,0.5)');
      ctx.fillStyle = mist; ctx.fillRect(x0 - 8, wy - 150, w + 16, 160);

      /* THE FAR WALL — FEWER, BIGGER, SOFTER.

         Two attempts got this wrong in opposite directions and both are worth recording.
         First it was one flat navy fill with the wall light crammed into 74px at each
         edge, so 88% of the width was a dead colour and the hole read as a shape cut in
         paper. The fix for that went far too far: forty hashed rectangles, four
         scribbled cracks and a row of uniform icicles right across the span. It was
         reported as cluttered, unrealistic and odd, and it was — hard-edged pale
         rectangles read as torn paper pasted on, and thin dark strokes read as
         scratches rather than as ice under stress.

         The lesson is that a CARTOON crevasse is not a detailed one. Depth here comes
         from a few big soft value shapes, not from many small ones:

           - one clean vertical gradient, darkest under the lip and brightening toward
             the water, because light really does bounce up off the pool
           - a wide gentle wall light from each side, meeting in the middle
           - THREE big soft ice shelves, rounded, no hard edges
           - a handful of icicles, only near the corners where the lip is thickest

         Everything else was removed. */

      // wet glacier walls, wide and soft, meeting in the middle
      const lightW = Math.max(120, w * 0.42);
      for (const side of [0, 1]) {
        const ex = side ? x1 : x0, dir = side ? -1 : 1;
        const wg = ctx.createLinearGradient(ex, 0, ex + dir * lightW, 0);
        wg.addColorStop(0, 'rgba(176,230,251,0.60)');
        wg.addColorStop(0.45, 'rgba(150,216,246,0.22)');
        wg.addColorStop(1, 'rgba(126,200,238,0)');
        ctx.fillStyle = wg;
        ctx.fillRect(side ? x1 - lightW : x0, CFG.surfaceY - 20, lightW, wy - CFG.surfaceY + 40);
      }

      /* THE SOFT SHELVES ARE GONE TOO. They were three big pale ellipses meant to read
         as slabs of ice caught on the walls, and they read as amorphous smudges
         floating in the middle of the crack — soft-edged blobs with no orientation and
         nothing to attach them to a surface. That is the third thing removed from this
         wall, and the pattern across all three is the same: every attempt to add
         DETAIL made the crevasse worse, and every removal made it better. What is left
         is the gradient, the wall light and the icicles at the corners. Leave it. */

      /* NO ICICLES. They were the last piece of added detail on this wall, and they
         went the same way as the rest: drawn as hard-edged triangles they read as sharp
         vector spikes stuck onto the lip rather than as ice.

         That is five things now removed from the inside of this crevasse — even
         columns, hashed rectangles, stress cracks, soft shelves and these teeth — and
         the score is unambiguous: every attempt to add DETAIL made it worse and every
         removal made it better. What is left is one gradient, a wide soft wall light,
         a rounded bitten lip and the pool at the bottom, and THAT is what reads as a
         crack in ice. Do not add anything else to it. */


      // --- the melt pool ---
      const body = ctx.createLinearGradient(0, wy, 0, CFG.H + 40);
      body.addColorStop(0, '#2E9FC9');
      body.addColorStop(0.30, '#1B7BA8');
      body.addColorStop(1, '#0C4A70');
      ctx.save();
      // the surface is a wave, so the water never reads as a flat rectangle
      const surf = new Path2D();
      surf.moveTo(x0 - 6, this.waterY(x0 - 6, t));
      for (let px = x0 - 6; px <= x1 + 6; px += 10) surf.lineTo(px, this.waterY(px, t));
      surf.lineTo(x1 + 6, CFG.H + 40);
      surf.lineTo(x0 - 6, CFG.H + 40);
      surf.closePath();
      ctx.clip(surf);
      ctx.fillStyle = body;
      ctx.fillRect(x0 - 8, wy - 10, w + 16, CFG.H + 60 - wy);
      // wall colour bleeding into the water as a reflection
      const refl = ctx.createLinearGradient(0, wy, 0, wy + 46);
      refl.addColorStop(0, 'rgba(196,236,252,0.46)');
      refl.addColorStop(1, 'rgba(174,224,248,0)');
      ctx.fillStyle = refl; ctx.fillRect(x0 - 8, wy, w + 16, 46);
      // drifting highlight streaks
      ctx.fillStyle = 'rgba(226,248,255,0.20)';
      for (let i = 0; i < 4; i++) {
        const sx = x0 + ((i * 0.3129 + t * 0.05) % 1) * w;
        const sy = wy + 14 + i * 13;
        ctx.beginPath();
        ctx.ellipse(sx, sy, 34 - i * 5, 2.2, 0, 0, 6.2832);
        ctx.fill();
      }
      ctx.restore();

      ctx.restore();
    }
  }

  /* The water's surface, drawn AFTER anything falling into it so a chunk visibly
     goes under rather than sitting on top of the pool. */
  drawWaterFront(ctx, worldX, t) {
    const L1 = CFG.levelOne;
    for (const s of this.openGaps(worldX)) {
      const w = (s.x1 - s.x0) * s.g.open;
      if (!(w > 1)) continue;
      const cx = (s.x0 + s.x1) / 2;
      const x0 = cx - w / 2, x1 = cx + w / 2;
      ctx.save();
      ctx.clip(this._ditchPath(x0, x1, s.g));

      // the bright meniscus along the wave itself
      ctx.save();
      ctx.strokeStyle = 'rgba(240,253,255,0.98)';
      ctx.lineWidth = 4.5; ctx.lineJoin = 'round';
      ctx.beginPath();
      ctx.moveTo(x0 - 6, this.waterY(x0 - 6, t));
      for (let px = x0 - 6; px <= x1 + 6; px += 10) ctx.lineTo(px, this.waterY(px, t));
      ctx.stroke();
      ctx.restore();

      // floating ice flecks bobbing on the surface
      ctx.fillStyle = 'rgba(240,252,255,0.85)';
      for (let i = 0; i < 5; i++) {
        const fx = x0 + ((i * 0.417 + t * 0.028) % 1) * w;
        const fy = this.waterY(fx, t) - 2;
        ctx.beginPath();
        ctx.ellipse(fx, fy, 9 - i, 3.2, Math.sin(t + i) * 0.15, 0, 6.2832);
        ctx.fill();
      }

      // --- splashes ---
      if (s.g.splashes) {
        for (const sp of s.g.splashes) {
          const age = t - sp.t0;
          if (age < 0 || age > 1.5) continue;
          const sy = this.waterY(sp.x, t);
          const u = age / 1.5;
          // expanding rings
          ctx.save();
          ctx.strokeStyle = `rgba(236,252,255,${(0.75 * (1 - u)).toFixed(3)})`;
          ctx.lineWidth = 3 * (1 - u) + 0.6;
          for (let k = 0; k < 3; k++) {
            const ru = clamp(u * 1.6 - k * 0.18, 0, 1);
            if (ru <= 0) continue;
            ctx.beginPath();
            ctx.ellipse(sp.x, sy + 2, 24 + ru * 118, (24 + ru * 118) * 0.17, 0, 0, 6.2832);
            ctx.stroke();
          }
          ctx.restore();
          // the crown: a short-lived plume straight up out of the hole it punched
          if (age < 0.55) {
            const cu = age / 0.55;
            ctx.save();
            ctx.globalAlpha = 1 - cu;
            ctx.fillStyle = 'rgba(226,248,255,0.9)';
            const ch = 74 * Math.sin(cu * Math.PI);
            ctx.beginPath();
            ctx.moveTo(sp.x - 26, sy + 4);
            ctx.quadraticCurveTo(sp.x - 12, sy - ch, sp.x, sy - ch * 1.15);
            ctx.quadraticCurveTo(sp.x + 12, sy - ch, sp.x + 26, sy + 4);
            ctx.closePath(); ctx.fill();
            ctx.restore();
          }
          // droplets thrown clear of the surface
          ctx.fillStyle = 'rgba(232,250,255,0.92)';
          for (const d of sp.drops) {
            const dy = sy - (Math.sin(d.a) * -1) * 0;
            const px = sp.x + Math.cos(d.a) * d.v * age;
            const py = sy + Math.sin(d.a) * d.v * age + 620 * age * age;
            if (py > sy + 6) continue;
            ctx.globalAlpha = clamp(1 - age / 0.85, 0, 1);
            ctx.beginPath(); ctx.arc(px, py + dy * 0, d.r, 0, 6.2832); ctx.fill();
          }
          ctx.globalAlpha = 1;
        }
      }
      ctx.restore();
    }
  }

  /** The path's tiles, with no crevasse cut out of them. Split out of draw() so the
      clipped and the unclipped case share one loop. */
  /* THE PATH, TILED — AND EVERY OTHER TILE IS MIRRORED.

     The art is a finished 1640px segment, not a seamless tile. Cropping the tapered
     ends off it (tileX/tileW) removed the notch two butted tapers used to cut, but it
     could not make the crop's left edge match its right edge — nothing can, short of
     repainting the art — so butting copies of it left a HARD VERTICAL SEAM straight
     down through the snow band, the ice and the rock. It crossed the screen roughly
     every 1900px, which at the default run speed is once every 3.7 seconds, and it was
     the most visible flaw in the running sections.

     Mirroring alternate tiles removes it exactly rather than hiding it. Lay them out
     A A' A A' and every join meets its own reflection:

       join 1:  A.right | A'.left  =  A.right | A.right     identical
       join 2:  A'.right | A.left  =  A.left  | A.left      identical

     So both joins are continuous by construction, at every pixel, with no blend band
     and no repainting. What it costs is that the ice pattern now reads as reflected
     every other tile — invisible on an irregular icicle fringe, which is why this is
     the standard fix for a non-tiling ground strip.

     The mirror is done with a negative scale about the tile's own centre, so the
     destination rectangle is unchanged and the integer positions that make neighbours
     butt exactly still hold. */
  /* THE TILE, PRE-SCALED AND PRE-MIRRORED, ONCE.

     Measured: drawing the strip cost 4.3ms of a 21.4ms frame — a fifth of the whole
     budget, and the largest single item in it. Almost none of that was the blit. The
     source crop is 1536x530 and the destination is 1905x657, so every frame asked the
     browser to RESAMPLE two large images, and the mirrored tile asked it to resample
     and flip. Nothing about either changes from frame to frame.

     So both are rendered once into offscreen canvases at exactly their destination
     size, and the per-frame work becomes two 1:1 blits with no transform and no
     filtering. The repo already keeps offscreen canvases for precisely this ("anything
     that is redrawn identically every frame"); the path was the one thing that
     qualified most and did not have one.

     Cost: two canvases of tw x th. Benefit: the resample and the mirror move out of
     the frame entirely.

     It is built lazily rather than in the constructor because the image may not have
     decoded yet, and it is keyed on tw/th so a change to CFG.path still takes. */
  _tiles() {
    if (this._tileCache && this._tileCache.w === this.tw && this._tileCache.h === this.th) {
      return this._tileCache;
    }
    const make = mirror => {
      const c = document.createElement('canvas');
      c.width = Math.max(1, this.tw); c.height = Math.max(1, this.th);
      const g = c.getContext('2d');
      g.imageSmoothingEnabled = true;
      g.imageSmoothingQuality = 'high';
      if (mirror) { g.translate(this.tw, 0); g.scale(-1, 1); }
      g.drawImage(this.img, this.src.x, 0, this.src.w, this.src.h, 0, 0, this.tw, this.th);
      return c;
    };
    this._tileCache = { w: this.tw, h: this.th, a: make(false), b: make(true) };
    return this._tileCache;
  }

  /* THE PATH, TILED — AND EVERY OTHER TILE IS MIRRORED.

     The art is a finished 1640px segment, not a seamless tile. Cropping the tapered
     ends off it (tileX/tileW) removed the notch two butted tapers used to cut, but it
     could not make the crop's left edge match its right edge — nothing can, short of
     repainting the art — so butting copies of it left a HARD VERTICAL SEAM straight
     down through the snow band, the ice and the rock. It crossed the screen roughly
     every 1900px, which at the default run speed is once every 3.7 seconds, and it was
     the most visible flaw in the running sections.

     Mirroring alternate tiles removes it exactly rather than hiding it. Lay them out
     A A' A A' and every join meets its own reflection:

       join 1:  A.right | A'.left  =  A.right | A.right     identical
       join 2:  A'.right | A.left  =  A.left  | A.left      identical

     So both joins are continuous by construction, at every pixel, with no blend band
     and no repainting. What it costs is that the ice pattern now reads as reflected
     every other tile — invisible on an irregular icicle fringe, which is why this is
     the standard fix for a non-tiling ground strip. */
  drawStrip(ctx, worldX) {
    if (!this.img) return;
    const t = this._tiles();
    const start = Math.floor(worldX / this.tw) - 1;
    const y = Math.round(this.ty);
    for (let k = start; k < start + 4; k++) {
      const sx = Math.round(k * this.tw - worldX);
      /* ONLY THE PART THAT IS ON SCREEN.

         A tile is 1905px wide against a 1920px stage, so at any moment two of them
         overlap the screen and between them cover up to 3810px of it — twice the
         pixels that can possibly be seen. The old loop blitted each whole tile and let
         the browser clip, which still costs the full alpha composite: this strip was
         4.5ms of a 21ms frame, and it is fill-rate bound, not resample bound.

         Because the cached tiles are already at destination scale, the visible slice
         is a straight 1:1 sub-rectangle — so this is exact, not an approximation, and
         it roughly halves the pixels the path touches. */
      const x0 = Math.max(0, sx), x1 = Math.min(CFG.W, sx + this.tw);
      const w = x1 - x0;
      if (w <= 0) continue;
      // k can be negative, so mask the low bit rather than using k % 2
      // integer positions with an integer tile width, so neighbours butt exactly
      ctx.drawImage((k & 1) ? t.b : t.a, x0 - sx, 0, w, this.th, x0, y, w, this.th);
    }
  }

  /* THE SEA UNDER THE SHELF — DRAWN AS THE SAME WATER AS EVERY CREVASSE POOL.

     Raising the walking line from 890 to 840 left the path art's painted content ending
     at y 1033 on a 1080 stage, so a 47px band of flat stage-background navy ran across
     the bottom of every frame. The alternative to filling it was scaling the path art
     from 1.24 to 1.538 — a 24% bigger path, which thickens the delivered rock strata
     well past the size it was drawn for.

     IT IS THE SAME LAKE, and that is the whole point rather than a convenience. The
     world is an ice shelf floating on meltwater, and a crevasse is a hole cut down INTO
     that water — so the pool at the bottom of a crevasse and the sea under the shelf are
     not two things that ought to look similar, they are one body of water seen two ways.
     A first attempt used its own darker palette and read as a separate dark strip.

     So this shares everything with the pool inside a crevasse:

       - the surface sits on exactly `surfaceY + waterDepth`, the same line
       - the surface is the same wave, from the same waterY() the pool and the splashes
         all use, so the two can never drift out of phase
       - the same body gradient, the same reflection band under the surface, the same
         drifting highlight streaks

     Drawn before the path strip and inside the same gap clip, so the rock overlaps it
     from above and it never paints into a crevasse — there, the crevasse draws its own
     stretch of the same water. */
  drawDeepWater(ctx, t) {
    const wy = CFG.surfaceY + CFG.levelOne.waterDepth;
    if (wy > CFG.H) return;

    ctx.save();
    // the same wave line the crevasse pool is drawn to
    const surf = new Path2D();
    surf.moveTo(-10, this.waterY(-10, t));
    for (let px = -10; px <= CFG.W + 10; px += 10) surf.lineTo(px, this.waterY(px, t));
    surf.lineTo(CFG.W + 10, CFG.H + 40);
    surf.lineTo(-10, CFG.H + 40);
    surf.closePath();
    ctx.clip(surf);

    // the same body gradient
    const body = ctx.createLinearGradient(0, wy, 0, CFG.H + 40);
    body.addColorStop(0, '#2E9FC9');
    body.addColorStop(0.30, '#1B7BA8');
    body.addColorStop(1, '#0C4A70');
    ctx.fillStyle = body;
    ctx.fillRect(-10, wy - 10, CFG.W + 20, CFG.H + 60 - wy);

    // the same reflection bleeding down from the surface
    const refl = ctx.createLinearGradient(0, wy, 0, wy + 46);
    refl.addColorStop(0, 'rgba(196,236,252,0.46)');
    refl.addColorStop(1, 'rgba(174,224,248,0)');
    ctx.fillStyle = refl;
    ctx.fillRect(-10, wy, CFG.W + 20, 46);

    // and the same drifting streaks, spread across the full width
    ctx.fillStyle = 'rgba(226,248,255,0.20)';
    for (let i = 0; i < 9; i++) {
      const sx = ((i * 0.3129 + t * 0.05) % 1) * CFG.W;
      const sy = wy + 14 + (i % 4) * 13;
      ctx.beginPath();
      ctx.ellipse(sx, sy, 34 - (i % 4) * 5, 2.2, 0, 0, 6.2832);
      ctx.fill();
    }
    ctx.restore();
  }


  draw(ctx, worldX, t) {
    const gaps = this.openGaps(worldX);
    ctx.save();
    if (gaps.length) {
      const path = new Path2D();
      path.rect(-200, this.ty - 40, CFG.W + 400, this.th + 80);
      for (const s of gaps) {
        const w = (s.x1 - s.x0) * s.g.open;
        const cx = (s.x0 + s.x1) / 2;
        path.addPath(this._ditchPath(cx - w / 2, cx + w / 2, s.g));
      }
      ctx.clip(path, 'evenodd');
    }
    this.drawDeepWater(ctx, t || 0);
    this.drawStrip(ctx, worldX);
    ctx.restore();
    this.drawLips(ctx, worldX);
  }

  /* THE LIPS, as a pass of their own so the tutorial can draw the crevasse by itself:
     interior, water and lips, with none of the platform around it. They stay broken
     even once a bridge spans them.

     THE LIP IS A PIECE OF THE PLATFORM ART, NOT A DRAWN SHAPE. The supplied
     pathui.png is a set of finished ice platforms, and every one of them ENDS: a
     vertical carved face of blue ice with icicles under the snow and the dark rock
     showing below. That end is exactly what the walking surface should look like
     where it stops at a crevasse — the same snow, the same ice band, the same rock,
     drawn by the same hand as the path itself. So each lip is one of those ends, cut
     from the sheet (tools: see cap-l.webp / cap-r.webp) and seated on the walking
     Every image is awaited before play begins, so the caps are always there. */
  drawLips(ctx, worldX) {
    for (const s of this.openGaps(worldX)) {
      const w = (s.x1 - s.x0) * s.g.open;
      if (w <= 1) continue;
      const cx = (s.x0 + s.x1) / 2;
      if (!this.caps || !this.caps.l || !this.caps.r) continue;   // art is awaited before play; this is belt and braces
      // at the NECK — the opening the plug fits — not at the extent of the void beneath
      const mk = s.g.throat ? (s.x1 - s.x0) / s.g.throat : 1;
      const ins = mk > 1 ? w * (1 - 1 / mk) / 2 : 0;
      this.drawCap(ctx, cx - w / 2 + ins, 1, s.g.open);
      this.drawCap(ctx, cx + w / 2 - ins, -1, s.g.open);
    }
  }

  /* HOW THE CAP IS SEATED. The cap art is 150x227 and its rows are measured, not
     guessed: solid snow starts at row 52 (the walking surface), the snow turns to ice
     at row 89, ice to rock around row 170, and the rock ends at row 226. The path art
     shows (contentY - surfaceY) pixels of face below the walking line, so the cap is
     scaled to put the same face height under the surface and its row 52 on the snow
     line — the two pieces of art then share a snow top, an ice band and a rock base
     at the same heights, which is what makes the cap read as the END of the path
     rather than as a thing stood in front of it.

     FADED INTO THE PLATFORM on its inner side. The cap is a different piece of the
     sheet from the tile behind it, so its grain does not continue the tile's; a hard
     inner edge would draw a vertical seam on the snow. The inner 40% of the cap is
     faded to nothing with destination-out, once, into a cached canvas per side.

     The carved face sits a few pixels INTO the hole so it overlaps the interior
     rather than leaving a hairline of sky between face and wall, and the whole cap
     slides open with the crevasse (g.open) the way the hole does. */
  static get CAP() { return { w: 150, h: 227, snowTop: 52, rockEnd: 226, overlap: 8, fade: 0.4 }; }
  /* ONE WALL OF THE CREVASSE, cached — the platform's own rock band (rock-band.webp, the
     stone base cut from the sheet) tiled down the side of the hole at the same scale as
     the caps, every course shifted and alternately mirrored so no repeat shows, then
     darkened the deeper it sits. A crevasse is a break in THIS platform, so its walls
     show the platform's own stone, not something else. The inner edge is a jagged mask,
     never a straight cut: a straight inner edge was the cut-out look this replaces.
     Built for the LEFT wall; the right wall is a second seed drawn mirrored. Keyed on
     width so every mouth size gets its own column. */
  /* THE FAR WALL, cached per mouth width: the rock band tiled across the whole interior
     at 0.72 of the caps' scale (farther away), rows shifted and alternately mirrored,
     then pulled toward the crevasse's dark blue so the side walls in front read as
     nearer. Darker toward the bottom, where the mist takes over. */
  _backArt(ww) {
    const band = this.rockBand;
    if (!band || ww < 8) return null;
    const H = Math.round(CFG.H + 60 - CFG.surfaceY);
    const key = 'back:' + ww;
    this._wallCache = this._wallCache || {};
    if (this._wallCache[key]) return this._wallCache[key];
    const c = document.createElement('canvas');
    c.width = ww + 16; c.height = H;
    const g = c.getContext('2d');
    g.imageSmoothingEnabled = true; g.imageSmoothingQuality = 'high';
    let seed = 4241;
    const rnd = () => (seed = (seed * 9301 + 49297) % 233280) / 233280;
    const C = GroundManager.CAP;
    const k = 0.72 * (this.contentY - CFG.surfaceY) / (C.rockEnd - C.snowTop);
    const rowH = Math.max(20, Math.round(band.height * k)), rowW = Math.round(band.width * k);
    for (let y = -Math.round(rnd() * rowH), row = 0; y < H; y += rowH - 4, row++) {
      for (let x = -Math.round(rnd() * rowW); x < c.width; x += rowW - 4) {
        g.save();
        if (row & 1) { g.translate(c.width, 0); g.scale(-1, 1); g.drawImage(band, c.width - x - rowW, y, rowW, rowH); }
        else g.drawImage(band, x, y, rowW, rowH);
        g.restore();
      }
    }
    g.globalCompositeOperation = 'source-atop';
    g.fillStyle = 'rgba(12,44,80,0.78)'; g.fillRect(0, 0, c.width, H);      // pushed well back into the blue: it is the FAR wall
    const dk = g.createLinearGradient(0, 0, 0, H);
    dk.addColorStop(0, 'rgba(4,18,40,0.3)'); dk.addColorStop(0.55, 'rgba(4,18,40,0.6)'); dk.addColorStop(1, 'rgba(4,18,40,0.9)');
    g.fillStyle = dk; g.fillRect(0, 0, c.width, H);
    g.globalCompositeOperation = 'source-over';
    const art = { canvas: c, w: c.width, h: H };
    this._wallCache[key] = art;
    return art;
  }
  _wallArt(side, ww) {
    const band = this.rockBand;
    if (!band) return null;
    const H = Math.round(CFG.H + 100 - CFG.surfaceY);
    const key = side + ':' + ww;
    this._wallCache = this._wallCache || {};
    if (this._wallCache[key]) return this._wallCache[key];
    const c = document.createElement('canvas');
    c.width = ww + 12; c.height = H;
    const g = c.getContext('2d');
    g.imageSmoothingEnabled = true; g.imageSmoothingQuality = 'high';
    let seed = side === 'l' ? 1301 : 7727;
    const rnd = () => (seed = (seed * 9301 + 49297) % 233280) / 233280;
    const C = GroundManager.CAP;
    const k = (this.contentY - CFG.surfaceY) / (C.rockEnd - C.snowTop);   // the caps' scale
    const rowH = Math.max(24, Math.round(band.height * k)), rowW = Math.round(band.width * k);
    for (let y = -Math.round(rnd() * rowH * 0.5), row = 0; y < H; y += rowH - 6, row++) {
      const sx = Math.round(rnd() * Math.max(0, rowW - c.width - 8));
      g.save();
      if (row & 1) { g.translate(c.width, 0); g.scale(-1, 1); }
      g.drawImage(band, -sx, y, rowW, rowH);
      g.restore();
    }
    /* THE INNER EDGE WANDERS, IT DOES NOT SAW. Straight segments between jittered points
       drew sharp triangular teeth down the wall; running a curve through the midpoints
       (the same trick as the crevasse's top edge) keeps the same wander and rounds every
       turn into a bulge of stone. Between 70% and 100% of the width. */
    g.globalCompositeOperation = 'destination-in';
    g.beginPath();
    g.moveTo(0, -60);
    let px = ww * (0.7 + 0.3 * rnd()), py = -60;
    g.lineTo(px, py);
    for (let y = 0; y <= H + 60; y += 56) {
      const nx = ww * (0.7 + 0.3 * rnd());
      g.quadraticCurveTo(px, (py + y) / 2, (px + nx) / 2, y);
      px = nx; py = y;
    }
    g.lineTo(px, H + 60);
    g.lineTo(0, H + 60);
    g.closePath();
    g.fill();
    // the deeper the darker: stone fading into the depth
    g.globalCompositeOperation = 'source-atop';
    const dk = g.createLinearGradient(0, 0, 0, H);
    dk.addColorStop(0, 'rgba(6,26,52,0.10)');
    dk.addColorStop(0.4, 'rgba(6,26,52,0.32)');
    dk.addColorStop(1, 'rgba(6,26,52,0.82)');
    g.fillStyle = dk; g.fillRect(0, 0, c.width, H);
    g.globalCompositeOperation = 'source-over';
    const art = { canvas: c, w: c.width, h: H };
    this._wallCache[key] = art;
    return art;
  }
  _capArt(side) {
    const C = GroundManager.CAP;
    const faceH = this.contentY - CFG.surfaceY;
    const k = faceH / (C.rockEnd - C.snowTop);
    const w = Math.round(C.w * k), h = Math.round(C.h * k);
    const key = side + ':' + w + ':' + h;
    this._capCache = this._capCache || {};
    if (this._capCache[key]) return this._capCache[key];
    const img = side === 'l' ? this.caps.l : this.caps.r;
    const c = document.createElement('canvas');
    c.width = Math.max(1, w); c.height = Math.max(1, h);
    const g = c.getContext('2d');
    g.imageSmoothingEnabled = true; g.imageSmoothingQuality = 'high';
    g.drawImage(img, 0, 0, w, h);
    // fade the inner edge: for the left lip the inner side is the LEFT of cap-l
    const fadeW = Math.round(w * C.fade);
    const grad = side === 'l'
      ? g.createLinearGradient(0, 0, fadeW, 0)
      : g.createLinearGradient(w, 0, w - fadeW, 0);
    grad.addColorStop(0, 'rgba(0,0,0,1)');
    grad.addColorStop(1, 'rgba(0,0,0,0)');
    g.globalCompositeOperation = 'destination-out';
    g.fillStyle = grad;
    g.fillRect(0, 0, w, h);
    g.globalCompositeOperation = 'source-over';
    const art = { canvas: c, w, h, k };
    this._capCache[key] = art;
    return art;
  }
  /** @param dir  1 = the platform is to the LEFT of x (a left lip), -1 = to the right */
  drawCap(ctx, x, dir, open) {
    const C = GroundManager.CAP;
    const art = this._capArt(dir === 1 ? 'l' : 'r');
    const top = CFG.surfaceY - 4 - C.snowTop * art.k;       // row 52 lands just above the footline
    // the face reaches into the hole by `overlap`, scaled down while the crevasse is still opening
    const reach = C.overlap * clamp(open === undefined ? 1 : open, 0, 1);
    const dx = dir === 1 ? Math.round(x + reach - art.w) : Math.round(x - reach);
    ctx.drawImage(art.canvas, dx, Math.round(top));
  }

}

/* The obstacle variants delivered as art, in the order they were supplied. Named here
   rather than globbed so the set is explicit and a missing file fails loudly at load
   instead of quietly shrinking the roster. */
const OBSTACLE_ART = [
  'log-fallen', 'log-arch', 'log-crossed', 'log-stump',
  'bone-ribs', 'bone-cage', 'bone-tusk', 'bone-arch'
];

/* ---------------- ObstacleController ---------------- */
class ObstacleController {
  /* Takes a list of obstacle images. Each one's opaque bounds are measured at load,
     so the art sits exactly on the snow line without a hand-tuned constant per asset,
     and every variant is normalised to the same on-screen height — that keeps the
     jump timing identical no matter which rock is spawned. */
  constructor(imgs, audio, particles) {
    this.audio = audio; this.particles = particles; this.list = [];
    this.chimed = new Set();
    this.kinds = [];
    for (const img of (Array.isArray(imgs) ? imgs : [imgs])) {
      if (!img) continue;
      const m = measureContent(img);
      if (!m) continue;
      /* Scale every variant so its visible height matches CFG.obstacle.drawHeight —
         the DRAWN size, which is deliberately larger than the collider (see the note
         on CFG.obstacle). Normalising them all to one height is what keeps the jump
         identical whichever rock variant is spawned. */
      const s = (CFG.obstacle.drawHeight || CFG.obstacle.height) / m.h;
      this.kinds.push({
        img,
        sx: m.x0, sy: m.y0, sw: m.w, sh: m.h,      // source crop: content only
        dw: m.w * s, dh: m.h * s                    // destination size on stage
      });
    }
    // collision uses the normalised size, so all variants play the same
    this.w = this.kinds.length ? this.kinds[0].dw : 200;
    this.h = CFG.obstacle.height;
  }
  reset() { this.list = []; this.chimed.clear(); }

  /* How far apart consecutive rocks stand, in world px. Derived from the jump so the
     two can never drift apart — see the note on CFG.obstacle. */
  get gap() {
    const air = 2 * Math.abs(CFG.jumpVel) / CFG.gravity;   // seconds off the ground
    const leap = CFG.runSpeed * air;                       // ground one jump covers
    const room = CFG.runSpeed * (CFG.obstacle.runRoomS || 1.2);
    return Math.round(leap + room);
  }

  spawn(worldX, screenX, count) {
    const id = Math.random();
    const cc = CFG.obstacle;
    const gap = this.gap;
    for (let i = 0; i < count; i++) {
      this.list.push({
        id: id + i,
        x: worldX + screenX + i * gap,
        scale: cc.pairScale || 1,
        kind: this.kinds.length ? (i + Math.floor(Math.random() * this.kinds.length)) % this.kinds.length : 0,
        passed: false, telegraph: 0, hits: 0, grace: 0
      });
    }
  }
  /* @param live  whether the world is actually moving. COLLISIONS ONLY COUNT WHEN IT
     IS, and that is a fix rather than a nicety.

     Walking into a rock stops the world and puts the Ouch card up. The rock does not
     move, the character does not move, and the 1.1s `grace` then expires with the two
     still overlapping — so it collided again. And again. Measured: one bump burned all
     three strikes in 2.2 seconds, which meant the three-strike safety valve (on the
     third failure the rock crumbles so the run can never dead-end) fired on the FIRST
     failure. The learner never got the two real attempts it exists to give them, the
     Ouch card flickered as each re-hit reset its timer, and the rock they were supposed
     to practise jumping crumbled away before they had tried twice.

     Gating on `live` is the whole fix: while the world is stopped there is no new
     collision, only the one already being shown. */
  update(dt, worldX, mammoth, onHit, live = true) {
    for (const o of this.list) {
      const sx = o.x - worldX;
      if (o.grace > 0) o.grace -= dt;
      if (sx < 1180 && sx > CFG.mammothX && o.telegraph < 1) {
        o.telegraph += dt * 1.6;
        if (!this.chimed.has(o.id)) { this.chimed.add(o.id); this.audio.crystal(); }
      }
      if (sx < CFG.mammothX - 200) o.passed = true;
      // collision — driven by the normalised size, never by the chosen art
      /* EACH VARIANT COLLIDES AT ITS OWN WIDTH. this.w is the FIRST kind's width, and
         with two similar rocks that was near enough. With ten silhouettes it is not:
         the bone arch is 639 source px wide and the tusk 593, and normalising them all
         to one drawn HEIGHT makes their drawn widths differ more, not less. Sharing one
         collider means the wide ones let the character walk into their edge untouched
         while the narrow ones stop him before he reaches them — the same input reading
         as a hit or a miss depending on which art happened to spawn.

         Falls back to this.w if a kind is somehow missing, so a missing sprite cannot
         take the collision out entirely. */
      const kw = (this.kinds[o.kind] || {}).dw || this.w;
      const ow = kw * o.scale, oh = this.h * o.scale;
      const ox0 = sx - ow * 0.28, ox1 = sx + ow * 0.28;
      const feet = mammoth.feetY;
      /* THE BODY BOX AND THE BAR, both loosened — see the note on CFG.jumpVel.

         68 was half the body box, so the danger zone was the rock plus 136px; 52
         takes 32px off it, which is 0.06s at run speed. And the bar comes down from
         45% of the rock height to 28%, so the character counts as clear earlier in
         the rise and later in the fall.

         Neither makes a hit unfair: 52px is still wider than the character's own
         chest, and at 28% of 140px the feet are 39px up, which is plainly over a rock
         the eye reads as knee-high. What they buy is that a press slightly early or
         slightly late still clears it. */
      if (live && o.grace <= 0 && o.hits < 3 && ox0 < CFG.mammothX + 52 && ox1 > CFG.mammothX - 52 && feet > CFG.surfaceY - oh * 0.28) {
        o.hits++; o.grace = 1.1; onHit(o, sx);
        if (o.hits >= 3) o.crumble = 0;
      }
      if (o.crumble !== undefined && o.crumble < 1) o.crumble = Math.min(1, o.crumble + dt * 1.7);
    }
    this.list = this.list.filter(o => o.x - worldX > -400);
  }
  /* `only` draws ONE rock and nothing else — no contact shadow, no neighbours — for the
     tutorial's focus render, which glows the alpha of whatever is drawn. */
  draw(ctx, worldX, t, only) {
    for (const o of this.list) {
      if (only && o !== only) continue;
      const sx = o.x - worldX;
      if (sx < -300 || sx > CFG.W + 300) continue;
      const ow = this.w * o.scale, oh = this.h * o.scale;
      /* Contact shadow — and it is much darker than it was, and sized to the ART rather
         than to the collider. At 0.30 alpha over a bright white snow path it was simply
         invisible, which is most of why the rock looked like it was hovering: nothing
         darkened where it met the ground. */
      const artW = (this.kinds[o.kind] || this.kinds[0] || { dw: ow }).dw * o.scale;
      if (!only) {
      ctx.save();
      ctx.translate(sx, CFG.surfaceY + 4);
      /* Soft and diffuse, NOT dark and tight. Squashing a strong radial into a 13px
         band drew a hard dark stripe across the snow that stuck out either side of the
         rock and looked worse than no shadow at all — a shadow has to be the thing you
         do not notice. Taller, and about half the opacity. */
      ctx.scale(1, 26 / (artW * 0.5));
      const crg = ctx.createRadialGradient(0, 0, 0, 0, 0, artW * 0.5);
      crg.addColorStop(0, 'rgba(22,64,108,0.30)');
      crg.addColorStop(0.45, 'rgba(22,64,108,0.15)');
      crg.addColorStop(1, 'rgba(24,72,120,0)');
      ctx.fillStyle = crg;
      ctx.beginPath(); ctx.arc(0, 0, artW * 0.5, 0, 6.2832); ctx.fill();
      ctx.restore();
      }
      const cr = o.crumble === undefined ? 0 : o.crumble;
      /* THE ROCK DOES NOT MOVE. A rocking, swelling anticipation was tried here — a
         cartoon prop leaning in before it matters — and removed on request: it read as
         the stone shaking whenever the mammoth came near, which is not what a rock
         does. It is a lump of stone in the snow and it holds still.

         The approach is still telegraphed, by the chime and the marks above it, neither
         of which touches the rock itself. */
      const lean = 0, swell = 1;
      ctx.save();
      // the sink is proportional to the drawn size — see the note on CFG.obstacle
      const sink = Math.round((CFG.obstacle.drawHeight || CFG.obstacle.height) *
                              (CFG.obstacle.sinkRatio || 0) * o.scale);
      ctx.translate(sx, CFG.surfaceY + sink);
      ctx.rotate(lean);
      ctx.scale(swell, swell);
      ctx.translate(-sx, -(CFG.surfaceY + sink));
      if (cr > 0) { ctx.save(); ctx.globalAlpha = 1 - cr; ctx.translate(sx, CFG.surfaceY); ctx.scale(1 + cr * 0.1, 1 - cr * 0.85); ctx.translate(-sx, -(CFG.surfaceY)); }
      // The rocks are dark against snow, so they need no added rim — the art carries
      // its own contrast. Seated by measured content bounds, sunk slightly into the snow.
      const k = this.kinds[o.kind] || this.kinds[0];
      if (k) {
        const dw = k.dw * o.scale, dh = k.dh * o.scale;
        const dx = sx - dw / 2, dy = CFG.surfaceY + sink - dh;
        ctx.drawImage(k.img, k.sx, k.sy, k.sw, k.sh, dx, dy, dw, dh);
      }
      /* NOTHING IS DRAWN OVER THE STONE. A snow drift banked across its base was
         tried here and taken out on request: it merged the rock into the path nicely,
         but it did so by painting an engine-drawn white shape over hand-drawn art,
         which changes the stone's own silhouette. Same standing rule as the seated
         option piece — the delivered art keeps its own shape.

         The rock is seated by the two things that do NOT touch it: the proportional
         sink above, which buries the right fraction of it whatever size it is drawn,
         and the soft contact shadow, which darkens the snow it stands on. */
      if (cr > 0) ctx.restore();
      ctx.restore();                      // the anticipation transform
      if (o.telegraph > 0 && o.telegraph < 1.6 && !o.passed) {
        const a = Math.sin(t * 9) * 0.5 + 0.5;
        ctx.save();
        ctx.globalAlpha = 0.55 * a * clamp(o.telegraph, 0, 1);
        ctx.strokeStyle = '#FFFFFF'; ctx.lineWidth = 3;
        for (let i = 0; i < 3; i++) {
          const ax = sx - 26 + i * 30, ay = CFG.surfaceY - oh - 18 - i * 14;
          ctx.beginPath();
          ctx.moveTo(ax - 9, ay); ctx.lineTo(ax + 9, ay);
          ctx.moveTo(ax, ay - 9); ctx.lineTo(ax, ay + 9);
          ctx.stroke();
        }
        ctx.restore();
      }
    }
  }
}

/* ---------------- PolygonCutManager ---------------- */
export const PolygonCutManager = {
  isDiagonal(n, i, j) {
    if (i === j) return false;
    const d = Math.abs(i - j);
    return d !== 1 && d !== n - 1;
  },
  split(pts, i, j) {
    const n = pts.length;
    const a = [], b = [];
    for (let k = i; ; k = (k + 1) % n) { a.push({ ...pts[k] }); if (k === j) break; }
    for (let k = j; ; k = (k + 1) % n) { b.push({ ...pts[k] }); if (k === i) break; }
    return [a, b];
  },
  toPiece(pts) {
    const c = centroid(pts);
    return { local: pts.map(p => ({ x: p.x - c.x, y: p.y - c.y })), x: c.x, y: c.y, rot: 0, scale: 1 };
  }
};

/* ================= main game ================= */
export function createGame(canvas, hooks = {}) {
  const ctx = canvas.getContext('2d');
  canvas.width = CFG.W; canvas.height = CFG.H;

  const audio = new AudioManager();
  const particles = new ParticleManager();
  const atmos = new Atmosphere();
  const images = {};
  let ground, obstacles, bgm, mammoth;
  let raf = 0, last = 0, destroyed = false, paused = false;
  // simulation steps per rendered frame; 1 is normal play (see setOptions)
  let fastForward = 1;
  let reduced = window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;
  const mqReduced = reduced;

  const RUN_STATES = new Set(['RUN_SEGMENT_1', 'JUMP_CHALLENGE_1', 'POST_JUMP_RUN_1',
    'PHASE_RUN', 'FINAL_RUN']);

  // Day/night follows JOURNEY MILESTONES, never wall-clock or extra distance spent
  // retrying an obstacle: each state owns a progress band it eases across, and the
  // puzzle states hold the sky still for as long as the learner needs.
  const JOURNEY = {
    RUN_SEGMENT_1:     [0.00, 0.06, 2400],
    JUMP_CHALLENGE_1:  [0.06, 0.09, 3600],
    POST_JUMP_RUN_1:   [0.09, 0.12, 2000],
    // 0.12 -> 0.82 belongs to Level 1's six phases and is driven by phases
    // completed, below — the sky has to move through the whole adventure now that
    // Level 1 IS the adventure
    FINAL_RUN:         [0.82, 1.00, 6000]
  };

  const G = {
    state: 'BOOT', st: 0, worldX: 0, dist: 0, progress: 0, t: 0,
    speedFactor: 1, shake: 0, shakeT: 0, moving: true,
    instruction: '', jumpEnabled: false, jumpPulse: false,
    complete: false,
    l1: null,
    attempts: 0, idle: 0, hintUntil: 0, hint: null,
    /* oops stays on the state object and is now always false: the Ouch card it drove
       is gone (the crash recovers by itself — see OBSTACLE_HIT). It is left here, and
       still published to the HUD, because removing a field from that object is a
       change every consumer has to be checked against and it buys nothing. */
    oops: false, hitFx: 0, hitObstacle: null, hitReturn: null,
    handHint: null, idleHand: 0, dropReady: false,
    quakeT: 0, quakeAmp: 0, quakeLen: 0, quakeRoll: 0, quakePeak: 0, quakeAt: 0,
    quakeOx: 0, quakeOy: 0,
    freeze: 0,                                            // seconds of hit-stop left
    /* The live view transform. k is the scale, (vx, vy) the stage point it scales
       about. Published to the HUD so the DOM overlays can map through exactly the same
       numbers — a coach mark or a verdict positioned in raw stage coordinates would
       drift off its target the moment the canvas zoomed. */
    zoom: 1, zoomWant: 1, zoomVX: 960, zoomVY: 540,
    punchAmp: 0, punchT: 0, punchLen: 0, punchAt: 0, punchX: 0, punchY: 0,
    instrHold: 0, instrLast: '',
    phase: 0, phasesDone: 0, gapsThisPhase: null, phaseLayout: null, phaseJumped: false
  };

  /* ---- HUD push ---- */
  /* The banner announces the task, then gets out of the way — a permanent caption
     is HUD clutter and the world is the thing worth looking at. It re-arms itself
     whenever the text changes, and briefly again after a wrong attempt. */
  function armInstruction(ms) { G.instrHold = ms === undefined ? T.instructionHold : ms; }
  function updateInstruction(dt) {
    if (G.instruction !== G.instrLast) { G.instrLast = G.instruction; armInstruction(); }
    if (G.instrHold > 0) G.instrHold = Math.max(0, G.instrHold - dt * 1000);
  }

  let lastHud = '';
  /* WHAT THE HUD IS TOLD — and nothing else.

     This is diffed against its own last value so hud.js is only called when something
     it can act on has actually changed. That only works if every key is something the
     HUD reads. It was not: nine were not read anywhere, and one of them, `progress`,
     is a float that advances on EVERY FRAME of every running segment. So the diff
     never matched, hud.js ran its whole DOM pass sixty times a second for the length
     of every run, and the comment promising otherwise was simply wrong.

     Removed, with what each one was for, so it is on the record rather than a mystery
     if anything ever wants them back:

       progress      the day/night position. Drawn on canvas by BackgroundTimeManager,
                     never in the DOM — and the key that broke the diff.
       level         always 1. Level 2 is parked.
       phaseLabel    'Dawn', 'Midday'... the sky caption was removed.
       phaseCount /
       phasesDone /
       phaseAt       the phase-progress diamonds, removed on request. The tests read
                     phasesDone from debug(), not from here.
       started       for a loading curtain that no longer exists.
       paused        for the pause control, removed from the markup.
       helper        a second instruction line, removed on request. G.helper is only
                     ever assigned the empty string, so `h.helper || h.instruction`
                     was provably just h.instruction; hud.js drops it too.

     What is left is exactly what hud.js and main.js consume. */
  function pushHud() {
    const h = {
      /* IT STAYS UP FOR THE WHOLE PLAYABLE PHASE. It used to slide away a few seconds
         after arriving, which meant the one thing telling the learner what to look for
         was gone by the time they were looking. It still owns the stage alone during
         PHASE_INTRO — the chunks are held above the screen until that beat ends — and
         it takes no pointer events, so it can never swallow a cut. */
      /* THE INSTRUCTION LEAVES BEFORE PLAY STARTS.
       *
       * It used to stay up for the whole of PHASE_ACTIVE, PHASE_WRONG and
       * PHASE_SUCCESS — so the sentence sat over the stage for as long as the learner
       * took to think, competing with the very shapes it was asking them to look at.
       * Now it owns the stage alone while it is readable and is gone by the time the
       * blocks are cuttable: instruction -> read it -> it leaves -> play.
       *
       * instrHold is the only gate left, so the sentence is on screen for exactly the
       * time it was armed for and no longer. NOTHING CLEARS G.instruction ITSELF —
       * only its visibility is gated — because replayInstruction() reads that text and
       * the idle helper re-arms this hold to bring it back. Blanking the text to hide
       * the panel is what silently broke the recall control once before. */
      instruction: G.instrHold > 0 ? G.instruction : '',
      jumpEnabled: G.jumpEnabled, jumpPulse: G.jumpPulse, complete: G.complete,
      // the shape that mended each crossing, for the ending's stamps — a string, so the
      // HUD's change detection sees one value rather than a fresh array every frame
      mendedKinds: G.complete ? L1.phases.map(p => p.targets[0]).join(',') : '',
      oops: G.oops,
      // the hint control asks for attention once the learner has been stuck a while
      hintNudge: G.state === 'PHASE_ACTIVE' && (G.idle > CFG.hint.slotMs / 1000 || (G.l1 && G.l1.wrong >= 1)),
      // where to demonstrate the cut, once the learner has been idle a long while
      handHint: G.handHint || null,
      /* THE VIEW TRANSFORM, so the DOM overlays land on what they point at. The
         verdict mark, the hand hint and the tutorial spotlight are all positioned in
         stage coordinates; once the canvas scales about a point, a raw stage position
         is no longer where that thing appears. Publishing the transform rather than
         the corrected positions keeps one source of truth and lets each consumer map
         only what it needs. */
      view: { k: G.zoom, x: G.zoomVX, y: G.zoomVY },
      soundOn: !!audio.enabled
    };
    const s = JSON.stringify(h);
    if (s !== lastHud) { lastHud = s; hooks.onHud && hooks.onHud(h); }
  }

  /* ---- who the player picked ---- */
  let characterId = CFG.characters[0].id;
  function currentCharacter() {
    return CFG.characters.find(c => c.id === characterId) || CFG.characters[0];
  }
  /** Swap the explorer. Kept out of the run states so it can only happen up front. */
  function setCharacter(id) {
    if (!CFG.characters.some(c => c.id === id)) return false;
    characterId = id;
    if (mammoth) { mammoth.setCharacter(currentCharacter(), images); mammoth.reset(); }
    return true;
  }

  /* ---- asset loading ---- */
  function loadImg(src) {
    return new Promise(res => {
      const i = new Image();
      i.onload = () => res(i); i.onerror = () => res(null);
      i.src = src;
    });
  }
  async function preload() {
    const jobs = CFG.phases.map(p => loadImg(p.src).then(i => { images[p.key] = i; }));
    jobs.push(loadImg('assets/env/path.webp').then(i => { images.path = i; }));
    jobs.push(loadImg('assets/env/rock-wide.webp').then(i => { images.rockWide = i; }));
    jobs.push(loadImg('assets/env/rock-tall.webp').then(i => { images.rockTall = i; }));
    /* THE DELIVERED OBSTACLE SET: four snow-covered logs and four fossils, sliced out
       of two 2x2 sheets by tools/slice-obstacles.mjs. They join the two rocks rather
       than replacing them, because what a run needs is VARIETY — ten silhouettes means
       a four-rock stretch is four different objects instead of the same lump four
       times, which is most of what makes the stretch feel like a journey. */
    for (const k of OBSTACLE_ART) {
      jobs.push(loadImg('assets/env/obs-' + k + '.webp').then(i => { images['obs:' + k] = i; }));
    }
    jobs.push(loadImg('assets/env/rope.webp').then(i => { images.rope = i; }));
    // the carved ends of a platform, cut from the supplied pathui.png — see GroundManager.drawCap
    jobs.push(loadImg('assets/env/cap-l.webp').then(i => { images.capL = i; }));
    jobs.push(loadImg('assets/env/cap-r.webp').then(i => { images.capR = i; }));
    // the platform's own stone base, cut from the same sheet: the crevasse walls are tiled from it
    jobs.push(loadImg('assets/env/rock-band.webp').then(i => { images.rockBand = i; }));

    /* THE FRIEND AT THE END. Loaded with the world rather than with the character
       sheets: he is scenery that happens to be a character, he has no animation and no
       states, and putting him in CFG.characters would make him look like something the
       player could be. */
    jobs.push(loadImg('assets/char/bear.webp').then(i => { images.bear = i; }));
    // the two of them dancing: the delivered 36-frame GIF as a 6x6 sheet at native size
    jobs.push(loadImg('assets/char/duo-celebrate.webp').then(i => { images.duo = i; }));
    // one painted block per shape the curriculum can name
    for (const [id, s] of Object.entries(optionShapes)) {
      jobs.push(loadImg(s.image).then(i => { images['shape:' + id] = i; }));
    }
    // every character's sheets, keyed 'id:slot'
    for (const ch of CFG.characters) {
      for (const slot of Object.keys(ch.sheets)) {
        const key = ch.id + ':' + slot;
        jobs.push(loadImg(ch.sheets[slot]).then(i => { images[key] = i; }));
      }
    }
    await Promise.all(jobs);
  }

  /* ---- state machine ---- */
  function setState(s) {
    G.state = s; G.st = 0;
    onEnter(s);
    pushHud();
  }

  function onEnter(s) {
    switch (s) {
      case 'RUN_SEGMENT_1':
        G.moving = true; G.jumpEnabled = true; mammoth.setState('RUN'); break;
      case 'JUMP_CHALLENGE_1':
        /* The very first rock is always a single one: it is the step where the jump is
           being learned, and learning it against three at once is not a difficulty
           curve, it is a wall. */
        obstacles.spawn(G.worldX, 2150, 1); G.jumpPulse = true; break;
      case 'POST_JUMP_RUN_1':
        G.jumpPulse = false; G.hitCount = 0; break;
      case 'TITLE':
        G.moving = false; G.jumpEnabled = false; G.jumpPulse = false;
        mammoth.setState('IDLE_LOOK');
        break;
      case 'OBSTACLE_HIT':
        G.moving = false; G.jumpEnabled = false; G.jumpPulse = false; G.oops = false;
        break;
      case 'GLACIER_BREAK_1': G.jumpEnabled = false; G.jumpPulse = false; startBreak(); break;
      case 'PHASE_RUN': G.zoomWant = 1;
        /* PHASE_RUN is also where a retry lands, so it must NOT reset the strike
           count. It used to, which meant the three-strike valve could never fire:
           fail the jump, retry, land back here, counter cleared, fail again — an
           infinite Try Again loop with no way past. The counter is cleared when the
           phase actually advances instead (PHASE_DONE). */
        G.moving = true; G.jumpEnabled = true; G.speedFactor = 1;
        G.phaseJumped = false;
        mammoth.setState('RUN'); break;
      case 'PHASE_INTRO':
        /* Frame the puzzle: the instruction, the blocks and the ditch become the whole
           picture, and the view eases back out when the run resumes below. */
        aimZoom();
        G.jumpEnabled = false;
        G.dropReady = false;                 // nothing moves until the panel leaves
        G.instruction = phaseCfg().instruction;
        // let the tremble that started at the stop play out into the head-down look
        if (mammoth.state !== 'SHAKE') mammoth.setState('LOOK_DOWN');
        buildPhase(); break;
      case 'PHASE_ACTIVE': G.idle = 0; G.idleHand = 0; if (!G.l1) buildPhase(); break;
      case 'PHASE_SUCCESS': break;
      case 'PHASE_DONE':
        // the whole phase is repaired: celebrate, then back to the adventure
        G.instruction = '';
        G.phasesDone = Math.max(G.phasesDone, G.phase + 1);
        mammoth.setState('CELEBRATE'); audio.success(G.phase); atmos.pulse();
        /* A crossing is mended and he can go on — the biggest beat in the loop, so it
           gets the biggest burst, thrown from over his head rather than off the hole.
           The fright is cleared at the same time: he is done being scared of this one. */
        mammoth.scare = 0;
        if (!reduced) particles.confetti(CFG.W, 110);   // confetti, not stars: the whole phase is done
        particles.poof(CFG.mammothX, CFG.surfaceY, reduced ? 3 : 6, 1.1);
        break;
      // Level 2 is parked (drafts/level-2.draft.js), so the last repaired crossing
      // leads straight into the run home.
      case 'FINAL_RUN': G.zoomWant = 1;
        /* Far enough ahead that the run home is a run rather than a step, and close
           enough that it is not a trek: at CFG.runSpeed this is about four seconds. */
        G.bearAt = G.worldX + CFG.W + 1250;
        G.l1 = null; G.gapsThisPhase = null;
        G.instruction = 'Run for home!';
        G.moving = true; G.jumpEnabled = true; G.speedFactor = 1;
        audio.setDuck(1); mammoth.setState('RUN'); break;
      case 'COMPLETE':
        G.moving = false; G.complete = true; G.jumpEnabled = false; G.instruction = ''; G.drizzleAt = 0; G.duoFrame = -1;
        mammoth.setState('CELEBRATE'); particles.poof(CFG.mammothX, CFG.surfaceY, 6, 1.1);
        /* CONFETTI, from above the whole stage rather than from the character. A burst
           thrown off one point reads as an impact; confetti has to fall on everything,
           which is what makes it a celebration rather than another particle effect. */
        if (!reduced) particles.confetti(CFG.W, 130, true);
        // a proper shower for the end of the journey, thrown from over his head
        particles.sparkle(CFG.mammothX + 40, CFG.surfaceY - 320, reduced ? 8 : 26, 340);
        audio.fanfare();
        break;
    }
  }

  /* THE FRIEND WAITING AT THE END OF THE JOURNEY.

   * He is placed in WORLD space, a fixed distance past the point the last crossing is
   * mended, so the character runs up to him rather than him sliding into frame — which
   * is the difference between arriving somewhere and having scenery delivered to you.
   *
   * bearAt is set when FINAL_RUN begins, because that is the first moment the finish
   * line has a world position at all. Drawn only once it is set, so nothing appears
   * during the puzzles.
   *
   * He is drawn at CFG.sprite.scale like the character, off his own foot line, so the
   * two animals are the same size standing next to each other — a friend who is subtly
   * the wrong scale reads as a different game's art. */
  function drawBear(ctx) {
    const img = images.bear;
    if (!img || !G.bearAt) return;
    const sx = G.bearAt - G.worldX;
    if (sx < -300 || sx > CFG.W + 300) return;
    const k = CFG.sprite.scale * 0.86;          // a cub, so a little smaller
    const w = img.width * k, h = img.height * k;
    ctx.save();
    /* A slow breathing bob, so he is alive while he waits. Sine on the shared clock —
       no state of his own to keep, and it cannot drift out of step with anything. */
    const bob = reduced ? 0 : Math.sin(G.t * 1.6) * 4;
    ctx.translate(sx, CFG.surfaceY + 6 + bob);
    /* MIRRORED, so he faces the friend who is arriving. The delivered art looks to its
       right; the mammoth runs in from the LEFT and stops on the bear's left, so unflipped
       the two of them stood back to back at the one moment the picture is about them
       meeting. */
    ctx.scale(-1, 1);
    ctx.drawImage(img, -w / 2, -h, w, h);
    ctx.restore();
  }

  /* ---- glacier break ---- */
  let brk = null;
  function makeCrack() {
    const p = []; let x = 0, y = 0;
    for (let i = 0; i < 6; i++) { x += (i % 2 ? 11 : -11) + rand(-6, 6); y += 22; p.push({ x, y }); }
    return p;
  }
  // The stop is two beats: the mammoth keeps running while the rumble builds,
  // then the skid bites and it slides to a halt. Distance is the integral of the
  // speed curve below, so the gap always lands the same distance ahead.
  const BREAK_HOLD = 140;                        // ms at full speed (anticipation)
  const BREAK_SLIDE = T.breakSkid - BREAK_HOLD;  // ms of deceleration
  const BREAK_K = 1.4;                           // speed = (1-u)^k, so mean speed = 1/(k+1)
  const BREAK_CRACK = 300;                       // ms until the ice actually lets go

  function startBreak() {
    ground.gaps = ground.gaps.filter(g => g.repaired);
    audio.rumble();
    audio.setDuck(0.8);
    // One tremor for the whole stop: it builds for the 300ms before the ice cracks,
    // peaks on that frame, and is gone by the time the skid ends — so the puzzle is
    // never introduced over a shaking screen.
    quake(reduced ? 4 : 10, T.breakSkid, BREAK_CRACK);
    const dist = CFG.runSpeed * (BREAK_HOLD + BREAK_SLIDE / (BREAK_K + 1)) / 1000;
    const targetWorldX = G.worldX + dist;
    brk = { cracked: false, skidded: false, targetWorldX };
    // The phase decides how many crevasses open and where. Laying them out here —
    // before the ground gives way — means the collapse drama opens exactly the holes
    // the puzzle is about to ask about, and every one is far too wide to jump.
    G.phaseLayout = layoutPhase(targetWorldX);
    G.gapsThisPhase = G.phaseLayout.gaps;
    mammoth.setState('RUN');
  }
  function updateBreak(dt) {
    const gaps = (G.gapsThisPhase || []).filter(Boolean);
    const cp = clamp(G.st / 340, 0, 1);
    gaps.forEach(g => { g.crack = cp; });
    if (G.st > 300) gaps.forEach(g => { g.open = clamp((G.st - 300) / 320, 0, 1); });

    if (G.st < BREAK_HOLD) {
      // still running — the ground is only just starting to give
      G.speedFactor = 1;
    } else {
      const u = clamp((G.st - BREAK_HOLD) / BREAK_SLIDE, 0, 1);
      G.speedFactor = Math.pow(1 - u, BREAK_K);
      if (!brk.skidded) { brk.skidded = true; audio.skid(); }
      mammoth.setState('SKID_STOP');
      mammoth.setSkidProgress(u);
    }

    // one-shot: without the flag this fires on every frame inside the window,
    // so a 144Hz display got six crack sounds and six times the ice chips
    if (!brk.cracked && G.st > BREAK_CRACK) {
      brk.cracked = true;
      audio.crack();
      /* The one moment the ground itself fails. It gets the longest hold and the
         biggest punch in the game, because everything after it — the whole puzzle —
         exists because of this frame. */
      hitStop(CFG.juice.stopBreak);
      punch(CFG.juice.punchBreak, 420, CFG.mammothX + 420, CFG.surfaceY);
      audio.rumble();
      atmos.pulse();                    // one flash, on the frame the ice gives
      gaps.forEach(g => particles.chips(g.x0 - G.worldX + (g.x1 - g.x0) / 2, CFG.surfaceY, 6, -180));
      shake(reduced ? 3 : 7, 260);
      /* THE FIRST BEAT OF THE JOKE. The ground lets go while he is still sliding, so
         the body shudders WITHOUT leaving the skid — jolt() is exactly that, an
         amplitude bump with no change of state. The full fright waits until he has
         stopped and can see how wide the hole is. */
      mammoth.jolt(reduced ? 0.3 : 0.6);
    }

    if (G.st >= T.breakSkid) {
      G.speedFactor = 0; G.moving = false; G.worldX = brk.targetWorldX;
      audio.setDuck(1);
      /* THE PUNCHLINE. He has stopped, the hole is right there, and this is where
         the shudder, the double take, the gulp and the sweat all start. It used to be
         setState('SHAKE'), which with no shake sheet lasted one frame. */
      mammoth.startle(reduced ? 0.55 : 1);
      setState('PHASE_INTRO');
    }
  }

  /* ---- Level 1 ---- */
  const L1 = CFG.levelOne;
  const SHAPE_W = L1.slabW, SHAPE_H = L1.slabH;

  function phaseCfg() { return L1.phases[clamp(G.phase, 0, L1.phases.length - 1)]; }

  /* Builds one phase: its crevasses, its REPAIR SLOTS, and its hanging chunks.

     The crevasse is a plain large natural chasm — its outline says nothing about
     which shape repairs it, which is the whole point. What makes the repair read as
     a repair is not a socket but a bridge: the right chunk wedges at the surface and
     the ice grows out from the lips to meet it.

     HOW MANY ANSWERS IS NOT HOW MANY HOLES. "Cut all the pentagons" wants three
     answers, and opening three crevasses for them would be a different game. So a
     phase opens `ditches` crevasses (one or two) and each crevasse is divided into
     as many equal SLOTS as its share of the phase's answers — three answers across
     two crevasses gives slot counts of 2 and 1. A correct chunk takes whichever free
     slot is nearest the cut, so the learner is never asked to guess an allocation,
     and a crevasse is mended only once every slot in it is plugged. */

  /** Share `total` slots over `n` crevasses as evenly as possible, fullest first. */
  function slotShare(total, n) {
    const out = [];
    let left = total;
    for (let i = 0; i < n; i++) {
      const k = Math.max(1, Math.ceil(left / (n - i)));
      out.push(k); left -= k;
    }
    return out;
  }

  /* THE ONE WIDTH EVERY OPTION IN A PHASE IS DRAWN AT.
   *
   * All the blocks in a phase must look equally capable of bridging the hole, or the
   * learner can pick by SIZE instead of counting sides — and picking by size is not
   * the thing being taught. Measured before this: a three-option row produced blocks
   * 243, 270 and 274px wide, so the widest was a standing hint on every one of the
   * five single-answer phases.
   *
   * The variation came from the re-fit inside seatedChunk taking min(w/width,
   * h/height): whenever a shape is taller than it is wide relative to the box, HEIGHT
   * binds and the finished block comes out narrower than the box. Which shapes that
   * catches depends on their aspect ratios, so the blocks in a row ended up at
   * whatever widths their proportions happened to give.
   *
   * So the width is chosen so that height can never bind for ANY option in the phase:
   * measure every shape at a huge notional height to get its true aspect ratio, take
   * the tallest, and pick the width at which even that one still fits the row box.
   * Every block then comes out at exactly that width, and the only thing that
   * distinguishes them is the silhouette — which is the question.
   *
   * Both layoutPhase and buildPhase call this, so the width the ditches are cut for
   * and the width the blocks are drawn at are the same number by construction. It is
   * pure: same phase in, same width out, no state. */
  function phasePieceW(p) {
    const box = optionBox(p.options);
    const w0 = Math.min(box.w, SHAPE_W);
    const kinds = p.targets.concat(p.distractors).slice(0, p.options);
    let tallest = 0;
    for (let i = 0; i < kinds.length; i++) {
      /* A notional height of 1e6 so the height term can never bind here — what comes
         back is the shape's own aspect ratio rather than a clamped one. */
      const c = seatedChunk(kinds[i], { w: w0, h: 1e6 },
                            { irregular: p.irregular, seed: p.id * 97 + 7 * i + 3 });
      const bb = polyBounds(c.pts);
      if (bb.w > 0) tallest = Math.max(tallest, bb.h / bb.w);
    }
    if (!(tallest > 0)) return w0;
    return Math.max(80, Math.min(w0, L1.optionH / tallest));
  }

  function layoutPhase(originX) {
    const p = phaseCfg();
    /* Never more crevasses than answers: a crevasse with no slot to fill could not
       be mended, and the run would arrive at an open hole. */
    const n = clamp(p.ditches || 1, 1, p.targets.length);

    /* EACH DITCH IS AS WIDE AS THE PIECE THAT WILL BRIDGE IT.
     *
     * The piece width is the option row's own box width — the same number
     * seatedChunk() clamps every hanging chunk to — so the ditch and the chunk cannot
     * disagree about how big a bridge is. Take the bearing off each end and what is
     * left is the span the piece has to cross.
     *
     * ONE DITCH PER ANSWER is what makes this hold together. A six-option row gives
     * narrow pieces and therefore narrow ditches, and a single narrow ditch would look
     * like something you could simply hop. Three of them with ice islands between is a
     * long broken stretch that plainly cannot be crossed, and each one is mended by
     * its own piece — which is also the clearest possible reading of "three answers,
     * three holes". Jumping is disabled for the whole puzzle regardless, so no
     * individual span is exploitable either way. */
    /* THE DITCH IS CUT TO THE PIECES AS THEY ACTUALLY COME OUT, not to the box they
     * were fitted in. Those are different numbers and the difference is not small.
     *
     * seatedChunk re-fits with k = min(w/width, h/height), so whenever HEIGHT is the
     * binding constraint the finished piece is narrower than its box. Measured: a
     * three-option row gave a 340px box and 274px pieces, and a six-option row a 198px
     * box and 162px pieces — so a ditch sized from the box left every bridge 5px short
     * in the easy phases and 88px short in the hard ones. A bridge that does not reach
     * is the entire feature failing, and it would have looked like a rendering bug.
     *
     * So every option is built here and measured, and the ditch is cut to the
     * NARROWEST of them. Every piece then spans its hole with bearing to spare.
     *
     * Using all the options rather than just the targets is deliberate: the narrowest
     * is as likely to be a distractor as an answer, so the width of the hole says
     * nothing about which shape belongs in it. Sizing to the targets would have put
     * the answer in the terrain.
     *
     * It builds each chunk twice per phase — once here to measure, once in buildPhase
     * to hang. That is a few dozen polygon operations once per phase, against getting
     * the geometry right; the seeds match so both passes see identical shapes. */
    /* Every block in the phase is this wide — see phasePieceW — so there is nothing
       to take a minimum over any more, and the hole is simply the block less the
       bearing it rests on at each end. */
    const pieceW = phasePieceW(p);
    const throatW = Math.max(L1.ditchMin, Math.round(pieceW * (1 - L1.bearing * 2)));
    // the visible cut in the platform is the MOUTH, mouthOf(k) below; the plug wedges at the THROAT

    /* HOW MANY POLYGONS EACH DITCH TAKES. Every answer needs a slot and there may be
       more answers than ditches: the extra ones go to the LAST ditch, so a phase with
       three answers and two ditches has one single-piece crossing and one bridged by
       TWO polygons side by side — the picture the brief drew, a trapezoid and a wedge
       meeting in the middle of one wide gap. A two-piece ditch is twice as wide at the
       throat, and its mouth scales with it. */
    const share = new Array(n).fill(1);
    for (let extra = p.targets.length - n, i = n - 1; extra > 0; extra--, i = (i - 1 + n) % n) share[i]++;
    const mouthOf = k => Math.round(throatW * k * (L1.mouth || 1));
    const groupW = share.reduce((a, k) => a + mouthOf(k), 0) + (n - 1) * L1.ditchGap;
    /* UNDER THE HANGING ROW, not centred on the stage — and that mismatch was visible.

       The row is centred on the SAFE AREA (mammothX + clearOfPlayer .. W - 60), which
       works out at x 1315. The crossing was centred on the STAGE and then pushed right
       to clear the character, which lands it at 900. Measured: the row centre sat 316px
       to the right of the crossing centre, so with one narrow ditch only the leftmost
       block was anywhere near the hole and the other two hung over solid ice. The
       relationship the player is supposed to read — thread, block, hole underneath —
       was not there to read.

       Aiming the group at the row centre costs nothing: it is the same clamp as before,
       just a better starting wish. Where the clamp binds — a three-ditch phase whose
       group is 639px wide cannot centre on 1315 and still keep its near lip clear of
       the character — it gets as close as the clearance allows, which is what the
       clamp is for. The near-lip rule still wins, and curriculum.spec asserts it. */
    const rowMid = (CFG.mammothX + L1.clearOfPlayer + (CFG.W - 60)) / 2;
    const lead = clamp(
      Math.max(Math.round(rowMid - groupW / 2), CFG.mammothX + L1.clearance),
      CFG.mammothX + L1.clearance * 0.5,
      CFG.W - 60 - groupW
    );

    ground.gaps = ground.gaps.filter(g => g.repaired);
    const gaps = [], slots = [];
    /* THE NEAR LIP OF THE OPENING lands where the character stops. The record's x0 is the
       edge of the VOID beneath (the undercut), which is inside the platform; the opening
       — the neck — starts half an overhang further in. Without this shift he stopped an
       overhang short of the edge he is supposed to be standing at. */
    const ins0 = (mouthOf(share[0]) - throatW * share[0]) / 2;
    let x = originX + lead - ins0;
    for (let i = 0; i < n; i++) {
      const k = share[i];
      const th = throatW * k, gw = mouthOf(k), ins = (gw - th) / 2;
      const g = ground.addGap({
        x0: x, x1: x + gw, throat: th, open: 0, repaired: false,
        crack: 0, crackPts: makeCrack(),
        bridge: 0, splashes: null, slots: [], pieces: []
      });
      // the slots sit across the THROAT, each one plug wide, not across the mouth
      for (let j = 0; j < k; j++) {
        g.slots.push({
          /* Its crevasse by INDEX, not by reference. A slot holding its gap while the
             gap holds its slots is a cycle, and debug() is read straight out of the
             page by the tests — a cycle there cannot be serialised. */
          gapIndex: i, x0: x + ins + j * throatW, x1: x + ins + (j + 1) * throatW,
          // a lone slot IS its crevasse, which is the one-answer case unchanged
          full: k === 1, filled: false, reserved: false, kind: null
        });
      }
      slots.push(...g.slots);
      gaps.push(g);
      x += gw + L1.ditchGap;
    }
    /* No pieceW carried out any more: buildPhase asks optionBox for the same
       safe-area-centred box this used, so the two cannot disagree. */
    return { gaps, slots };
  }

  function buildPhase() {
    G.attempts = 0; G.idle = 0;
    const p = phaseCfg();
    const seedBase = p.id * 97;

    // the collapse already opened this phase's crevasses; reuse them so the puzzle
    // and the drama cannot disagree about where the ground gave way
    const layout = G.phaseLayout || layoutPhase(G.worldX);
    G.phaseLayout = null;
    G.gapsThisPhase = layout.gaps;

    // options: every target plus its distractors, shuffled, all the same material
    const kinds = p.targets.concat(p.distractors).slice(0, p.options);
    for (let i = kinds.length - 1; i > 0; i--) { const j = Math.floor(Math.random() * (i + 1)); [kinds[i], kinds[j]] = [kinds[j], kinds[i]]; }

    /* ONE BOX, MEASURED AND USED. The row is centred on the SAFE AREA, not on the
     * crevasse group, and that is what removes a bug rather than a preference.
     *
     * It used to be centred on the group, which made the row's box depend on where the
     * ditches are — while the ditches are now sized from the row's box. That cycle was
     * broken by measuring the box at the stage centre for the ditches and then
     * OVERRIDING box.w here, and the override is exactly the fault: `step` still came
     * from the recentred box while `w` came from the stage-centred one, so every chunk
     * was drawn wider than the slot it hangs in and the three of them overlapped into
     * one mass. Measured: 340px shapes on a step narrower than that.
     *
     * Centring on the safe area means the box that sized the ditches IS the box the
     * chunks hang in — one value, no override, and a shape can never be wider than its
     * own slot. The row sits slightly right of the stage centre because the safe area
     * starts clear of the character, which is where the crossing is anyway; the phase
     * zoom then pulls the whole composition together. */
    const box = optionBox(kinds.length);
    /* The one width, again from phasePieceW rather than from the box — the box decides
       WHERE each block hangs, this decides how WIDE it is, and the ditches were cut
       from the same call. Clamped to the box so a block can never be wider than the
       slot it hangs in, which is what made the row overlap into one mass before. */
    box.w = Math.min(box.w, phasePieceW(p));

    G.l1 = {
      phase: p, slots: layout.slots,
      /* THE REQUIRED SET — one entry per answer the phase wants, so "cut all the
         pentagons" is three entries and the phase cannot finish on one of them. */
      targets: p.targets.map(kind => ({ kind, filled: false })),
      /* WHAT the phase still wants, not WHERE. Any free slot takes any wanted shape,
         so the requirement is a multiset of kinds and the slot is chosen when the cut
         happens. Spliced at cut time — see targetFor — which is also what stops one
         correct kind being scored twice. */
      wanted: p.targets.slice(),
      unfilled: p.targets.slice(),
      wrong: 0, sealT: 0, filled: null, hintCount: 0, pulsedOnce: false,
      slotPulse: 0, slotWobble: 0,
      demo: p.tutorial ? { t: 0, done: false } : null,
      shapes: kinds.map((k, i) => {
        // Rotation is a recognition challenge, not geometry: the vertices stay
        // upright and only the renderer turns them, so a chunk can right itself on
        // the way down and still wedge square across the chasm.
        const rot = p.rotate ? ((i % 2 ? -1 : 1) * p.rotate * (0.6 + 0.5 * ((i * 37) % 7) / 7)) : 0;
        const seated = seatedChunk(k, box, { irregular: p.irregular, seed: seedBase + 7 * i + 3 });
        const pts = seated.pts;
        const b = polyBounds(pts);
        const x = box.startX + i * box.step;
        return {
          kind: k, x, y: -260, targetY: L1.optionY, phase: rand(0, 6.28),
          /* Measured, not assumed. A chunk is fitted uniformly into the row's box, so
             its real width and height depend on which shape it is — and the rope, the
             anchor and where it comes to rest are all sized from them. */
          baseRot: rot * Math.PI / 180, w: b.w, h: b.h, pts, art: seated.art,
          slotX: x, anchorX: x, tail: 0,
          seed: seedBase + 7 * i + 3,
          dropT: 0, cut: false, state: 'hang', rot: rot * Math.PI / 180,
          alpha: 1, scale: 1, fallT: 0, vy: 0
        };
      })
    };
    // the rope hangs from each chunk's own highest point, so the anchor goes above
    // THAT rather than above the chunk's centre — otherwise the body swings out of
    // its slot by the pivot's offset
    for (const sh of G.l1.shapes) {
      sh.pivot = chunkPivot(sh);
      sh.anchorX = sh.slotX + sh.pivot.x;
    }
  }

  /* THE HANGING ROW, for however many options the phase has — three, five or six.

     CENTRED ON THE CREVASSE. The row used to start clear of the character and run to
     the right edge, which bunched every option to the right of the hole they were
     going into. It is now symmetric about the middle of the crevasse group, so the
     options hang over the thing they repair.

     AND CLEAR OF THE CHARACTER. A cut chunk falls toward the crevasse, and one that
     hung over the character dropped a slab of ice on its head. Nothing may hang left
     of `mammothX + clearOfPlayer`, so the row is only as wide as the narrower of its
     two sides allows — the squeeze comes out of the shape size, never out of the
     safety margin. Keeping it symmetric is what makes the left side the binding
     constraint, since the crevasse sits left of centre on the stage.

     What goes in the box is scaled uniformly, so adding options makes a shape smaller
     but never squashes it: the sides stay countable, which is the only thing the
     learner is being asked to do. */
  function optionBox(n, centreX) {
    const safeL = CFG.mammothX + L1.clearOfPlayer;
    const safeR = CFG.W - 60;
    const mid = centreX === undefined ? (safeL + safeR) / 2 : centreX;
    const half = Math.min(mid - safeL, safeR - mid);
    const step = (half * 2) / n;
    return {
      step, startX: mid - half + step / 2,
      w: Math.max(80, Math.round(step - L1.optionMargin)),
      /* Tall enough that WIDTH is what limits a chunk, not height. Otherwise widening
         the row buys nothing: a pentagon is about as tall as it is wide, so a 210-high
         box capped every three-option chunk at 210 however much room the row had. */
      h: L1.optionH
    };
  }

  /** A chunk already turned into the pose it will seat in, fitted to the row's box.

      Hung in the orientation it will SEAT in: it used to hang in the shape's
      canonical pose and then flip on the way into the hole, because seat() lays the
      longest edge along the top. Seating it here means what the learner cuts is what
      drops in. Rotating changes the bounding box, so it is re-fitted afterwards —
      uniformly, or a regular polygon would come out with unequal sides. */
  /* THE PICTURE HAS TO TRAVEL WITH THE RING.

     The ring gets seated — rotated so its longest edge lies flat along the top, which
     is what makes a triangle hang point-down like the wedge it becomes — and then
     re-fitted to the row's box. Drawing an axis-aligned texture over a ring that has
     been rotated 40 degrees would tear the picture off the shape.

     So this returns the ring AND the transform that maps the artwork onto it. A point
     p of the artwork's own box lands at R(rot)p * scale - offset, which as canvas calls
     is translate(-offset), scale, rotate — applied in that order, then the image drawn
     over its own box. Both the hanging chunk and the wedged plug use it, so the two
     cannot disagree. */
  function seatedChunk(kind, box, opt) {
    const w = Math.min(box.w, SHAPE_W);
    const art = PolygonFactory.art(kind);
    const raw = PolygonFactory.chunk(kind, w, box.h, opt);
    const st = PolygonFactory.seat(raw, w);

    /* THE RE-CENTRING AFTER THE ROTATION IS THE WHOLE PROBLEM, and getting it wrong
       is what pulled every picture off its outline.

       seat() rotates the ring so its longest edge lies along the top and then hands
       back `center(out)` — the rotated ring shifted so ITS bounding box is centred on
       the origin. That shift is real and it is shape-specific: a bounding box centre
       is not a centroid, so as soon as a ring is rotated its box centre moves, and
       for every one of these shapes except a square it moves by a visible amount.

       The artwork was transformed by the rotation and the scale but NOT by that
       shift, so the picture sat a few degrees and a dozen pixels off the outline it
       was clipped to. Measured on the pentagon in a three-option row it was 13px, and
       the frame showed it plainly: a wedge of sky inside the ring down the left side
       and the painted top edge sitting below the drawn one.

       So the shift is computed HERE, explicitly, rather than being thrown away inside
       seat(): `turned` is the rotation on its own, `c1` is the box centre seat() would
       have subtracted, and the artwork is given exactly the same `-c1 * k` that the
       ring gets. The ring itself comes out identical to before — only the picture
       moves, onto it. */
    const cs = Math.cos(st.rot), sn = Math.sin(st.rot);
    const turned = raw.map(q => ({ x: q.x * cs - q.y * sn, y: q.x * sn + q.y * cs }));
    const tb = polyBounds(turned);
    const c1 = { x: (tb.x0 + tb.x1) / 2, y: (tb.y0 + tb.y1) / 2 };

    // the uniform re-fit, computed here so the picture can use the same number
    const k = Math.min(tb.w > 0 ? w / tb.w : 1, tb.h > 0 ? box.h / tb.h : 1);
    const pts = turned.map(q => ({ x: (q.x - c1.x) * k, y: (q.y - c1.y) * k }));
    /* What the renderer applies is translate(-off), scale(k), rotate(rot) — so a
       point p of the artwork lands at k*R(rot)*p - off. Setting off to c1*k makes that
       k*(R(rot)*p - c1), which is the ring above, exactly. */
    const off = { x: c1.x * k, y: c1.y * k };

    /* The artwork's own box, in the units `raw` was built in. chunk() fitted the
       registry ring into w x box.h, so the same fit describes where the texture goes. */
    const ab = polyBounds(raw);
    return {
      pts,
      art: art ? { id: kind, rot: st.rot, scale: k, off,
                   box: { x: ab.x0, y: ab.y0, w: ab.w, h: ab.h } } : null
    };
  }

  /** The repair slot a cut of this kind should fill, or null if the kind is not
      wanted — which is the entire definition of a wrong answer.

      ANY free slot accepts ANY wanted shape, and the one nearest the cut is chosen.
      Binding a crevasse to one shape made the learner guess an assignment they had
      never been told, on top of the recognition the level is actually teaching, and
      that stays true now there are three answers and two crevasses.

      Splicing `wanted` here is what makes "cut ALL the pentagons" work: each cut
      consumes exactly one entry, so a kind cannot be scored twice, a wrong kind is
      never in the list to begin with, and the phase is finished only when the list
      is empty — in whatever order the learner got there.

      The reservation is taken HERE and not at wedge time: a slot is not "filled"
      until the chunk lands, so without it two quick cuts would both take one slot. */
  function targetFor(kind, atX) {
    const L = G.l1; if (!L) return null;
    const i = L.wanted.indexOf(kind);
    if (i < 0) return null;
    const open = L.slots.filter(s => !s.filled && !s.reserved);
    if (!open.length) return null;
    const x = atX === undefined ? CFG.mammothX : atX;
    let best = open[0], bd = Infinity;
    for (const s of open) {
      const d = Math.abs((s.x0 + s.x1) / 2 - G.worldX - x);
      if (d < bd) { bd = d; best = s; }
    }
    L.wanted.splice(i, 1);
    L.unfilled = L.wanted.slice();
    // mark the required-set entry this cut answers, so `targets` reads as progress
    const t = L.targets.find(q => !q.filled && q.kind === kind);
    if (t) t.filled = true;
    best.reserved = true;
    best.kind = kind;               // the slot now expects what is on its way in
    return best;
  }

  /* A wedged chunk sits with its top just under the snow line, spanning its slot;
     the ice then grows over it. Both heights are taken from the chunk's OWN measured
     height rather than a constant, because a chunk is now fitted uniformly into the
     option row and so a triangle and an octagon are not the same size. */
  const restOnPath = sh => CFG.surfaceY - (sh.h || SHAPE_H) / 2;
  // top edge 30px below the snow line, so the snow laid over it has something to sit
  // on and the chunk is still clearly visible holding the crossing up
  const restWedged = sh => CFG.surfaceY + (L1.throatDepth || 30) + (sh.h || SHAPE_H) / 2;

  /** Screen-space centre of a repair slot, at the height a chunk wedges. */
  function slotCenter(s, sh) {
    return { x: (s.x0 + s.x1) / 2 - G.worldX, y: restWedged(sh) };
  }
  /** Where a WRONG chunk is aimed: the nearest slot that is still open water. While
      any answer remains, at least one slot is unfilled, so there is always somewhere
      for a wrong chunk to splash — a wrong answer can never land on the crossing. */
  function nearestOpenWater(x, sh) {
    const L = G.l1;
    const open = (L ? L.slots : []).filter(s => !s.filled);
    if (open.length) {
      let best = open[0], bd = 1e9;
      for (const s of open) {
        const d = Math.abs((s.x0 + s.x1) / 2 - G.worldX - x);
        if (d < bd) { bd = d; best = s; }
      }
      return slotCenter(best, sh);
    }
    const gaps = G.gapsThisPhase || [];
    if (!gaps.length) return { x, y: restWedged(sh) };
    return { x: (gaps[0].x0 + gaps[0].x1) / 2 - G.worldX, y: restWedged(sh) };
  }
  /** The crevasse a screen x is currently over, repaired or not. */
  function gapUnder(x) {
    return (G.gapsThisPhase || []).find(g => x > g.x0 - G.worldX && x < g.x1 - G.worldX) || null;
  }

  function cutShape(sh) {
    const L = G.l1;
    if (L.demo) L.demo.done = true;   // retire the gesture hint on a real cut, not on any tap
    sh.cut = true; sh.state = 'falling'; sh.fallT = 0; sh.vy = 0;
    L.filled = null; L.sealT = 0;
    /* The rope actually parts. Without this the chunk simply detached from a rope
       that stayed whole, and the one thing the learner just DID had no consequence
       on screen. */
    const span = ropeSpan(sh);
    sh.pivot = sh.pivot || chunkPivot(sh);
    sh.tail = 34;                                   // travels down with the chunk
    (L.stubs = L.stubs || []).push({
      x: span.x0, w: sh.w || SHAPE_W, len: (span.y1 - span.y0) * 0.72, t: 0
    });
    particles.frost(span.x0, span.y0 + 30, 5);
    audio.slice();
    particles.frost(sh.x, sh.y - (sh.h || SHAPE_H) / 2 - 20, 4);

    // correct if this kind is still wanted; it goes into the nearest free repair slot
    const target = targetFor(sh.kind, sh.x);
    sh.correct = !!target;
    sh.target = target;
    /* NO TICK AND NO CROSS. A right answer throws CONFETTI from the crossing; a wrong
       one gets no mark at all.

       The tick and cross were a verdict stamped over the scene — interface, drawn on
       the picture, saying in a symbol what the world was about to say in action. A
       right answer already has the wedge, the ring and the chord; a confetti SHOWER
       is the celebration a child understands without reading anything. A shower from
       the top, not a burst from a point and not star glints: that was the ask.

       A wrong answer keeps only the world's own response: the chunk sails past, the
       whistle falls, it hits the water. No cross, because a cross is a mark AGAINST
       the child, and everything else in this game is careful never to make one — the
       same rule that keeps the sad trombone out of the sound set. */
    if (!sh.correct) { L.wrong++; audio.reject(); }
    else if (!reduced) particles.confetti(CFG.W, 64);   // a shower across the stage, as asked
    sh.from = { x: sh.x, y: sh.y };
    sh.rest = { y: restOnPath(sh), wedge: restWedged(sh) };
    sh.socket = target ? slotCenter(target, sh) : nearestOpenWater(sh.x, sh);
    /* Both outcomes are CARRIED to where they belong as they fall, at the speed that
       gets them there by the time they arrive.

       A wrong chunk is thrown toward the water: it used to thud onto the path and
       topple, and a topple that ended up over solid ice just faded out — a block
       dropped on the road with no consequence at all. Its fall time is solved to the
       SURFACE, not the water, so it is over the hole by the moment it passes the lip.

       A correct chunk is carried to its slot the same way, and this is a change the
       several-slots-per-phase repair forced: it used to land on the path and grind
       sideways, and with slots spread across two crevasses that grind could set off
       across an open chasm at path level, which read as a block sliding on thin air.
       It is aimed at a slot no nearer the character than the near lip, so a chunk
       still cannot travel anywhere near the character. */
    const drop = Math.max(60, (sh.correct ? sh.rest.wedge : CFG.surfaceY) - sh.y);
    sh.vx = clamp((sh.socket.x - sh.x) / Math.sqrt(2 * drop / L1_GRAV), -1400, 1400);
    // correct: fall -> wedge.  wrong: fall -> splash -> gone
    sh.phaseName = 'fall';
    if (!sh.correct) audio.slideDown();
    G.attempts++;
    if (sh.correct) setState('PHASE_SUCCESS');
    else setState('PHASE_WRONG');
  }

  const L1_GRAV = L1.dropGravity;

  /* The chunk wedges into its slot. The slot is marked filled immediately and drops
     out of the free list, so a later wrong answer in the same phase can never undo
     it — earned progress is permanent. The crevasse itself is only `repaired`, and
     only starts bridging, once every slot in it is plugged. */
  function lockIn(L, sh) {
    // the tilt it was cut at, kept before the wedge squares it up
    const cutRot = sh.rot;
    sh.rot = 0;
    sh.phaseName = 'settle'; sh.impact = 1;
    audio.wedge();
    audio.fit();                        // the same chord for every right answer, in every level
    L.filled = sh; L.sealT = 0;
    particles.frost(sh.x, CFG.surfaceY, 6);
    particles.poof(sh.x, CFG.surfaceY, 6, 1.25);
    particles.chips(sh.x, CFG.surfaceY + 10, 6, -150);
    /* THE REWARD BEAT. Ice chips say 'something heavy landed'; a ring of glints says
       'that was RIGHT'. The two are different messages and the second one was missing,
       so a correct answer and a heavy thud looked the same. */
    particles.sparkle(sh.x, CFG.surfaceY - 30, reduced ? 5 : 11, 210);
    audio.twinkle();
    shake(reduced ? 1 : 2.6, 180);
    /* THE IMPACT BEAT, in the order it is felt: the world stops on the frame the chunk
       lands, the frame swells about the landing, and a hoop marks the spot. Together
       with the glints and the thud already above, that is the difference between a
       block arriving in a hole and an answer being RIGHT — which is what the game is
       for. No token and no pickup ding: see the note in CFG.juice. */
    hitStop(CFG.juice.stopWedge);
    punch(CFG.juice.punchWedge, CFG.juice.punchMs, sh.x, CFG.surfaceY);
    if (!reduced) particles.ring(sh.x, CFG.surfaceY - 20, 30, 210);

    const gapOf = s => s ? (G.gapsThisPhase || [])[s.gapIndex] : null;
    if (sh.target && gapOf(sh.target)) {
      const slot = sh.target;
      slot.filled = true;
      const g = gapOf(slot);
      // The wedged chunk becomes part of the crossing. The falling copy is retired
      // in the same breath — leaving both in play drew the chunk twice.
      /* The chunk GROWS to span ITS SLOT.
         A chunk dropped into a chasm is a small block in a big hole, no matter how
         well the bridge is drawn — the learner's answer has to visibly BECOME the
         crossing. So it swells until its longest edge spans the slot it took, and
         snow packs over the joins to hide the last of the seam. */
      /* IT FILLS THE SLOT BY ITS WIDTH. This used to scale the piece so its TOP EDGE
         spanned the slot, which works for a triangle — whose top edge IS its full width
         — and fails badly for everything else. A regular pentagon's top edge is about
         62% of its width, so making that edge 430px wide grew the whole shape to
         670x645 inside a 430px hole: the silhouette was then clipped away at both
         sides and what showed was a slab with cut edges, not a pentagon. Measured, the
         same rule left a concave pentagon 2px NARROWER than its slot, so some plugs
         were oversized and others left a visible gap.

         Scaling on the bounding width makes every shape fill its slot exactly, whatever
         its proportions. Where a shape's top edge is narrower than the slot the snow
         laid across the crossing covers the difference — which is what that snow is for.

         IT KEEPS THE ORIENTATION IT WAS CUT IN. The chunks are built already seated —
         longest edge flat along the top, so a triangle hangs point-down like the wedge
         it is about to become — so there is nothing here left to seat.

         Re-seating it was a real bug, and a subtle one. seat() picks the longest edge,
         and on a REGULAR polygon the edges are equal to within floating-point noise:
         a regular triangle's came out 177, 176.999938, 177. So the second call could
         pick a different edge from the first and hand back a rotation of 120 degrees —
         with vertices that were geometrically IDENTICAL, because 120 degrees is an
         equilateral triangle's own symmetry. The piece then animated a 120-degree roll
         to arrive at the orientation it already had, and the answer visibly flipped as
         it settled into the crevasse.

         So: the same vertices, and the growth scaled off the top edge that is already
         on top. The only roll left is the small tilt it was cut at. */
      /* HOW BIG THE PLUG IS — and this is the answer's whole payoff, so it matters
         more than anything else drawn in the crevasse.

         It used to be scaled so its BOUNDING WIDTH filled the slot. That reliably
         destroyed the shape. The cavity is only `waterDepth` (152px) deep before the
         meltwater, and a shape grown to a 620px-wide slot is 500px tall — so four
         fifths of it fell below the water line and was clipped away. Measured on the
         shipped build: phase 1's answer is a TRIANGLE and what the finished crossing
         showed was a TRAPEZOID, because the point was under the water. Phase 6's three
         pentagons showed as three vertical slabs. The learner cuts a shape, and the
         confirmation shows a different shape.

         So the plug is now scaled to fit ENTIRELY inside the visible cavity: whichever
         of width or height binds first, with a little margin, and never grown past the
         option size it was cut at. What it no longer does is span the gap — so the
         crossing is completed by an ice deck drawn from lip to lip beneath the snow
         (drawCrossingDeck), with the plugs hanging under it as visible keystones. The
         crossing still reads as mended; the answer stays countable. */
      const sb = polyBounds(sh.pts);
      const slotSpan = (slot.x1 - slot.x0);
      /* IT LANDS AT THE SIZE IT WAS CUT. Exactly 1:1, no scaling at all.

         This has been through three versions and the first two were both wrong in ways
         only a frame showed. Scaling the plug UP so its width filled the slot pushed
         most of it below the water line and clipped it away — phase 1's triangle came
         back as a trapezoid. Scaling it DOWN so the whole silhouette fitted the cavity
         halved it, and watching the learner's answer shrink by half as it settled is
         its own kind of wrong: the thing they cut is not the thing that arrives.

         So it does not resize. The block that comes down is the block that stays, at
         the size it hung at, which is the only version where "that is the shape I cut"
         is literally true. It is deeper than the cavity, and that is fine — the
         crevasse's own path runs past the bottom of the screen, so a big block wedged
         into a crack simply has its lower end out of frame, which is how a crack looks.
         drawCrossingFill closes the ice around whatever is left. */
      /* THE GEOMETRY DOES NOT ALLOW BOTH, so the resize is made INVISIBLE instead.

         There are only 190px between the walking line (surfaceY 890) and the bottom of
         the 1080 stage, and a three-option chunk is 233px tall. So a block cannot both
         land at exactly the size it was cut AND show its whole silhouette — at 1:1 a
         triangle's apex falls off the bottom of the screen and gets clipped, which is
         the very fault that made phase 1's answer look like a trapezoid.

         What was actually objectionable was watching it RESIZE. So the scale change
         stays (about 0.8, enough to fit whole) and the ANIMATION of it goes: the plug is
         drawn at its final size from its very first frame, inside the wedge burst —
         the impact squash, the shake, the chips and the chime all land on the same
         frame, and a single-frame size step inside that is not something an eye can
         pick out. Nothing is ever seen to shrink.

         PLUG_SINK is 0 here so the block keeps as much height as the stage allows. */
      const availH = CFG.H - CFG.surfaceY - 6;
      /* NO WIDTH CONSTRAINT ANY MORE, and this is the last place the old geometry was
       * still fighting the new one.
       *
       * It used to fit the plug into `slotSpan * 0.94` as well as the cavity height,
       * because a fixed 620px crevasse was far wider than any chunk and the slot was a
       * share of it. The ditch is now CUT FROM the piece — see layoutPhase — so that
       * constraint inverted: the slot is narrower than the chunk by exactly the bearing
       * the bridge needs at each end, and re-fitting to it shrank every piece back down
       * to the opening. Measured on phase 1: a 274px triangle scaled to 0.686 and landed
       * 188px wide, so it sat inside its hole instead of spanning it, and the bearing
       * the whole bridge idea rests on was scaled away.
       *
       * It also broke a standing rule the hard way: a plug that is re-fitted on landing
       * is a plug that visibly changes size between what was cut and what arrives.
       *
       * The height clamp stays. It is not redundant — it is what stops a tall shape
       * dropping its apex off the bottom of the stage, which is the fault that once
       * made phase 1's triangle read as a trapezoid. With optionH tied to the cavity
       * height it comes out at 1.0 for every phase, so in practice the piece now lands
       * at exactly the size it was cut. */
      const fitWhole = Math.min(1, sb.h > 0 ? availH / sb.h : 1);
      (g.pieces = g.pieces || []).push({
        kind: sh.kind, pts: sh.pts, seed: sh.seed, art: sh.art,
        /* The top of the seated silhouette, in the piece's own coordinates. The
           piece is positioned FROM this rather than from its centre: the top edge is
           the one that has to lie on the snow line, and how far it sits from the
           bbox centre differs per shape and is multiplied again by the fit scale, so
           one fixed centre put every shape's walking surface at a different height. */
        topLocal: polyBounds(sh.pts).y0,
        // the only roll: from the tilt it was cut at, back to square
        rot0: cutRot, rot: 0,
        grow: 0, fit: fitWhole,
        cx: (slot.x0 + slot.x1) / 2, cy: restWedged(sh), impact: 1,
        // its own span, so several plugs in one crevasse stay in their own lanes
        x0: slot.x0, x1: slot.x1, full: slot.full
      });
      /* The crossing is only mended when every slot in it is plugged. Until then the
         plugs that are in sit there visibly accepted, and the snow that seals the
         crossing waits — which is what makes a partly answered phase read as
         progress rather than as finished. */
      if (g.slots.every(s => s.filled)) { g.repaired = true; g.bridge = 0; }
      L.shapes = L.shapes.filter(s => s !== sh);
      L.unfilled = L.wanted.slice();
    }

    if (L.unfilled.length) {
      /* The SAME instruction, not a new line. It says "cut all the pentagons" and it
         still does; there is no "one more gap", no count of what is left, and no
         second sentence — those were more to read and taught nothing. */
      G.instruction = phaseCfg().instruction;
      G.instrLast = '';                 // force the card to re-enter rather than sit
      armInstruction(T.instructionRemind);
      mammoth.setState('LOOK_DOWN');
      if (L.slots.some(s => !s.filled)) L.slotPulse = 1;
    } else {
      mammoth.setState('CELEBRATE');
    }
  }

  function updateL1Piece(L, sh, dt) {
    if (sh.phaseName === 'fall') {
      sh.vy += L1_GRAV * dt;
      sh.y += sh.vy * dt;
      // a chunk on its way home turns itself square, so it wedges flat
      if (sh.correct) sh.rot = lerp(sh.rot, 0, dt * 7);

      /* EVERY wrong chunk ends in the water — it is carried sideways toward the
         nearest crevasse as it falls, so it clears the lip wherever it was cut. */
      if (!sh.correct) {
        /* THE WATER STOPS IT. Sideways travel only while it is still in the air.

           sh.vx is solved so the chunk arrives over its patch of water by the moment
           it passes the surface — and it used to keep accruing for the whole 0.8s of
           sinking afterwards, at the same speed, which is roughly another 500px. A
           chunk cut on the RIGHT of the row travels leftward, so it did not stop in
           the hole: it sailed straight out of the far side of it and across the ice
           toward the character. Measured: the socket is at x 1210, vx about -660, and
           the chunk's left edge reached 682 — inside the character's right edge at
           699. tests/regression.spec.mjs catches exactly this and was failing on it.

           It was also just wrong to watch. A block that has broken the surface of a
           meltwater pool does not carry on flying sideways under it. */
        /* IT MAY NEVER TRAVEL INTO THE CHARACTER, and it could.

           A wrong chunk is thrown sideways at the speed that puts it over open water
           by the time it has fallen far enough. If it then splashes, this stops. But a
           chunk whose fall does NOT end in water — one aimed across a narrow ditch that
           lands on solid ice instead — never sets `splashed`, so it kept accelerating
           sideways for as long as it existed. Cut from the right of the row it travels
           LEFT, and it was measured reaching x 569 in phases 2, 3 and 5, against a
           character whose right edge is at 699. A block was landing on the player.

           Two guards, because either alone leaves a hole. It stops once it has reached
           the x it was aimed at, which is the honest end of the throw; and its left
           edge is hard-clamped clear of the character regardless, so no future change
           to socket-picking can reintroduce this. The clamp is the invariant
           regression.spec asserts, and it is a safety rule rather than a nicety:
           nothing in this game is allowed to fall on the character. */
        if (!sh.splashed) {
          const reached = sh.socket && ((sh.vx > 0 && sh.x >= sh.socket.x) ||
                                        (sh.vx < 0 && sh.x <= sh.socket.x));
          if (!reached) sh.x += sh.vx * dt;
          const halfW = (sh.w || SHAPE_W) / 2;
          const floorX = CFG.mammothX + 300 + halfW;
          if (sh.x < floorX) { sh.x = floorX; sh.vx = 0; }
        }
        sh.rot += dt * 1.9;
        sh.scale = lerp(sh.scale, 0.62, dt * 1.6);
        const g = gapUnder(sh.x);
        const wy = g ? ground.waterY(sh.x, G.t) : CFG.H + 200;
        if (!sh.splashed && sh.y >= wy) {
          sh.splashed = true;
          if (g) ground.addSplash(g, sh.x, G.t);
          /* AT THE WATER LINE. It used to be thrown from CFG.surfaceY + 8 — the mouth
             of the crevasse, about 180px above the pool — on the reasoning that a
             splash down in the hole would be invisible. That was true before the pool
             was painted; its surface is clearly visible now, so the burst belongs where
             the chunk actually goes in. wy is the exact row the impact was detected on,
             including the surface's own bob. */
          particles.splash(sh.x, wy - 4, reduced ? 12 : 26);
          audio.splash();
          // a lighter hold than a correct answer, and no punch on the frame: a miss
          // should feel like a splash, not like the game hitting the player back
          hitStop(CFG.juice.stopSplash);
          shake(reduced ? 0.9 : 2.6, 240);
          // the reaction belongs to the SPLASH now: it used to fire when a wrong chunk
          // thudded onto the path, which no longer happens
          mammoth.setState('SURPRISED');
          mammoth.jolt(reduced ? 0.4 : 0.85);   // and recoils off the lip
          sh.sinkFrom = sh.y;
        }
        if (sh.splashed) {
          // under the surface it darkens and fades rather than dropping forever
          sh.sinkT = (sh.sinkT || 0) + dt;
          sh.y = sh.sinkFrom + sh.sinkT * 150;
          sh.submerged = clamp(sh.sinkT / 0.5, 0, 1);
          sh.alpha = clamp(1 - sh.sinkT / 0.72, 0, 1);
          if (sh.sinkT > 0.8) sh.phaseName = 'gone';
        }
        return;
      }

      /* A CORRECT chunk is carried across to its slot as it falls, then wedges. It
         closes the last of the distance on a lerp rather than on its velocity, so it
         arrives dead centre in the slot however the arithmetic rounded. */
      if (Math.abs(sh.x - sh.socket.x) > (sh.w || SHAPE_W) * 0.35) sh.x += sh.vx * dt;
      else { sh.vx = 0; sh.x = lerp(sh.x, sh.socket.x, clamp(dt * 7, 0, 1)); }

      if (!sh.entered && sh.y >= sh.rest.y - 30) {
        sh.entered = true;
        particles.frost(sh.x, CFG.surfaceY - 10, 5);
      }
      if (sh.y >= sh.rest.wedge) { sh.y = sh.rest.wedge; sh.impact = 1; lockIn(L, sh); }
    }
    if (sh.impact) sh.impact = Math.max(0, sh.impact - dt * 4);
  }
  function updateL1(dt) {
    const L = G.l1; if (!L) return;
    for (const sh of L.shapes) {
      if (sh.state === 'hang') {
        // held above the screen until the instruction has had the stage to itself
        if (!G.dropReady) continue;
        sh.dropT += dt;
        const dp = clamp((sh.dropT - 0.06) / (T.shapeDrop / 1000), 0, 1);
        sh.y = lerp(-220, sh.targetY, easeBackOut(dp));
        if (!sh.arrived && dp >= 1) { sh.arrived = true; audio.pop(); }
        /* No arrival bounce and no jiggle. Both were motion applied to a hanging
           option — the settle squash when the rope went taut, and the wobble when a
           swipe passed close and missed — and both are gone with the swing, for the
           same reason: the options hold perfectly still while the learner reads them.
           The missed-swipe feedback is now the sound alone. */
        if (sh.jiggle) sh.jiggle = 0;
        // Swings on arrival, then settles to almost still. A permanent wobble on all
        // three options was constant visual noise and made the ropes harder to cut.
        const swing = lerp(reduced ? 0.012 : 0.05, reduced ? 0.003 : 0.007,
                           clamp((sh.dropT - 0.6) / 2.6, 0, 1));
        /* The sway is applied by the renderer as one rotation of the whole rig about
           the rig line, so there is nothing to integrate here. `rot` and `x` are kept
           in step ONLY so that a cut piece starts from exactly where it was drawn — get
           this wrong and a chunk visibly jumps sideways the instant its rope parts.

           The maths has to mirror the renderer's transform exactly: rotate about
           ROPE_TOP, travel `len` down the rope, then offset by the pivot. */
        const piv = sh.pivot || chunkPivot(sh);
        const a = rigSwing();
        const len = (sh.y + piv.y) - ROPE_TOP;
        sh.rot = sh.baseRot + a;
        sh.x = sh.anchorX + Math.sin(a) * len - (piv.x * Math.cos(a) - piv.y * Math.sin(a));
      } else if (sh.state === 'falling') {
        sh.fallT += dt;
        updateL1Piece(L, sh, dt);
      }
    }
    if (L.demo && !L.demo.done && G.state === 'PHASE_ACTIVE' && G.attempts === 0) {
      L.demo.t += dt;
      if (L.demo.t > 1.9) L.demo.done = true;
    }
    if (L.stubs) {
      for (const st of L.stubs) st.t += dt;
      L.stubs = L.stubs.filter(st => st.t < 30);   // a cut rope stays cut
    }
    L.slotWobble = lerp(L.slotWobble, 0, dt * 5);
    L.slotPulse = Math.max(0, L.slotPulse - dt * 1.1);
    if (L.filled) L.sealT = Math.min(1, L.sealT + dt * 1.6);

    // ice creeping out from both lips to meet whatever is wedged in the middle: this
    // is what turns "a chunk sitting in a hole" into "a crossing"
    const step = dt * 1000 / L1.bridgeMs;
    for (const g of (G.gapsThisPhase || [])) {
      if (g.repaired && g.bridge < 1) {
        g.bridge = Math.min(1, g.bridge + step);
        if (g.bridge >= 1 && !g.bridgeDone) {
          g.bridgeDone = true; audio.seal();
          /* THE CROSSING IS WHOLE. A burst of glints up off the mended span and the
             resolved phrase: the payoff for the phase, placed on the crossing itself
             rather than over the character, because the crossing is what the learner
             just fixed. */
          const cx = (g.x0 + g.x1) / 2 - G.worldX;
          if (!reduced) particles.confetti(CFG.W, 40);   // confetti, not star glints
          punch(CFG.juice.punchWin, 380, clamp(cx, 200, CFG.W - 200), CFG.surfaceY - 40);
          audio.prize();
        }
      }
    }
  }


  /* HOW A MENDED CROSSING IS BUILT, top to bottom:

       the snow band      drawCrossingSnow — one unbroken white surface over every join
       the ice deck       drawCrossingDeck — lip to lip, the thing that spans the gap
       the keystones      drawKeystone     — the learner's answers, whole and countable
       the crevasse       still open below them, water still visible at the bottom

     THE DECK IS NEW, and it is what made it possible to stop mangling the answers. The
     plug used to be grown until it spanned its slot on its own, which is why it had to
     be clipped and why the clipping destroyed the shape. Now the deck spans the gap and
     the plugs hang beneath it at a size that keeps them intact — which is both the
     honest arch construction (a keystone does not span an arch, it closes one) and the
     only version where the learner can still see what they cut. */
  /* ZERO: the plug's top edge sits ON the walking line, flush with the platforms — the
     picture the brief drew, a slab you walk straight onto. The mouth above the throat is
     wider than the plug; those shoulders are closed by drawCrossingCollar BEHIND it, the
     slab's own flared ends, so nothing is laid over the answer. A 30px sink with a deck
     and a snow band on top was tried and asked to go: it hid the top of the shape and
     the snow strip read as interface. */
  /* -9: the plug seats a little PROUD of the walking line, so its flat edge covers the
     chewed top edge of the neck (which reaches 9px above the line — see _profile). At 0
     a dark sliver of hole showed between the snow and the answer. A wedged slab standing
     a hair above the ice is also what a wedged slab looks like. */
  const PLUG_SINK = -9;


  /* How fast a landed plug settles: grow is the swell easing to rest, impact the squash
     recovering. Per second of game time. (These sat beside the old deck code and were
     nearly lost with it — they belong here, with the one function that reads them.) */
  const PIECE_GROW = 3.3, PIECE_IMPACT = 2.7;
  function updatePieces(dt) {
    for (const g of ground.gaps) {
      if (!(g.pieces && g.pieces.length)) continue;
      for (const p of g.pieces) {
        if (p.grow === undefined) p.grow = 0;
        if (p.grow < 1) p.grow = clamp(p.grow + dt * PIECE_GROW, 0, 1);
        if (p.impact) p.impact = Math.max(0, p.impact - dt * PIECE_IMPACT);
      }
    }
  }

  /* WHERE TO SCALE ABOUT, solved rather than chosen.
   *
   * Scaling by k about f maps a stage point p to f + (p - f) * k, so every point
   * further from f than the frame edge moves OUT of frame. The things that must stay
   * visible are the rightmost block, the character on the left, and the water at the
   * bottom of the ditch. Rearranging the map for each of those gives a permitted
   * range for f, and the crossing centre is then clamped into it — so the camera
   * points at the puzzle whenever it can, and gives up exactly as much of that as it
   * must to keep a block on screen.
   *
   * Doing this the other way round — picking a nice-looking focus and a nice-looking
   * scale — is what clips the sixth option in a six-option phase, on a stage width
   * nobody tested. */
  function viewFocus(k) {
    const M = 8;                                  // px of slack at each edge
    const rightMost = CFG.W - 60;                 // the option row reaches here
    const leftMost = CFG.mammothX - 120;          // the character stays in shot
    const bottomMost = CFG.surfaceY + CFG.levelOne.waterDepth;
    const topMost = 60;                           // the instruction pill sits below this
    // f + (p - f) k <= limit   =>   f (1 - k) <= limit - p k   =>   f >= (limit - p k)/(1 - k)
    const fx = {
      min: (CFG.W - M - rightMost * k) / (1 - k),
      max: (M - leftMost * k) / (1 - k)
    };
    const fy = {
      min: (CFG.H - M - bottomMost * k) / (1 - k),
      max: (M - topMost * k) / (1 - k)
    };
    return { fx, fy };
  }

  /** Aim the view at the crossing, as far as the frame allows. */
  function aimZoom() {
    const gaps = (G.gapsThisPhase || []).filter(Boolean);
    if (!gaps.length) { G.zoomWant = 1; return; }
    const k = CFG.levelOne.zoomK;
    const cx = (gaps[0].x0 + gaps[gaps.length - 1].x1) / 2 - G.worldX;
    const { fx, fy } = viewFocus(k);
    G.zoomVX = clamp(cx, Math.min(fx.min, fx.max), Math.max(fx.min, fx.max));
    /* Between the blocks and the ditch, so both are pulled towards the middle rather
       than one of them being centred and the other pushed to an edge. */
    const mid = (CFG.levelOne.optionY + CFG.surfaceY) / 2;
    G.zoomVY = clamp(mid, Math.min(fy.min, fy.max), Math.max(fy.min, fy.max));
    G.zoomWant = k;
  }

  /* ---- shake: amplitude decays over its life instead of cutting off flat ---- */
  function shake(amp, ms) {
    if (reduced) amp *= 0.4;
    G.shake = amp; G.shakeAmp = amp; G.shakeT = ms / 1000; G.shakeLen = ms / 1000;
  }

  /* HIT-STOP. The simulation stops dead for a few frames while rendering carries on,
     so the impact frame is held long enough to be seen. Two heavy things meeting is
     the one moment real motion briefly stops, which is why this reads as weight and
     not as a dropped frame — provided it stays short. CFG.juice.stopMax is a hard
     ceiling so no caller, and no two callers landing on the same frame, can stall the
     game: the longest possible pause is an eighth of a second.

     It is deliberately NOT the pause flag. Pause halts rendering too and is a player
     control; this halts only time, and the player cannot tell it happened except by
     feeling the hit land. */
  function hitStop(ms) {
    if (reduced) return;                                  // motion sensitivity: no holds
    G.freeze = Math.min(CFG.juice.stopMax / 1000, Math.max(G.freeze || 0, ms / 1000));
  }

  /* CAMERA PUNCH. A scale pulse about the point the impact happened: it snaps to full
     on the impact frame and eases out, because anything that ramps IN is anticipation
     and an impact has already happened by the time you see it.

     Scaling about the event rather than the stage centre is what keeps it from reading
     as a lurch — the thing you are looking at stays exactly where it was while the
     frame swells around it. Amplitudes are in the region of 2%: past about 3% the
     letterboxed edges start to show as the world pulls in from the frame. */
  function punch(amp, ms, x, y) {
    if (reduced) return;
    G.punchAmp = amp; G.punchT = 0;
    G.punchLen = (ms || CFG.juice.punchMs) / 1000;
    G.punchX = x === undefined ? CFG.W / 2 : x;
    G.punchY = y === undefined ? CFG.surfaceY : y;
  }

  /* An earthquake, for the ground giving way.
     Two things make this read as shaking ground rather than as a juddering camera:

     WAVEFORM. An impact is a random jolt, so the one-shot shake() above is white
     noise — correct for a bonk. A quake is not: random offsets every frame at 60fps
     are 30Hz noise, which looks like video static. This runs on a pair of sines in
     the 7-13Hz range with only a trace of noise on top, and moves the ground about
     twice as far horizontally as vertically, which is what shaking looks like from
     the side.

     TIMING. The envelope is keyed to the EVENT, not to the clip: it builds through
     the anticipation, peaks on the frame the ice actually cracks, and is back to
     zero exactly as the skid ends — so it never runs on into the instruction. It
     used to peak 350ms after the crack and shake for another 260ms afterwards. */
  function quake(amp, ms, peakMs) {
    if (reduced) amp *= 0.35;
    G.quakeAmp = amp;
    G.quakeT = 0;
    G.quakeLen = ms / 1000;
    G.quakePeak = (peakMs === undefined ? ms * 0.3 : peakMs) / 1000;
  }

  /** 0..1 envelope: builds to the break, then rattles out. */
  function quakeEnv() {
    if (G.quakeLen <= 0 || G.quakeT >= G.quakeLen) return 0;
    const t = G.quakeT, p = Math.max(0.001, G.quakePeak);
    if (t < p) return 0.22 + 0.78 * Math.pow(t / p, 1.7);      // the ground starts to go
    const tail = Math.max(0.001, G.quakeLen - p);
    return Math.max(0, 1 - Math.pow((t - p) / tail, 0.85));    // aftershock
  }

  /* Stars circling a knocked-out head. Only for a character whose knockout art does
     not already have them drawn in — the cub's does, the mammoth's does not, and two
     sets at once looks like a mistake. */
  /* THE DIZZY SWIRL. The classic scribble round a knocked-out head: a dashed loop that
     runs, and four fat gold stars riding it, bigger in front and smaller behind, each
     GLOWING — a soft gold light off each star and the loop, no keyline: a drawn outline
     read as a sticker on the picture, light reads as light. It arrives with a bounce
     once he is sitting (the sheet takes ~1.1s to tumble into the sit). Three small
     outline-less stars were here first and did not read at stage size. */
  function drawDazeStars(ctx) {
    if (!mammoth.koStars || mammoth.state !== 'KNOCKOUT') return;
    const t = mammoth.t;
    const u = clamp((t - 0.55) * 2.6, 0, 1);            // from the tumble, so they are seen at once
    if (u <= 0.01) return;
    const pop = 1 + Math.sin(u * Math.PI) * 0.5;
    const cx = CFG.mammothX - (mammoth.knock || 0) - 60;
    const cy = CFG.surfaceY - 345 + Math.sin(t * 2.2) * 4;   // the loop hovers over his crown, clear of his eyes
    const RX = 112, RY = 30, STARS = 5, spin = t * 3.8;
    ctx.save();
    ctx.globalAlpha = u;
    // the loop itself, dashed and running, tilted a touch like a halo knocked askew
    ctx.save();
    ctx.translate(cx, cy); ctx.rotate(-0.12);
    ctx.setLineDash([14, 10]); ctx.lineDashOffset = -t * 140;
    ctx.shadowColor = 'rgba(255,204,84,1)'; ctx.shadowBlur = 22;
    ctx.lineCap = 'round'; ctx.lineWidth = 6; ctx.strokeStyle = 'rgba(255,236,160,0.98)';
    ctx.beginPath(); ctx.ellipse(0, 0, RX, RY, 0, 0, 6.2832); ctx.stroke();
    ctx.shadowBlur = 0;
    ctx.setLineDash([]);
    ctx.restore();
    for (let i = 0; i < STARS; i++) {
      const a = spin + (i / STARS) * 6.2832;
      const x = cx + Math.cos(a) * RX, y = cy + Math.sin(a) * RY;
      const depth = (Math.sin(a) + 1) / 2;                 // 1 at the front of the loop
      const sc = (0.8 + 0.6 * depth) * pop;
      ctx.save();
      ctx.translate(x, y); ctx.scale(sc, sc); ctx.rotate(t * 2.6 + i);   // each star spins on its own
      ctx.beginPath();
      for (let k = 0; k < 5; k++) {
        const o = (k / 5) * 6.2832 - Math.PI / 2, i2 = o + 6.2832 / 10;
        ctx.lineTo(Math.cos(o) * 32, Math.sin(o) * 32);
        ctx.lineTo(Math.cos(i2) * 14, Math.sin(i2) * 14);
      }
      ctx.closePath();
      const g = ctx.createLinearGradient(0, -32, 0, 32);
      g.addColorStop(0, '#FFF6C4'); g.addColorStop(1, '#F7B733');
      // the glow: the star's own light, drawn twice so the halo is wide and the core bright
      ctx.shadowColor = 'rgba(255,190,50,1)'; ctx.shadowBlur = 38; ctx.fillStyle = g; ctx.fill();
      ctx.shadowBlur = 9; ctx.fill();
      ctx.shadowBlur = 0;
      ctx.restore();
    }
    ctx.restore();
    ctx.globalAlpha = 1;
  }
  /* ---- impact burst drawn at the point of collision ---- */
  function drawHitFx(ctx) {
    if (G.hitFx <= 0) return;
    const p = 1 - G.hitFx;                       // 0 at impact -> 1 at the end
    const x = CFG.mammothX + 74, y = CFG.surfaceY - 96;
    ctx.save();
    // radiating ice sparks
    const n = reduced ? 5 : 9;
    for (let i = 0; i < n; i++) {
      const a = (i / n) * 6.2832 + 0.4;
      const d = 26 + easeOut(p) * 76;
      const len = 20 * (1 - p);
      ctx.globalAlpha = clamp(1 - p * 1.15, 0, 1) * 0.9;
      ctx.strokeStyle = i % 2 ? C.frost : C.lightIce;
      ctx.lineWidth = 4 * (1 - p * 0.6);
      ctx.lineCap = 'round';
      ctx.beginPath();
      ctx.moveTo(x + Math.cos(a) * d, y + Math.sin(a) * d * 0.72);
      ctx.lineTo(x + Math.cos(a) * (d + len), y + Math.sin(a) * (d + len) * 0.72);
      ctx.stroke();
    }
    // one soft warm flash at the contact point — no strobe, single fade
    ctx.globalAlpha = clamp(1 - p * 1.6, 0, 1) * 0.5;
    const fg = ctx.createRadialGradient(x, y, 0, x, y, 130);
    fg.addColorStop(0, 'rgba(255,236,190,0.95)');
    fg.addColorStop(1, 'rgba(255,214,150,0)');
    ctx.fillStyle = fg;
    ctx.beginPath(); ctx.arc(x, y, 130, 0, 6.2832); ctx.fill();
    ctx.restore();
    ctx.globalAlpha = 1;
  }

  /* ---- input ---- */
  /* CLIENT COORDINATES -> STAGE COORDINATES.

     The canvas rectangle is CACHED. getBoundingClientRect() forces the browser to
     flush pending layout, and this used to run on every single pointermove — so on a
     touch device sampling at 120Hz the game demanded a layout recalculation 120 times
     a second, while the HUD was writing to the DOM in the same frame. That is the
     textbook layout-thrash pattern and it is the most expensive thing a canvas game
     can do to itself.

     The rect only changes when the window does, so it is re-read on resize and on
     orientationchange and nowhere else. */
  let canvasRect = null;
  const invalidateRect = () => { canvasRect = null; };
  window.addEventListener('resize', invalidateRect);
  window.addEventListener('orientationchange', invalidateRect);
  function rect() {
    if (!canvasRect || !canvasRect.width) canvasRect = canvas.getBoundingClientRect();
    return canvasRect;
  }
  function toLocal(e) {
    const r = rect();
    return { x: (e.clientX - r.left) * CFG.W / r.width, y: (e.clientY - r.top) * CFG.H / r.height };
  }
  /* THE STROKE IN PROGRESS, and WHOSE finger it belongs to.

     `slash.id` is new and it fixes a real cut. onMove took every pointermove it was
     given, so a second finger anywhere on the screen — a thumb resting on the frame,
     a child using two hands — fed its position into the SAME polyline. The stroke then
     jumped between the two contacts, and the segment joining them swept across the
     whole option row and cut whatever rope it crossed. The learner had not swiped
     through it. Only the pointer that started the stroke can extend it now. */
  let slash = null;

  /* IS THE POINTER ON THE MAMMOTH?
     Deliberately narrower than the sprite, which is 735px wide and reaches x 797 —
     just past the 770 the option row starts at. Held to ±250 of mammothX it stops at
     680, so a tap meant for the leftmost rope can never be read as a tap on him. */
  function onMammoth(p) {
    return p.x > CFG.mammothX - 250 && p.x < CFG.mammothX + 250 &&
           p.y > CFG.surfaceY - 430 && p.y < CFG.surfaceY + 30;
  }

  /* HE IS TOUCHABLE. Tap the mammoth and he toots, bounces and kicks up snow.

     It changes NOTHING: no state, no progress, no answer, and it is refused outright
     while he is mid-air or knocked out so it can never interrupt a jump or a crash.
     It is here because a character that ignores being poked is scenery, and every
     child who is handed this will poke him within about four seconds. */
  let pokeAt = -1e9;
  function pokeMammoth() {
    if (performance.now() - pokeAt < 420) return false;      // no machine-gunning it
    if (mammoth.airborne || mammoth.state === 'KNOCKOUT' || G.complete) return false;
    pokeAt = performance.now();
    audio.toot();
    // a hop, a squash on the way down, and a puff off the snow
    mammoth.hop = Math.max(mammoth.hop, 16);
    mammoth.squash = 0.9;
    mammoth.jolt(0.34);
    particles.poof(CFG.mammothX - 10, CFG.surfaceY, reduced ? 2 : 5, 1.3);
    particles.sparkle(CFG.mammothX + 30, CFG.surfaceY - 300, reduced ? 2 : 5, 120);
    return true;
  }

  /* TAP TO GET ON WITH IT.

     Measured over a full playthrough: 8.2 seconds of a 296-second run are interactive.
     Three per cent. A third of the rest is running, and every puzzle opens with a fixed
     5.0s of pre-roll — 2.3s of collapse, 2.0s of the instruction card holding the stage
     alone, then 0.7s of the chunks descending — with no way past any of it. Seven
     puzzles, so 35 seconds of a five-minute game is spent watching a beat the player has
     already seen six times.

     A tap now advances both of those beats, and this is the one place that time can be
     reclaimed for free:

       - the collapse still HAPPENS. Jumping the clock to its final frame runs the same
         last step, so the crevasses open, the character lands where the layout expects
         and the fright still fires. What is skipped is the watching, not the event.
       - the card's read-hold is the only thing it loses, and the card does not go away:
         it stays up for the whole playable phase. So a learner who wants to read it
         still can, for as long as they like, and one who has read it six times already
         is not made to wait a seventh.

     Deliberately NOT skippable: the run segments (they are the journey), and the wrong
     and success beats (they are the feedback — a splash cut short teaches nothing). */
  function skipPreRoll() {
    if (G.state === 'GLACIER_BREAK_1' && G.st < T.breakSkid - 1) {
      G.st = T.breakSkid - 1;         // one step short, so the final frame still runs
      return true;
    }
    if (G.state === 'PHASE_INTRO' && !G.dropReady && G.st < T.introRead) {
      G.st = T.introRead;
      return true;
    }
    return false;
  }

  function onDown(e) {
    if (paused) return;
    audio.start(); audio.resume();
    const p = toLocal(e);
    G.idle = 0; G.idleHand = 0; G.handHint = null;
    addTap(p.x, p.y);                 // every touch gets an answer, in every state
    skipPreRoll();                    // a tap gets past the collapse and the card
    /* THE STROKE IS ARMED THROUGH THE WHOLE OF A PUZZLE, not only in PHASE_ACTIVE.

       In a multi-answer phase ("cut all the pentagons") the state leaves PHASE_ACTIVE
       for PHASE_SUCCESS the moment a correct rope is cut and does not come back until
       the plug has grown and the bridge has closed — over a second in which the
       remaining ropes are still hanging there, still look cuttable, and a pointerdown
       armed nothing at all. The learner had to lift and swipe again, with no
       indication why the first attempt was ignored. PHASE_WRONG is the same, for
       longer.

       Arming the stroke in those states is safe because the CUT is still gated: onMove
       only cuts when the game is in PHASE_ACTIVE. So a stroke begun a moment early
       lands the instant play resumes, instead of being thrown away. */
    if (G.state === 'PHASE_ACTIVE' || G.state === 'PHASE_SUCCESS' || G.state === 'PHASE_WRONG') {
      slash = { pts: [p], t: 0, dist: 0, id: e.pointerId };
      /* The ropes used to quiver when a drag began. Removed with the rest of the
         hanging motion — what says "these are interactive" now is the warm halo and the
         sheen sweeping across the ice, which are light rather than movement and so do
         not disturb the shape being read. */
    }
    /* The poke is ADDITIVE — the slash above is still armed, so a stroke that starts
       over him and sweeps out to a rope still cuts. He is not a button that swallows
       the gesture. */
    if (onMammoth(p)) pokeMammoth();
    canvas.setPointerCapture && canvas.setPointerCapture(e.pointerId);
  }
  /* HOW FAR THE FINGER HAS TO TRAVEL BEFORE A CUT COUNTS.

     There was no minimum. `nearSeg(p, top, bot, 30)` fired on the FIRST pointermove
     inside 30px of a rope, so a press with one pixel of drift — a tap, in other words,
     or a finger settling on the screen — committed an answer the learner had not
     chosen. In a game whose whole score is "did you pick the right polygon", an
     accidental commit is the worst possible input bug.

     36 stage pixels is about 13 real pixels on a phone-landscape stage: far below a
     deliberate swipe, far above a tap's jitter and above the ~10px slop a touch
     screen reports for a stationary finger. A crossing stroke still cuts on the
     segment test at any length, because a stroke that has geometrically crossed the
     rope is unambiguous — the minimum only guards the proximity test. */
  const CUT_MIN_TRAVEL = 36;

  function onMove(e) {
    if (paused) return;
    const p = toLocal(e);
    atmos.pointer(p.x);
    // only the finger that began the stroke may extend it; see the note on slash.id
    if (slash && slash.id !== undefined && e.pointerId !== undefined &&
        e.pointerId !== slash.id) return;
    if (slash) {
      const prev = slash.pts[slash.pts.length - 1];
      if (prev) slash.dist += Math.hypot(p.x - prev.x, p.y - prev.y);
      slash.pts.push(p);
      if (slash.pts.length > 26) slash.pts.shift();
      // hit test ropes — but only while the phase is actually playable
      const L = G.l1;
      if (L && G.state === 'PHASE_ACTIVE' && slash.pts.length > 1) {
        const a = slash.pts[slash.pts.length - 2], b = p;
        for (const sh of L.shapes) {
          if (sh.state !== 'hang') continue;
          /* EXACTLY THE ROPE THAT IS DRAWN, all of it.

             The hit segment used to start at `rigY - 10` = y 140, while drawRope draws
             from ROPE_TOP = -24 — so the top 164px of every visible rope, about a
             third of it, looked perfectly cuttable and was not. A learner swiping high,
             which is the natural place to cut a hanging rope, got nothing and no
             explanation. Starting the segment where the rope is actually drawn is the
             whole fix. */
          const s2 = ropeSpan(sh);
          const top = { x: s2.x0, y: ROPE_TOP };
          const bot = { x: s2.x1, y: s2.y1 };
          const crossed = segIntersect(a, b, top, bot);
          const grazed = slash.dist >= CUT_MIN_TRAVEL && nearSeg(p, top, bot, 30);
          if (crossed || grazed) {
            slash = null; cutShape(sh); return;
          }
        }
      }
    }
  }
  function nearSeg(p, a, b, tol) {
    const vx = b.x - a.x, vy = b.y - a.y;
    const l2 = vx * vx + vy * vy || 1;
    let t = ((p.x - a.x) * vx + (p.y - a.y) * vy) / l2;
    t = clamp(t, 0, 1);
    return Math.hypot(a.x + vx * t - p.x, a.y + vy * t - p.y) < tol;
  }
  /* A SWIPE THAT CUT NOTHING.

     Until now this was completely silent: the learner swiped, the stroke faded, and
     the game gave no sign it had even seen the gesture — which is indistinguishable
     from the game being broken, and is the single most likely thing to happen on a
     first attempt.

     So a real stroke that hit no rope makes the ropes it passed near JIGGLE, with a
     puff of air. It says "that was a cut, but not through a rope" and it says nothing
     whatever about which rope is the answer: EVERY rope inside the radius jiggles by
     the same amount, wanted or not. A short stroke is ignored, so a tap is not a
     failure message. */
  function missedSwipe() {
    const L = G.l1;
    if (!L || !slash || slash.dist < 46 || slash.pts.length < 2) return;
    const CM = CFG.comedy;
    let any = false;
    for (const sh of L.shapes) {
      if (sh.state !== 'hang') continue;
      const s2 = ropeSpan(sh);
      // the same full span the cut test uses, so "near a rope" means the same thing
      const a = { x: s2.x0, y: ROPE_TOP }, b = { x: s2.x1, y: s2.y1 };
      // the closest the stroke came to this rope
      let d = Infinity;
      for (const q of slash.pts) {
        const vx = b.x - a.x, vy = b.y - a.y;
        const l2 = vx * vx + vy * vy || 1;
        const t = clamp(((q.x - a.x) * vx + (q.y - a.y) * vy) / l2, 0, 1);
        d = Math.min(d, Math.hypot(a.x + vx * t - q.x, a.y + vy * t - q.y));
      }
      if (d < CM.jiggleRadius) {
        /* Nearly FLAT across the radius — 0.5 at the edge rising to 0.9 at the rope.
           Proportional-to-distance was tried and is wrong here: it makes the rope
           closest to the stroke visibly livelier than its neighbours, which on a
           near-miss beside the answer is a hint nobody asked for. Every rope the
           stroke came near answers, and answers about the same. */
        sh.jiggle = Math.max(sh.jiggle || 0, 0.5 + (1 - d / CM.jiggleRadius) * 0.4);
        // it swings away from the stroke, so neighbours part rather than moving as one
        sh.jiggleDir = sh.anchorX < slash.pts[slash.pts.length - 1].x ? -1 : 1;
        any = true;
      }
    }
    if (any) audio.whiff();
  }

  function onUp(e) {
    if (paused) { slash = null; return; }
    if (slash && slash.id !== undefined && e && e.pointerId !== undefined &&
        e.pointerId !== slash.id) return;      // a different finger lifting
    if (slash) { missedSwipe(); slash = null; }
  }

  /* THE STROKE IS ABANDONED, not finished.

     There was no pointercancel handler at all. The browser fires it whenever it takes
     the pointer away mid-gesture — a system edge-swipe, a notification, the palm of a
     hand, a page scroll it decided to own — and without this the stroke stayed LIVE
     with its last known point still in the polyline. The next pointermove then joined
     that stale point to wherever the finger now was, and the segment between them
     swept the option row and cut a rope. On a phone this was reachable just by
     swiping in from the screen edge.

     It drops the stroke silently rather than calling missedSwipe(): the gesture was
     taken away from the player, so telling them they missed would be a lie. */
  function onCancel() { slash = null; }

  function onKey(e) {
    if (paused) return;
    if (e.code === 'Space' || e.code === 'ArrowUp' || e.code === 'KeyW') {
      /* SPACE BELONGS TO A FOCUSED BUTTON FIRST.

         This called preventDefault() unconditionally on a window listener, which
         cancelled the browser's own "Space activates the focused button". The Try
         Again card focuses its button when it opens — so a keyboard player could tab
         to Try Again, press Space, and have the jump fire instead of the button, with
         the panel still up and the world still stopped. Same for Replay on the
         Journey Complete card.

         ArrowUp and KeyW are unaffected: no button activates on those, so they still
         belong to the jump wherever the focus is. */
      const el = document.activeElement;
      const onButton = el && el !== document.body &&
                       (el.tagName === 'BUTTON' || el.getAttribute('role') === 'button');
      if (e.code === 'Space' && onButton) return;
      e.preventDefault();
      // the same keys that jump also get past the collapse and the card
      if (skipPreRoll()) return;
      api.jump();
    }
  }
  canvas.addEventListener('pointerdown', onDown);
  canvas.addEventListener('pointermove', onMove);
  window.addEventListener('pointerup', onUp);
  /* Both cancels. pointercancel is the browser taking the gesture away;
     lostpointercapture fires when the capture set in onDown is released out from under
     us, which is the same situation seen from the other side. Either one has to drop
     the stroke or it stays live with a stale point in it — see onCancel. */
  window.addEventListener('pointercancel', onCancel);
  canvas.addEventListener('lostpointercapture', onCancel);
  window.addEventListener('keydown', onKey);

  /* ---- hints ---- */
  /* Nothing here reveals an answer. The learner is never shown which shape fits or
     which corners make a diagonal — the only nudges point at WHERE the problem is
     (the hole, the corners), so the reasoning stays theirs. */
  function updateHints(dt) {
    if (G.state === 'PHASE_ACTIVE') {
      G.idle += dt;
      const L = G.l1; if (!L) return;
      // one pulse of the notch itself, so a stuck learner looks at the hole
      /* Two hints, two clocks. The pulse below resets G.idle, which meant the hand
         hint's 13s could never be reached — the pulse fired at 7s and put the
         counter back to zero, so the two guidance stages were competing for one
         timer instead of escalating. */
      G.idleHand += dt;
      if ((L.wrong >= 1 || G.idle > CFG.hint.slotMs / 1000) && L.slotPulse <= 0 && !L.pulsedOnce) {
        L.pulsedOnce = true; L.slotPulse = 1; G.idle = 0;
      }
      /* After a long idle, demonstrate the GESTURE. Placed on the middle rope, which
         is a position not an answer: it says "ropes are cut like this", never "cut
         this one". It leaves the instant anything is touched. */
      if (G.idleHand > CFG.hint.idleMs / 1000 && L.shapes.length) {
        const mid = L.shapes[Math.floor(L.shapes.length / 2)];
        G.handHint = { x: mid.anchorX, y: (L1.rigY + mid.y - (mid.h || SHAPE_H) / 2) / 2 };
      } else {
        G.handHint = null;
      }
    }
  }

  /* ---- update ---- */
  function update(dt) {
    /* THE HIT-STOP GATE. Time does not advance while a hold is running — not G.t, not
       the state clock, not a single subsystem — so the frame the impact happened on is
       what stays on screen. Real dt is still consumed, so a hold always ends. */
    if (G.freeze > 0) { G.freeze -= dt; return; }
    G.t += dt; G.st += dt * 1000;
    /* Eased towards the target on the game clock, so the move is identical at any
       frame rate. Different rates in and out: see the note on zoomInMs. */
    {
      const L1z = CFG.levelOne;
      const ms = G.zoomWant > G.zoom ? L1z.zoomInMs : L1z.zoomOutMs;
      G.zoom += (G.zoomWant - G.zoom) * clamp(dt * 1000 / Math.max(1, ms) * 2.6, 0, 1);
      if (Math.abs(G.zoomWant - G.zoom) < 0.0008) G.zoom = G.zoomWant;
    }
    if (G.punchLen > 0) {
      G.punchT += dt;
      if (G.punchT >= G.punchLen) { G.punchLen = 0; G.punchAt = 0; }
      // snaps to full on the impact frame, then eases out
      else G.punchAt = G.punchAmp * Math.pow(1 - G.punchT / G.punchLen, 2.2);
    }
    if (G.shakeT > 0) {
      G.shakeT -= dt;
      // ease the amplitude down instead of holding full strength then cutting to zero
      G.shake = G.shakeT <= 0 ? 0 : G.shakeAmp * Math.pow(clamp(G.shakeT / G.shakeLen, 0, 1), 1.6);
    }
    if (G.quakeLen > 0 && G.quakeT < G.quakeLen) {
      G.quakeT += dt;
      G.quakeAt = G.quakeAmp * quakeEnv();
      // loose ice shaken off the path and snow jolted up around the feet. No flash:
      // firing the atmosphere pulse on this cadence was nine white flashes a second.
      G.quakeRoll = (G.quakeRoll || 0) + dt;
      if (G.quakeRoll > 0.09 && G.quakeAt > 1) {
        G.quakeRoll = 0;
        particles.chips(rand(60, CFG.W - 60), CFG.surfaceY - 4, 1, -120 - G.quakeAt * 14);
        particles.poof(CFG.mammothX - 34, CFG.surfaceY, 1, 0.42);   // a little puff behind each footfall
      }
    } else {
      G.quakeAt = 0;
    }
    if (G.hitFx > 0) G.hitFx = Math.max(0, G.hitFx - dt * 1.5);
    if (RUN_STATES.has(G.state) && G.speedFactor !== 1) G.speedFactor = 1;

    if (G.moving) {
      const v = CFG.runSpeed * G.speedFactor;
      G.worldX += v * dt; G.dist += v * dt;
    }
    const band = JOURNEY[G.state];
    if (band) {
      const u = clamp(G.st / band[2], 0, 1);
      G.progress = Math.max(G.progress, lerp(band[0], band[1], easeInOut(u)));
    }
    // Level 1 is six phases long, so its share of the journey advances with phases
    // repaired rather than on a per-state timer — otherwise the sky would sit still
    // through most of the game.
    if (G.phasesDone > 0 && G.phasesDone <= L1.phases.length) {
      G.progress = Math.max(G.progress, lerp(0.12, 0.82, G.phasesDone / L1.phases.length));
    }
    bgm.update(dt, G.progress);
    atmos.update(dt, G.progress);
    mammoth.update(dt, performance.now(), G.moving && G.speedFactor > 0.2, G.speedFactor);
    particles.update(dt);
    // the last argument is what stops one bump burning all three strikes while
    // the world is stopped behind the Ouch card — see ObstacleController.update
    obstacles.update(dt, G.worldX, mammoth, onCrystalHit, G.moving);
    updateInstruction(dt);
    updateTaps(dt);
    updateHints(dt);
    if (G.l1) updateL1(dt);
    updatePieces(dt);
    /* CULL CROSSINGS THAT ARE OFF SCREEN BEHIND US.

       Repaired crevasses were kept forever: layoutPhase only ever filtered out the
       UNrepaired ones, so by the end of a playthrough the ground held nine gaps and
       eleven plugs, and every frame walked all of them — the ditch, the water, the
       fill, the deck and the snow — to draw things a long way off the left edge.
       Measured over a full run: the arrays only ever climbed. Per-frame cost therefore
       grew with progress, which is the worst shape a cost curve can have.

       A crossing is dropped once its far lip is 600px behind the character, which is
       well off screen and past any chance of the run going back to it. */
    if (ground.gaps.length > 1) {
      const cutoff = G.worldX - 600;
      ground.gaps = ground.gaps.filter(gp => gp.x1 > cutoff || (G.gapsThisPhase || []).includes(gp));
    }

    switch (G.state) {
      case 'RUN_SEGMENT_1': if (G.st > T.run1) setState('JUMP_CHALLENGE_1'); break;
      case 'JUMP_CHALLENGE_1':
        if (obstacles.list.length && obstacles.list.every(o => o.passed)) setState('POST_JUMP_RUN_1');
        break;
      case 'POST_JUMP_RUN_1': if (G.st > T.postJump1) setState('GLACIER_BREAK_1'); break;
      case 'OBSTACLE_HIT':
        /* THE CRASH PLAYS OUT AND THE RUN RESUMES BY ITSELF. No panel, no button.

           It used to stop here and pop an "Ouch!" card with a TRY AGAIN button on
           it, and that is a worksheet interrupting a game: the player has already
           been told they crashed — by the impact, the stars and the character
           sitting down dazed — and being asked to confirm it adds a tap that says
           nothing. A runner recovers at the nearest checkpoint and carries on.

           The timeline is the ANIMATION length, not an arbitrary beat. The delivered
           knockout is 36 frames at CFG.sprite.koFps, so it needs 2.4s to play, and
           T.recover holds a little past that so the dazed sit is read rather than cut
           off. Recovering at T.knockout (1100ms) would have talked over the crash it
           is the consequence of — which is the same mistake the card made in the
           other direction.

           retryObstacle() is the checkpoint: it clears the rock that was walked
           into, restores movement and the jump control, and returns to G.hitReturn —
           the run state the player was actually in — so the run-up is identical to
           the first attempt and no progress is lost. */
        if (G.st > T.recover) retryObstacle();
        break;
      case 'GLACIER_BREAK_1': updateBreak(dt); break;
      case 'PHASE_INTRO':
        /* Read, then act. The panel owns the first beat by itself; when it slides
           away the ropes lower their chunks in, and only then is the phase playable. */
        /* The hold is re-armed to the reading time when the phase opens, so the
           sentence cannot vanish before introRead is up — the two used to be set
           independently and a short instructionHold blanked the panel while the stage
           was still supposed to be its own. */
        if (!G.dropReady && G.st > T.introRead) {
          G.dropReady = true;
          /* Send the BANNER away, not the instruction. The panel's visibility is
             gated on instrHold, and replayInstruction() reads G.instruction — so
             clearing the text made the hint button silently do nothing for the whole
             puzzle, which is the one thing that was supposed to make clearing the
             panel safe. */
          G.instrHold = 0;
          audio.pop();
        }
        if (G.dropReady && G.st > T.introRead + T.shapeDrop + 160) setState('PHASE_ACTIVE');
        break;

      case 'PHASE_WRONG': {
        // A phase state with no puzzle built is only reachable by forcing one, but it
        // used to throw on every frame from here down, which buries the real problem
        // under a flood of errors. Bail out to play instead.
        if (!G.l1) { setState('PHASE_RUN'); break; }
        // wait for the piece to actually tip off and fade, not a fixed duration —
        // the fall is real gravity, so it takes as long as it takes
        const gone = !G.l1.shapes.some(s => s.state === 'falling' && !s.correct && s.alpha > 0.02);
        if (gone || G.st > 2200) {
          G.l1.shapes = G.l1.shapes.filter(s => !(s.state === 'falling' && !s.correct));
          mammoth.setState('LOOK_DOWN');
          // the instruction comes back so the learner is reminded what they are after
          G.instruction = phaseCfg().instruction;
          G.instrLast = '';             // re-enter, so the chips re-pop with what is left
          armInstruction(T.instructionRemind);
          setState('PHASE_ACTIVE');
        }
        break;
      }

      case 'PHASE_SUCCESS': {
        if (!G.l1) { setState('PHASE_RUN'); break; }
        // The bridge closing over is what completes a repair, so wait for that
        // rather than for a fixed time — the chunk may have had to grind along the
        // ice before it reached the hole.
        const bridged = G.l1.filled &&
          (G.gapsThisPhase || []).every(g => !g.repaired || g.bridge >= 1);
        if ((bridged && G.st > 400) || G.st > 6000) {
          // more crevasses in this phase: straight back to play. The wedged chunk has
          // already left the shape list, so nothing is culled here.
          setState(G.l1.unfilled.length ? 'PHASE_ACTIVE' : 'PHASE_DONE');
        }
        break;
      }

      case 'PHASE_DONE':
        if (G.st > T.celebrate) {
          G.l1 = null; G.gapsThisPhase = null;
          G.phase++;
          G.hitCount = 0; G.phaseJumped = false;    // a fresh phase, a fresh slate
          if (G.phase >= L1.phases.length) setState('FINAL_RUN');   // every crossing repaired
          else setState('PHASE_RUN');
        }
        break;

      case 'PHASE_RUN': G.zoomWant = 1; {
        // a real stretch of adventure between puzzles, with a rock to clear before
        // the phases the config asks for — not before every one
        const p = L1.phases[G.phase];
        const dur = L1.runMs[G.phase] || 3000;
        if (L1.jumpBefore.includes(p.id) && !G.phaseJumped && G.st > 700) {
          G.phaseJumped = true;
          /* MORE ROCKS AS THE JOURNEY GOES ON — one before the first jump stretch, then
             two, then three, up to the cap. The run between puzzles gets harder as the
             puzzles do, so the curve is in the whole game rather than only in the
             thinking.

             DERIVED FROM WHICH STRETCH THIS IS, not counted up as they happen. A
             counter was tried and it inflates on a retry: retryObstacle() returns to
             PHASE_RUN, re-entering clears phaseJumped, and the stretch spawns again
             with the counter one higher — measured going 1, 2, 3, 4 inside a single
             phase, so failing a jump made the next attempt harder than the one that
             had just beaten you. jumpBefore.indexOf is the same number every time this
             stretch is entered, however many attempts it takes.

             Off jumpBefore rather than the phase number because it does not name every
             phase — off the phase index the count would skip values. */
          const stretch = L1.jumpBefore.indexOf(p.id);
          // starts at TWO: one rock is the tutorial's teaching case and is behind us
          const count = clamp(2 + Math.max(0, stretch), 2, L1.maxRocks || 4);
          obstacles.spawn(G.worldX, 2150, count);
          G.jumpPulse = true;
        }
        const clear = !obstacles.list.length || obstacles.list.every(o => o.passed);
        if (G.st > dur && clear) { G.jumpPulse = false; setState('GLACIER_BREAK_1'); }
        break;
      }
      case 'COMPLETE': {
        /* A LIGHT DRIZZLE OF CONFETTI for as long as the ending is up. The opening shower
           falls and is gone in three seconds, and the screen that stays is the one the
           player looks at — it should keep celebrating. Small handfuls, spaced out. */
        if (!reduced && G.st - (G.drizzleAt || 0) > 2200) { G.drizzleAt = G.st; particles.confetti(CFG.W, 34, true); }
        break;
      }
      case 'FINAL_RUN':
        G.zoomWant = 1;
        /* ARRIVES AT THE FRIEND. It used to end on a progress number, so the journey
           finished at an arbitrary moment with nothing on screen to mark it; stopping
           where the bear stands gives the ending a place.

           bearAt is set ONCE in onEnter, not here. It was assigned in this branch first
           and that can never arrive: the target is recomputed from the current worldX on
           every frame, so it stays a fixed distance ahead forever and the run home never
           ends. The progress test is kept as the fallback for a bearAt that was never
           set. */
        /* STOPS SHORT OF HIM, not level with him. 330 was the distance to the bear
           and the character stands at CFG.mammothX = 430 — so the run ended with the
           bear at screen x 327, a hundred pixels BEHIND the character: he had gone past
           his own friend. The gap has to clear the character position plus room for the
           two of them to stand side by side. */
        if (G.bearAt) { if (G.bearAt - G.worldX <= CFG.mammothX + 265) setState('COMPLETE'); }
        else if (G.progress >= 0.999) setState('COMPLETE');
        break;
    }
    pushHud();
  }


  function onCrystalHit(o, sx) {
    /* Failures are counted on G, not on the obstacle. retryObstacle() clears the
       obstacle list, so a per-obstacle counter reset every retry and the 3-strike
       safety valve could never fire — a learner who could not time the jump got the
       Try Again card over and over with no way through. On the third failure the
       rock crumbles and the run simply continues. */
    G.hitCount = (G.hitCount || 0) + 1;
    if (G.hitCount >= 3) {
      audio.bonk();
      particles.poof(CFG.mammothX + 50, CFG.surfaceY - 16, 8, 1.7);   // the crash: a big cloud
      particles.chips(sx, CFG.surfaceY - 20, 8, -240);
      shake(reduced ? 1.5 : 3, 220);
      hitStop(CFG.juice.stopHit * 0.7);
      punch(CFG.juice.punchHit * 0.8, 300, sx, CFG.surfaceY - 60);
      G.hitFx = 1;
      o.hits = 3; o.crumble = 0;          // stops colliding and crumbles away
      mammoth.setState('HURT');            // auto-returns to RUN while moving
      mammoth.knock = Math.max(mammoth.knock || 0, KO_KNOCK);
      return;                              // no panel, no stop: progress is guaranteed
    }
    audio.bonk();
    particles.poof(CFG.mammothX + 50, CFG.surfaceY - 16, 8, 1.7);   // the crash: a big cloud
    particles.chips(CFG.mammothX + 60, CFG.surfaceY - 40, 5, -200);
    shake(reduced ? 2 : 4, 260);
    // the hardest hold in the game: the character has physically stopped, and the
    // frame should stop with it
    hitStop(CFG.juice.stopHit);
    punch(CFG.juice.punchHit, 340, CFG.mammothX + 60, CFG.surfaceY - 60);
    if (!reduced) particles.ring(CFG.mammothX + 60, CFG.surfaceY - 70, 22, 170);
    mammoth.setState('KNOCKOUT');
    /* KNOCKED BACK CLEAR OF THE ROCK. The dazed sit leans back and stretches his feet
       about 130px forward of his running x, and the rock he hit stands right there — so
       he sat THROUGH it. The impact recoil was 34px, tuned for a bump he runs on from.
       A knockout throws him back far enough that the pose clears the stone, and the
       recoil holds while he is down (see the decay) and eases back as he gets up. */
    mammoth.knock = Math.max(mammoth.knock || 0, KO_KNOCK);
    mammoth.squash = 0.86;
    mammoth.jolt(reduced ? 0.45 : 1);      // the wince carries on shaking after the hit
    G.hitFx = 1;                      // drives the impact spark burst + warm vignette
    G.hitObstacle = o;
    G.hitReturn = RUN_STATES.has(G.state) ? G.state : 'RUN_SEGMENT_1';
    setState('OBSTACLE_HIT');
  }

  /** Hand control back with the obstacle on a fresh approach. Nothing is lost. */
  function retryObstacle() {
    // Clear the crystal that was walked into; re-entering the jump state spawns a
    // fresh one at the normal distance, so the run-up is identical to the first try.
    obstacles.reset();
    G.oops = false; G.hitFx = 0; G.hitObstacle = null;
    // OBSTACLE_HIT stopped the world and hid the jump button. The jump states do not
    // set these themselves — they inherit them from the run state — so restore them
    // here or the world stays frozen and the obstacle can never be passed.
    G.moving = true; G.jumpEnabled = true; G.speedFactor = 1;
    G.jumpPulse = true;               // re-teach the control on the retry
    mammoth.setState('RUN');
    setState(G.hitReturn || 'RUN_SEGMENT_1');
  }


  /* A hanging chunk of glacier, drawn in exactly the language of the shape glyph in
     the instruction panel (assets/ui/shapes/*.svg): one clean ice gradient, one navy
     outline, one white lip along the top edge.

     That match is the point. The panel says "cut the pentagon" and shows a pentagon
     drawn this way; the thing to cut is drawn the same way, so the two connect
     without the learner having to be told. The previous version had crystal facets,
     air bubbles and snow drips, which looked like ice but buried the one thing that
     actually matters here — the SILHOUETTE, which is the question being asked.

     Simple, high contrast, and lifted off the sky by its own shadow so it reads as
     an object you can reach for. `installed` adds the icicle fringe, which belongs
     on a chunk wedged under a bridge and would eat into a hanging chunk's outline. */
  /** rimMul scales the outline down when the chunk is drawn inside a magnifying
      transform, so a seated piece carries the same line weight on screen as a hanging
      one. Without it the seating scale of ~1.8 turned a 6px rim into an 11px slab. */
  function paintGlacierChunk(ctx, sh, installed, rimMul) {
    const pts = sh.pts;
    const b = polyBounds(pts);
    const scale = Math.max(1, b.w / 320);          // outline weight tracks the size
    const img = sh.art ? images['shape:' + sh.art.id] : null;

    ctx.save();
    ctx.lineJoin = 'round';
    ctx.lineCap = 'round';

    if (img) {
      /* THE DELIVERED BLOCK. Clipped to the ring as well as transformed onto it: the
         trace is a simplification of the painted edge, so a pixel or two of the
         picture can sit outside the polygon the game is using, and on a plug that has
         been swelled to span a crevasse a pixel becomes ten. Clipping means the
         silhouette on screen is exactly the silhouette being reasoned about. */
      const a = sh.art;
      ctx.save();
      if (!installed) {
        ctx.shadowColor = 'rgba(9,42,80,0.4)';
        ctx.shadowBlur = 20 * scale;
        ctx.shadowOffsetY = 9 * scale;
      }
      traceRing(ctx, pts);
      ctx.clip();
      ctx.translate(-a.off.x, -a.off.y);
      ctx.scale(a.scale, a.scale);
      ctx.rotate(a.rot);
      /* Drawn 2% OVER its box. The ring is a trace of a painted edge, so it can sit a
         fraction of a pixel outside the paint — and since the texture is clipped to the
         ring, that showed as a hairline of nothing between the picture and its rim.
         Over-drawing cannot spill, because the clip is the ring. */
      const F = 1.02;
      ctx.drawImage(img, a.box.x * F, a.box.y * F, a.box.w * F, a.box.h * F);
      ctx.restore();
    } else {
      /* No artwork for this shape: the drawn material, which is still what the basic
         PolygonFactory shapes get. */
      const g = ctx.createLinearGradient(0, b.y0, 0, b.y1);
      g.addColorStop(0, '#FBFEFF');
      g.addColorStop(0.20, '#DFF5FE');
      g.addColorStop(0.48, '#9BDCF6');
      g.addColorStop(0.78, '#41B0E4');
      g.addColorStop(1, '#1C6E9C');
      ctx.save();
      ctx.shadowColor = installed ? 'transparent' : 'rgba(9,42,80,0.4)';
      ctx.shadowBlur = installed ? 0 : 20 * scale;
      ctx.shadowOffsetY = installed ? 0 : 9 * scale;
      traceRing(ctx, pts);
      ctx.fillStyle = g;
      ctx.fill();
      ctx.restore();
    }

    /* A COLD RIM. The painted blocks carry their own bevel, so this is not an outline
       drawn around them — it is a thin frozen glow just inside the edge, which is what
       lifts a pale block off a pale sky and makes the silhouette read at a glance.
       An installed piece skips its UPPER edges: that edge has become the walking
       surface, and a line along it draws a dark seam through the snow packed over the
       join — the one line that has to be absent for a repair to read as whole. */
    const rim = (rimMul === undefined ? 1 : rimMul);
    ctx.save();
    /* A HANGING block gets a harder, darker rim than a seated one. It is pale ice on a
       pale sky and the silhouette IS the question being asked, so it has to be the
       crispest edge on screen; a seated plug is surrounded by fresh ice instead and a
       heavy line there would read as a seam through a finished repair. */
    ctx.strokeStyle = img ? (installed ? 'rgba(10,140,240,0.85)' : 'rgba(12,86,150,0.95)') : '#14496F';
    ctx.lineWidth = (img ? (installed ? 3.2 : 4.6) : 5.6) * scale * rim;
    if (!installed) {
      traceRing(ctx, pts);
      ctx.stroke();
    } else {
      for (let i = 0; i < pts.length; i++) {
        const a2 = pts[i], c2 = pts[(i + 1) % pts.length];
        if ((a2.y + c2.y) / 2 <= b.y0 + b.h * 0.34) continue;   // an upper edge: skip
        ctx.beginPath();
        ctx.moveTo(a2.x, a2.y); ctx.lineTo(c2.x, c2.y);
        ctx.stroke();
      }
    }
    ctx.restore();

    /* A frosted highlight along the top edges — for the DRAWN material only. The
       painted blocks carry their own bevel highlight, and adding this one on top of it
       put a thick pale bar across the upper edges, inset from them by 6% of the radius
       so it did not even follow the outline. Two highlights are worse than one. */
    if (!img) {
      ctx.strokeStyle = 'rgba(255,255,255,0.9)';
      ctx.lineWidth = 3 * scale * rim;
      for (let i = 0; i < pts.length; i++) {
        const a2 = pts[i], c2 = pts[(i + 1) % pts.length];
        if ((a2.y + c2.y) / 2 > b.y0 + b.h * 0.34) continue;      // not an upper edge
        ctx.beginPath();
        ctx.moveTo(a2.x * 0.94, a2.y * 0.94);
        ctx.lineTo(c2.x * 0.94, c2.y * 0.94);
        ctx.stroke();
      }
    }
    ctx.restore();

    /* NO ICICLES UNDER A WEDGED PIECE EITHER. Eight outlined white triangles used to
       hang off the underside of every plug, and they were the last of the sharp vector
       shapes in the crevasse — hard-edged, evenly spaced and stroked, they read as
       stuck-on decoration along the bottom of the learner's answer, which is the one
       silhouette in the game that has to stay clean.

       Nothing replaces them. The plug's own rim and the inner shadow where the fresh
       ice closes around it already give it an edge; it needs no fringe. */
  }

  /* FREEZING VAPOUR. A block of glacier ice hanging in the air is colder than the air,
     so it smokes: thin cold mist sliding off it and sinking. It is drawn OUTSIDE the
     ring — not clipped to it like the interior detail — because the whole point is
     that it escapes the silhouette, and it is kept faint and slow so it reads as
     atmosphere rather than as another thing to look at.

     Deterministic from the chunk's seed and the world clock, so it drifts rather than
     flickering, and it is skipped entirely under reduced motion. */
  function drawChunkVapour(ctx, sh) {
    if (reduced || !sh.art) return;
    const b = polyBounds(sh.pts);
    const n = 5;
    ctx.save();
    for (let i = 0; i < n; i++) {
      const ph = ((sh.seed || 1) * 0.37 + i * 0.71) % 1;
      // each wisp runs its own slow cycle: born at the block, sinks and fades
      const t = ((G.t * 0.22 + ph) % 1);
      const ease = t * t * (3 - 2 * t);
      const x = b.x0 + b.w * (0.14 + ((i * 0.29 + ph) % 1) * 0.72);
      const y = b.y1 - b.h * 0.1 + ease * b.h * 0.55;
      const r = b.w * (0.10 + 0.12 * ease);
      const a = Math.sin(t * Math.PI) * 0.16;
      if (a < 0.012) continue;
      const g = ctx.createRadialGradient(x, y, 0, x, y, r);
      g.addColorStop(0, 'rgba(238,251,255,' + a.toFixed(3) + ')');
      g.addColorStop(0.55, 'rgba(224,246,255,' + (a * 0.4).toFixed(3) + ')');
      g.addColorStop(1, 'rgba(224,246,255,0)');
      ctx.fillStyle = g;
      ctx.beginPath();
      ctx.ellipse(x, y, r, r * 0.52, 0, 0, 6.2832);
      ctx.fill();
    }
    ctx.restore();
  }

  /* ringBottomAt() was removed with the icicle fringe it existed to place: it found
     the lowest point of a ring at a given x, and nothing else ever asked. */

  /* THE HANGING RIG.
     Each option hangs on a rope that comes down out of the fog. Three things make it
     read as genuinely hung rather than as art pasted together:

     PIVOT.  A hanging object turns until its weight is under the attachment point,
             and a rope meets it at its HIGHEST point. So the pivot is the midpoint of
             the chunk's top edge, the chunk swings about that pivot, and the rope runs
             vertically down to it. Attaching to the chunk's centre made the rope look
             glued to whichever face happened to be nearest.

     SEAMS.  The rope art has ends. The top runs off the screen and is lost in the
             fog; the bottom is buried inside the chunk. No cut-off edge is visible.

     THE CUT. When the rope is cut it really parts: the lower length falls away with
             the chunk, and the stub left above snaps upward and swings out the
             tension. Nothing about the mechanic is legible if the rope simply
             disappears. */

  /** Sway of the whole rig, in radians, pivoting from the rig line off the top of the
      screen. Shared by the rope, the chunk and the hit test — all three derive their
      geometry from this one number, so they cannot disagree.

      ONE PENDULUM, IN PHASE, FOR EVERY OPTION. That is the whole design of it, and it
      is what separates natural hanging from mess.

      The original swing gave every chunk its OWN random phase and its own decaying
      amplitude. The result was a row where each block leaned a different way by a
      different amount at any moment — positions all over the place, no two ropes
      parallel — and it was removed for exactly that reason. Zero motion is tidy but
      dead: heavy blocks hanging on ropes should breathe.

      A single shared angle gives both. Every rope leans the same way at the same time,
      so the row stays perfectly even and no two blocks ever drift into each other's
      space: the spacing between neighbours is constant at every angle, because they are
      all rotated by the same amount about points on the same line. What moves is the
      whole rig together, like a mobile in a draught.

      Small and slow on purpose — about 1.3 degrees over a 4.5 second cycle, which
      carries the bottom of a block roughly 11px. Enough to be alive, far too little to
      make a shape harder to count or a rope harder to hit. */
  function rigSwing() {
    if (reduced) return 0;
    const CM = CFG.comedy;
    return Math.sin(G.t * CM.swayHz * 6.2832) * CM.swayRad;
  }

  /* Where the rope attaches: the TOP CENTRE of the chunk's rotated silhouette.
     Attaching to the highest VERTEX is what a real rope would do, but a vertex sits
     off to one side on most of these shapes, so each chunk hung from a different
     corner and the row looked haphazard. Top centre keeps every rope directly above
     its own slot and the rig reads as a tidy set. */
  function chunkPivot(sh) {
    const c = Math.cos(sh.baseRot), s = Math.sin(sh.baseRot);
    /* The midpoint of the chunk's TOP EDGE — the seated edge, since chunks are built
       already seated. It used to return the shape's horizontal centre at the shape's
       topmost y, and on a tilted chunk the topmost point is a corner: the rope ended
       above the middle of the top edge with nothing there, and a corner poked up
       beside it, so every option looked as if it were dangling off one shoulder. */
    let m = null, best = Infinity;
    const pts = sh.pts || [];
    for (let i = 0; i < pts.length; i++) {
      const a = pts[i], b = pts[(i + 1) % pts.length];
      const my = (a.y + b.y) / 2;
      if (my < best) { best = my; m = { x: (a.x + b.x) / 2, y: my }; }
    }
    if (!m) return { x: 0, y: -SHAPE_H / 2 };
    return { x: m.x * c - m.y * s, y: m.x * s + m.y * c };
  }

  /** Where the rope leaves the anchor and where it meets the chunk. */
  /* WHERE THE ROPE IS, AFTER THE SWAY — and the hit test uses this same function, so
     what looks cuttable is cuttable at every angle.

     The rig pivots from ROPE_TOP, off the top of the screen, and the rope and the chunk
     both hang off that one rotation. So the rope's lower end swings by (length x angle)
     and its upper end does not move at all, which is what a rope on a pendulum does.

     It used to return a dead vertical line at anchorX regardless of the swing, because
     the chunk was rotated about its own attachment point instead — the block leaned
     while the rope it hung from stayed bolt upright. That reads as a block pinned to a
     stick, not hung from a rope. */
  function ropeSpan(sh) {
    const piv = sh.pivot || chunkPivot(sh);
    const a = rigSwing();
    const len = (sh.y + piv.y) - ROPE_TOP;
    return {
      x0: sh.anchorX, y0: ROPE_TOP,
      x1: sh.anchorX + Math.sin(a) * len,
      y1: ROPE_TOP + Math.cos(a) * len
    };
  }

  /* THE FOG the ropes come out of.

     This replaces an ice shelf with an icicle fringe. The shelf was the second largest
     thing on screen for the whole puzzle and it was hard scenery competing with the
     shapes; fog gives the ropes somewhere to come from without drawing the eye.

     IT IS FRACTAL NOISE, and the two attempts before it say why. A full-width linear
     gradient read as exactly what it was — a rectangle. Replacing that with a few
     dozen big soft ellipses read as horizontal bands, because a flat wide ellipse IS a
     band and no amount of stacking them hides the primitive.

     Fog has no primitive. It is turbulent at every scale at once: thick here, clear a
     hundred pixels along, wispy at the edges of both. That is what fractal noise is, so
     the alpha of this layer is four octaves of tileable value noise, contrast-stretched
     so there are genuinely clear patches and genuinely thick ones, multiplied by a
     vertical falloff.

     BUILT SMALL AND SCALED UP. The noise field is computed at a sixth of the size and
     then drawn up with smoothing — which costs a fortieth of the pixels and, more
     usefully, does the softening for free. It is cached per sky colour, so the whole
     thing is computed a handful of times over a run.

     THREE LAYERS DRIFTING AT DIFFERENT SPEEDS is what stops it reading as a texture
     pinned to the screen. Each is a strip twice the stage wide whose noise wraps in x,
     so it can be offset forever without a seam.

     TINTED BY THE SKY. A fixed white bank over a violet dusk is the exact fault that
     had generated clouds deleted from this game once already. */
  let fogArt = null;

  /** Tileable fractal value noise as an alpha field, in the sky's own colour. */
  function paintFogLayer(H, salt, cols, gain) {
    const W2 = CFG.W * 2;
    const SS = 6;
    const w = Math.max(16, Math.round(W2 / SS)), h = Math.max(6, Math.round(H / SS));
    const src = offscreen(w, h);
    const g = src.getContext('2d');
    const img = g.createImageData(w, h);

    /* Integer hash on a lattice, stable and repeatable. Every multiply goes through
       Math.imul: the classic shader-style version of this squares and cubes the seed,
       which in JS leaves float precision behind and — measured — returned exactly zero
       for 7979 of 8000 lattice points. A flat field is a flat fog, which is to say no
       fog at all. This one measures mean 0.50, sd 0.29 over the same points. */
    const hash = (ix, iy, o) => {
      let n = Math.imul(ix, 374761393) + Math.imul(iy, 668265263) +
              Math.imul(o + 1, 2246822519) + Math.imul(salt, 3266489917);
      n = Math.imul(n ^ (n >>> 13), 1274126177);
      return ((n ^ (n >>> 16)) >>> 0) / 4294967296;
    };
    const smooth = t => t * t * (3 - 2 * t);
    const octave = (u, v, c, r, o) => {
      const x = u * c, y = v * r;
      const x0 = Math.floor(x), y0 = Math.floor(y);
      const fx = smooth(x - x0), fy = smooth(y - y0);
      const wrap = i => ((i % c) + c) % c;      // wraps in x, so the strip tiles
      const a = hash(wrap(x0), y0, o), b = hash(wrap(x0 + 1), y0, o);
      const d = hash(wrap(x0), y0 + 1, o), e = hash(wrap(x0 + 1), y0 + 1, o);
      return (a * (1 - fx) + b * fx) * (1 - fy) + (d * (1 - fx) + e * fx) * fy;
    };

    for (let y = 0; y < h; y++) {
      const v = y / h;
      // thickest along the top, gone before the chunks, with a soft shoulder
      const fall = clamp(1 - Math.pow(clamp(v / 0.94, 0, 1), 1.6), 0, 1);
      for (let x = 0; x < w; x++) {
        const u = x / w;
        let n = 0, amp = 1, tot = 0, c = cols, r = 2;
        for (let o = 0; o < 4; o++) {
          n += octave(u, v, c, r, o) * amp;
          tot += amp; amp *= 0.52; c *= 2; r *= 2;
        }
        n /= tot;
        // contrast: fog is patchy, not a uniform veil
        n = clamp((n - 0.30) * 2.1, 0, 1);
        const i = (y * w + x) * 4;
        // WHITE, and the alpha carries the fog. The colour is applied later by
        // tintFogLayer, so this field is built once and reused for every sky.
        img.data[i] = 255; img.data[i + 1] = 255; img.data[i + 2] = 255;
        img.data[i + 3] = Math.round(clamp(n * fall * gain, 0, 1) * 255);
      }
    }
    g.putImageData(img, 0, 0);

    const out = offscreen(W2, H);
    const g2 = out.getContext('2d');
    g2.imageSmoothingEnabled = true;
    g2.imageSmoothingQuality = 'high';
    g2.drawImage(src, 0, 0, W2, H);
    return out;
  }

  /* THE NOISE ONCE, THE COLOUR CHEAPLY.

     This used to be one cache keyed on the sky colour, so a colour change rebuilt the
     whole thing — three 4-octave noise fields, three putImageData calls and three
     3840x195 canvases, about 8.6MB and 50-100ms of blocked main thread. And the sky
     CROSSFADES: bgm.light() interpolates for 1.5s, so with the colour quantised to 4
     bits a channel the key changed three or four times during every crossing, each one
     a visible hitch in the middle of the run.

     The fix is that the noise has nothing to do with the colour. It is generated once,
     white, with the fog in the alpha — keyed on the band height alone, which never
     changes at runtime. Re-tinting is then a blit plus a `source-in` fill per layer:
     two compositing operations instead of a per-pixel loop, so a crossfade costs
     essentially nothing and the look is identical. */
  let fogNoise = null;
  function fogMasks(H) {
    if (fogNoise && fogNoise.H === H) return fogNoise.masks;
    fogNoise = {
      H,
      // coarse and thick, then finer and fainter over the top of it
      masks: [
        { art: paintFogLayer(H, 1, 5, 0.95), sp: 4 },
        { art: paintFogLayer(H, 2, 9, 0.70), sp: 9 },
        { art: paintFogLayer(H, 3, 17, 0.45), sp: 17 }
      ]
    };
    return fogNoise.masks;
  }
  /** One mask, washed in the sky's own colour. */
  function tintFogLayer(mask, H, rgb) {
    const W2 = CFG.W * 2;
    const out = offscreen(W2, H);
    const g = out.getContext('2d');
    g.drawImage(mask, 0, 0);
    g.globalCompositeOperation = 'source-in';
    // the same wash the per-pixel version applied: most of the way to white
    const col = rgb.map(v => Math.round(v + (255 - v) * 0.72));
    g.fillStyle = `rgb(${col[0]},${col[1]},${col[2]})`;
    g.fillRect(0, 0, W2, H);
    return out;
  }

  function drawFog(ctx) {
    const H = Math.round(L1.rigY * 1.3);
    const L = bgm ? bgm.light() : { c: [255, 255, 255], dim: 1 };
    const key = L.c.map(v => (v | 0) >> 4).join('.') + '/' + H;
    if (!fogArt || fogArt.key !== key) {
      const masks = fogMasks(H);
      fogArt = {
        key,
        layers: masks.map(m => ({ art: tintFogLayer(m.art, H, L.c), sp: m.sp }))
      };
    }
    const W2 = CFG.W * 2;
    ctx.save();
    ctx.globalAlpha = clamp(0.5 + L.dim * 0.5, 0, 1);
    for (const l of fogArt.layers) {
      const ox = -(((reduced ? 0 : G.t) * l.sp) % W2);
      ctx.drawImage(l.art, Math.round(ox), 0);
      ctx.drawImage(l.art, Math.round(ox + W2), 0);
    }
    ctx.restore();
  }

  /* Where every rope starts: off the top of the screen, so the frame edge cuts it and
     it never has a visible end. That is what lets the fog stay a light band instead of
     having to be opaque enough to hide a rope's tip. */
  const ROPE_TOP = -24;

  function drawRope(ctx, sh) {
    const img = images.rope;
    const s = ropeSpan(sh);
    /* Over-length at both ends: the top runs off the screen behind the fog, and the
       bottom is buried inside the chunk. The lower overlap is generous because the
       chunk is MOVING while it lowers in — too tight and a gap flickers open between
       the rope and the chunk it is carrying. */
    /* THE ROPE HANGS FROM THE BLOCK, NOT DOWN TO IT — and that is the fix for a real
       bug rather than a preference.

       It used to be drawn from the rig line DOWN to the block's attachment point, with
       an early return when that length came out below 4px. But a chunk starts its drop
       at y -220 while the rig line is at -24, so for the first two thirds of the descent
       the block is ABOVE the point it hangs from and the length is negative:

           block y -220  ->  rope length -313   no rope drawn
           block y    0  ->  rope length  -93   no rope drawn
           block y   93  ->  rope length    0   no rope drawn
           block y  200  ->  rope length  107   rope appears

       So the block sailed in from the top of the screen with nothing attached to it, and
       the rope only appeared once it had dropped past the rig — the two arrived as
       separate objects.

       Drawing it the other way round makes that impossible. The rope's BOTTOM is pinned
       to the attachment point and it runs upward, along the sway direction, for a fixed
       length that always reaches off the top of the frame. It is therefore attached on
       every frame of the drop, at every angle, and there is no length at which it can
       fail to be drawn. The top end is never seen: the fog is drawn over it, and the
       frame edge cuts it before that. */
    const w = Math.max(11, (sh.w || SHAPE_W) * 0.055);
    const UP = 1400;                       // always past the top of the frame
    const overlap = Math.max(30, (sh.h || SHAPE_H) * 0.3);
    ctx.save();
    ctx.translate(s.x1, s.y1);             // the attachment point on the block
    ctx.rotate(rigSwing());
    if (img) ctx.drawImage(img, Math.round(-w / 2), Math.round(-UP), Math.round(w), Math.round(UP + overlap));
    else { ctx.fillStyle = 'rgba(228,246,255,0.95)'; ctx.fillRect(-w / 2, -UP, w, UP + overlap); }
    ctx.restore();
  }

  /* The stub left hanging on the anchor after a cut: it snaps up from the release of
     tension, then swings the energy out. */
  function drawRopeStub(ctx, st) {
    const img = images.rope;
    const e = clamp(st.t / 0.9, 0, 1);
    // snaps up as the tension goes, then keeps a visible dangling length
    const len = lerp(st.len, st.len * 0.42, easeOut(clamp(st.t / 0.22, 0, 1)));
    const swing = Math.sin(st.t * 13) * 0.22 * (1 - e);
    const w = Math.max(11, st.w * 0.055);
    /* It still SWINGS about the rig line — pivoting from the top of the screen would
       throw the tip sideways by three times as much — but it is drawn from off-screen
       upward of that, so the fog covers where it comes from. */
    const over = L1.rigY - ROPE_TOP;
    ctx.save();
    ctx.translate(st.x, L1.rigY);
    ctx.rotate(swing);
    if (img) ctx.drawImage(img, -w / 2, -over, w, len + over);
    else { ctx.fillStyle = 'rgba(228,246,255,0.95)'; ctx.fillRect(-w / 2, -over, w, len + over); }
    ctx.restore();
  }

  /* MAKING THE OPTIONS THE THING YOU LOOK AT.

     They were reported as not catching the eye, and the frames bear that out: pale ice
     blocks against a pale sky, with only a drop shadow separating them. Nothing on
     screen said "these are the interactive objects" — which for the one thing the
     learner has to act on is the most expensive possible omission.

     Three additions, all of them applied IDENTICALLY to every option so none of them
     can hint at which is the answer:

       halo    a warm-white glow behind each block, so it is the brightest thing in the
               upper half of the screen and lifts off the sky whatever the sky is doing
       sheen   a slow specular band sweeping down the ice face, clipped to the ring —
               the standard "this is glossy and it is live" cue
       breath  a shared slow pulse on the halo, so the whole row reads as waiting for you

     The sweep's phase is driven by the shared clock and NOT by the shape's own seed, on
     purpose: staggered timing would make one block catch the eye before its neighbours. */
  function drawChunkHalo(ctx, sh) {
    const b = polyBounds(sh.pts);
    const r = Math.max(b.w, b.h) * 1.05;
    // one shared breath across the whole row
    const pulse = 0.86 + 0.14 * Math.sin(G.t * 1.9);
    ctx.save();
    /* WARM, NOT COOL — and that is the whole reason this works now.

       The first version glowed pale blue. Pale blue ice, on a pale blue halo, against a
       pale blue sky: it added light and no separation, and the options still read as
       part of the background. The blocks are the one thing on screen the learner has to
       act on, so they have to be the one thing that is obviously not scenery.

       A WARM halo behind a COOL object is the strongest separation available without
       touching the artwork — the hue itself says "this is lit, this is foreground, this
       is the thing" — and it is already the game's accent, the amber the buttons use.
       Two passes: a wide gold bloom, then a tight near-white core that hugs the
       silhouette so the block's own edge stays crisp against it. */
    const wide = ctx.createRadialGradient(0, 0, r * 0.28, 0, 0, r * pulse);
    wide.addColorStop(0, 'rgba(255,238,186,0.62)');
    wide.addColorStop(0.42, 'rgba(255,206,104,0.36)');
    wide.addColorStop(0.72, 'rgba(255,186,72,0.14)');
    wide.addColorStop(1, 'rgba(255,176,48,0)');
    ctx.fillStyle = wide;
    ctx.beginPath(); ctx.arc(0, 0, r * pulse, 0, 6.2832); ctx.fill();

    const core = ctx.createRadialGradient(0, 0, r * 0.1, 0, 0, r * 0.62);
    core.addColorStop(0, 'rgba(255,252,238,0.72)');
    core.addColorStop(1, 'rgba(255,244,206,0)');
    ctx.fillStyle = core;
    ctx.beginPath(); ctx.arc(0, 0, r * 0.62, 0, 6.2832); ctx.fill();
    ctx.restore();
  }

  /** A specular band sweeping down the ice, clipped to the block's own outline. */
  function drawChunkSheen(ctx, sh) {
    if (reduced) return;
    const b = polyBounds(sh.pts);
    // 0..1 down the face, with a long pause between passes so it reads as a glint
    const cycle = 3.4;
    const u = (G.t % cycle) / cycle;
    if (u > 0.42) return;
    const p = u / 0.42;
    const band = b.h * 0.42;
    const y = lerp(b.y0 - band, b.y1 + band, p);
    ctx.save();
    traceRing(ctx, sh.pts);
    ctx.clip();
    const g = ctx.createLinearGradient(0, y - band / 2, 0, y + band / 2);
    g.addColorStop(0, 'rgba(255,255,255,0)');
    g.addColorStop(0.5, 'rgba(255,255,255,0.42)');
    g.addColorStop(1, 'rgba(255,255,255,0)');
    ctx.fillStyle = g;
    ctx.fillRect(b.x0 - 10, y - band / 2, b.w + 20, band);
    ctx.restore();
  }

  /* `bare` is the focus render: ropes and blocks only. The fog is a full-width band and
     the halo and vapour are soft light, and all three have alpha — on a canvas that is
     glowed by its alpha they would have lit the whole top of the screen. */
  function drawHangingShapes(ctx, belowSurface, bare) {
    const L = G.l1; if (!L) return;
    if (!belowSurface) {
      /* Ropes FIRST, fog over them. Every rope runs off the top of the screen, so
         what hides its upper end — and the blunt cut end of a stub — is the fog
         itself rather than a piece of scenery drawn on top of it. */
      for (const st of (L.stubs || [])) drawRopeStub(ctx, st);
      for (const sh of L.shapes) if (sh.state === 'hang') drawRope(ctx, sh);
      if (!bare) drawFog(ctx);
    }
    for (const sh of L.shapes) {
      const isBelow = sh.y > CFG.surfaceY - SHAPE_H * 0.4;
      if (isBelow !== belowSurface) continue;
      const piv = sh.pivot || chunkPivot(sh);
      ctx.save();
      ctx.globalAlpha = sh.alpha;
      if (isBelow) ctx.filter = `brightness(${(0.84 - (sh.submerged || 0) * 0.42).toFixed(2)})`;
      if (sh.state === 'hang') {
        /* Swing about the attachment point, the way a hung object does — plus two
           cartoon overlays, BOTH of them applied about that same point so the block
           stays on the end of its rope:

             jiggle  a swipe passed close and missed. A decaying swing, so the miss
                     has a visible consequence without saying anything about which
                     rope was the right one.
             land    it has just arrived and the rope has gone taut: a squash that
                     recovers, which is where the weight reads.

           Neither moves the HIT TEST, which is against ropeSpan() — a wobbling block
           cannot make a rope harder to cut. */
        /* HUNG OFF THE SAME PENDULUM AS ITS ROPE. Rotate about the rig line, travel
           down the rope to the attachment point, then place the block by its pivot. The
           block therefore stays joined to the rope end at every angle, and because every
           option shares one angle the row's spacing never changes. baseRot is 0 for
           every phase, so the block itself is axis-aligned as drawn — it is carried by
           the sway, not tilted independently by it. */
        const len = (sh.y + piv.y) - ROPE_TOP;
        ctx.translate(sh.anchorX, ROPE_TOP);
        ctx.rotate(rigSwing());
        ctx.translate(0, len);
        ctx.translate(-piv.x, -piv.y);
      } else {
        ctx.translate(sh.x, sh.y);
        ctx.rotate(sh.rot);
        ctx.scale(sh.scale, sh.scale);
      }
      // the halo goes BEHIND the block, so it reads as light coming off it
      if (sh.state === 'hang' && !bare) drawChunkHalo(ctx, sh);
      paintGlacierChunk(ctx, sh, false);
      if (sh.state === 'hang') { drawChunkSheen(ctx, sh); if (!bare) drawChunkVapour(ctx, sh); }
      // the short tail of rope a cut chunk carries down with it
      if (sh.tail > 0 && sh.state !== 'hang') {
        const img = images.rope;
        const w = Math.max(11, (sh.w || SHAPE_W) * 0.055);
        ctx.save();
        ctx.translate(piv.x, piv.y);
        if (img) ctx.drawImage(img, -w / 2, -sh.tail, w, sh.tail + 10);
        ctx.restore();
      }
      ctx.restore();
      ctx.filter = 'none';
    }
    ctx.globalAlpha = 1;
  }
  // Contextual "swipe to cut" demo — drawn in neutral space between two options so it
  // teaches the gesture without pointing at an answer.
  /* THE CUT LINE — where a swipe has to cross, marked on every rope.

     This is what replaced the scissors cursor, and it says more than the scissors
     could. A cursor is in one place at a time, it exists only for a mouse, and it
     had to be gated by hand to the one state where cutting is possible. A dotted
     line is on every rope at once, works for a finger, and carries the one thing
     the scissors never said: cut ACROSS the rope, not along it.

     MARCHING, because a still dotted line is decoration and a moving one is an
     instruction — the dashes travel the way the hand has to travel. The march runs
     off the game clock, so a hit-stop holds it with everything else on screen.

     IT CANNOT LEAK THE ANSWER. Every hanging rope gets an identical line, so the
     marks distinguish nothing — the rule updateHints() is built on.

     A DARK KEYLINE UNDER A BRIGHT ONE, for the same reason the scissors had both:
     the ropes come out of pale fog and cross the near-black rock band, and no one
     colour holds against both ends of that range. */
  function drawCutGuide(ctx) {
    const L = G.l1;
    if (!L || G.state !== 'PHASE_ACTIVE') return;
    /* DASHES, WITH SQUARE ENDS. A dashed line is the universal "cut here" mark, and it
       has to be drawn with butt caps: round caps add a full line-width to every dash, so
       [17, 14] at lw 11 rendered as 28px capsules with 3px gaps — a row of grey pills
       that read as a UI control sitting on the rope. Square ends keep the dashes the
       length they were given and the gaps open. Dots were tried in between and asked
       to be dashes. */
    const DASH = [14, 11];
    const march = -(G.t * 84) % (DASH[0] + DASH[1]);
    /* A HINT, NOT A HEADLINE. Thin gold dashes with a soft glow of their own colour, no
       dark rim: the first version was 11px dashes inside a 14px navy halo, and it sat on
       the rope like a piece of signage — heavier than the rope it was marking. A hint
       should be the quietest thing that still reads. The glow is what keeps a 4px line
       visible against both the pale sky and the dark rock band, which the rim used to do
       with weight; the breath keeps it alive on a still frame. */
    const breathe = 0.5 + 0.28 * Math.sin(G.t * 3.6);
    for (const sh of L.shapes) {
      if (sh.state !== 'hang') continue;
      const s = ropeSpan(sh);
      /* 60px ABOVE THE BLOCK, which is EXACTLY where the tutorial puts its hand
         (Tutorial.ropeBox) — so the hand sweeps along this line rather than somewhere
         else on the same rope. This is also the most reachable stretch of rope and the
         clearest — the fog is above it and the block below. */
      const top = sh.y - (sh.h || SHAPE_H) / 2;
      if (top < 60) continue;                // rope still off the top: nothing to mark
      const cy = Math.max(ROPE_TOP + 70, top - 60);
      /* x INTERPOLATED ALONG THE ROPE at that height, not the span midpoint: the rope
         sways, and the midpoint is only on it when the mark is halfway down. */
      const tt = (cy - ROPE_TOP) / Math.max(1, s.y1 - ROPE_TOP);
      const cx = s.x0 + (s.x1 - s.x0) * tt;
      const perp = Math.atan2(s.y1 - ROPE_TOP, s.x1 - s.x0) + Math.PI / 2;
      const half = Math.max(64, (sh.w || SHAPE_W) * 0.36);
      ctx.save();
      ctx.translate(cx, cy);
      ctx.rotate(perp);
      ctx.globalAlpha = breathe;
      ctx.lineCap = 'butt';
      ctx.setLineDash(DASH);
      ctx.lineDashOffset = march;
      ctx.shadowColor = 'rgba(255,196,60,0.95)';
      ctx.shadowBlur = 12;
      ctx.strokeStyle = '#FFD24A'; ctx.lineWidth = 4;
      ctx.beginPath(); ctx.moveTo(-half, 0); ctx.lineTo(half, 0); ctx.stroke();
      // a second pass with no blur so the dash itself stays crisp inside its glow
      ctx.shadowBlur = 0;
      ctx.strokeStyle = '#FFE58A'; ctx.lineWidth = 2;
      ctx.beginPath(); ctx.moveTo(-half, 0); ctx.lineTo(half, 0); ctx.stroke();
      ctx.setLineDash([]);
      ctx.restore();
    }
  }
  function drawCutDemo(ctx) {
    const L = G.l1;
    if (!L || !L.demo || L.demo.done || G.attempts > 0 || G.state !== 'PHASE_ACTIVE') return;
    if (L.shapes.length < 2) return;
    /* IT HAS TO CROSS A ROPE.

       It used to be centred BETWEEN two ropes and reach 100px each way. Measured at
       the sizes the game draws, the ropes in a three-option phase are about 330px
       apart, so a stroke ±100 from the midpoint stopped 65px short of either one: the
       tutorial's only job is to teach the gesture, and what it demonstrated was a
       swipe through empty space, which cuts nothing.

       It is now on the MIDDLE rope and long enough to cross it — the same placement
       the idle hand hint already uses, and for the same reason: the middle is a
       POSITION, not an answer. It says "ropes are cut like this", never "cut this
       one". */
    const mid = L.shapes[Math.floor(L.shapes.length / 2)];
    const cx = mid.anchorX;
    const cy = (L1.rigY + L1.optionY - (mid.h || SHAPE_H) / 2) / 2;
    const cycle = 0.95, u = (L.demo.t % cycle) / cycle;
    const fade = clamp(Math.sin(Math.min(u, 1) * Math.PI) * 1.6, 0, 1) * clamp(2 - L.demo.t / 1.1, 0, 1);
    if (fade <= 0.01) return;
    // long enough to start clear of the rope and finish clear the other side
    const x0 = cx - 132, x1 = cx + 132;
    const head = lerp(x0, x1, clamp(u * 1.25, 0, 1));
    ctx.save();
    ctx.globalAlpha = fade * 0.95;
    ctx.lineCap = 'round';
    const tr = ctx.createLinearGradient(x0, cy - 18, head, cy + 18);
    tr.addColorStop(0, 'rgba(255,255,255,0)');
    tr.addColorStop(1, 'rgba(255,255,255,0.95)');
    ctx.strokeStyle = tr; ctx.lineWidth = 8;
    ctx.beginPath(); ctx.moveTo(x0, cy - 18); ctx.lineTo(head, cy + 18); ctx.stroke();
    ctx.fillStyle = '#FFFFFF';
    ctx.beginPath(); ctx.arc(head, cy - 18 + (head - x0) / (x1 - x0) * 36, 11, 0, 6.2832); ctx.fill();
    ctx.strokeStyle = 'rgba(45,130,181,0.65)'; ctx.lineWidth = 3;
    ctx.beginPath(); ctx.arc(head, cy - 18 + (head - x0) / (x1 - x0) * 36, 11, 0, 6.2832); ctx.stroke();
    ctx.restore();
  }

  function drawSlash(ctx) {
    if (!slash || slash.pts.length < 2) return;
    ctx.save();
    ctx.lineCap = 'round'; ctx.lineJoin = 'round';
    ctx.strokeStyle = 'rgba(255,255,255,0.85)'; ctx.lineWidth = 9;
    ctx.beginPath();
    slash.pts.forEach((p, i) => i ? ctx.lineTo(p.x, p.y) : ctx.moveTo(p.x, p.y));
    ctx.stroke();
    ctx.strokeStyle = 'rgba(104,201,238,0.8)'; ctx.lineWidth = 3; ctx.stroke();
    ctx.restore();
  }

  /* EVERY TOUCH IS ACKNOWLEDGED.

     A ring that expands out of wherever the player put their finger, on every single
     pointerdown, in every state. It is the cheapest possible answer to the commonest
     complaint about a touch game — "I tapped and nothing happened" — and it is
     honest, because it says only "I saw that", never "that was right".

     Deliberately state-blind: it fires while running, while the ice is breaking and
     during a puzzle. A feedback that appears only when the game happens to want input
     teaches the player to distrust it. */
  const taps = [];
  function addTap(x, y) {
    taps.push({ x, y, t: 0 });
    if (taps.length > 6) taps.shift();
  }
  function updateTaps(dt) {
    for (const t of taps) t.t += dt;
    for (let i = taps.length - 1; i >= 0; i--) if (taps[i].t > 0.5) taps.splice(i, 1);
  }
  function drawTaps(ctx) {
    for (const t of taps) {
      const e = clamp(t.t / 0.5, 0, 1);
      const r = lerp(14, 74, easeOut(e));
      ctx.save();
      ctx.globalAlpha = (1 - e) * 0.55;
      ctx.strokeStyle = '#FFFFFF';
      ctx.lineWidth = lerp(7, 1.5, e);
      ctx.beginPath(); ctx.arc(t.x, t.y, r, 0, 6.2832); ctx.stroke();
      ctx.restore();
    }
    ctx.globalAlpha = 1;
  }
  /* THE CROSSING.
     A chunk sitting in a hole is just a chunk sitting in a hole. What makes it a
     repair is an arch: the chunk wedges in the middle of the crevasse as the
     keystone, and a snow-and-ice deck grows out from BOTH broken lips until it meets
     over the top of it. The deck is one continuous flat surface at the snow line —
     that is the thing the character runs across — and its underside dips to sit on
     the chunk, with icicles hanging beneath. `g.bridge` runs 0 -> 1 and drives the
     whole thing, so the learner watches the path knit itself back together over
     their answer.

     Earlier this drew two ramps that passed IN FRONT of the chunk and a full-width
     translucent band across the chasm, which read as a shape suspended in a hole
     behind a ghost bar — no crossing at all. */
  /* There is no deck and there are no shoulders any more. Both existed only to
     imitate the path across the gap with canvas gradients, and neither could: the
     path is bitmap art. The mend is cut from the path's own tiles instead, so there
     is nothing left for a deck to do. */

  /** The seated piece's outline in SCREEN space, so it can be used as a clip for the
      path pixels that fill it. */
  function pieceSilhouette(p, cx, cy, k, roll) {
    const c = Math.cos(roll), sn = Math.sin(roll);
    const path = new Path2D();
    p.pts.forEach((q, i) => {
      const x = cx + (q.x * c - q.y * sn) * k;
      const y = cy + (q.x * sn + q.y * c) * k;
      if (i === 0) path.moveTo(x, y); else path.lineTo(x, y);
    });
    path.closePath();
    return path;
  }

  /* The mend itself. */
  function drawKeystone(ctx, g, p) {
    if (!p) return;
    /* It SWELLS to span its slot. A chunk dropped into a chasm reads as a small block
       in a big hole however well the bridge is drawn — the answer has to visibly
       become the crossing. A little overshoot on the way makes it read as settling in
       rather than as a sprite being rescaled. */
    /* READ ONLY. `grow` and `impact` are advanced in updatePieces() on the game clock.
       They used to be stepped HERE, by a fixed 0.055 and 0.045 per RENDERED FRAME —
       so the plug swelled into place two and a half times faster on a 144Hz display
       than on a 60Hz one, and slower still on a machine dropping frames. The repo
       already holds this standard everywhere else ("spray is time-based, not
       per-frame, so a 144Hz display gets the same amount as a 60Hz one"); the mend —
       the single most important animation in the game — was the one place it was not
       being kept. */
    if (p.grow === undefined) p.grow = 0;
    const e = easeOut(p.grow);
    /* NO SCALE RAMP. This used to lerp from 1 to p.fit across the grow, which is
       literally an animation of the learner's answer changing size — the thing that was
       reported. The plug is at its final scale on frame one; `e` now only drives the
       settling overshoot (a 3.5% swell that peaks halfway and returns), the frost bloom
       and the roll back to square. */
    const k = (p.fit || 1) * (1 + Math.sin(e * Math.PI) * 0.035);
    const sq = p.impact ? p.impact : 0;
    // it rolls from the angle it was cut at into the angle it seats at
    const roll = lerp(p.rot0 || 0, 0, e);
    /* Positioned by its TOP EDGE, not its centre, so the walking surface lands on
       the snow line at every frame of the growth and for every shape — a triangle
       and a hexagon have their flat side different distances from the bbox centre.
       SEAT_INSET tucks that edge just under the snow band laid over it. */
    /* How far the plug's top edge sits BELOW the snow line. It was 2 — the top edge
       was the walking surface, because the plug spanned the gap. Now the deck is the
       walking surface and the plug hangs under it, so it is tucked down far enough for
       the deck to visibly rest on it. */
    const SEAT_INSET = PLUG_SINK;
    const kk = Math.max(k, 0.001);
    const cx = p.cx - G.worldX;
    const cy = p.topLocal !== undefined
      ? CFG.surfaceY + SEAT_INSET - p.topLocal * kk
      : p.cy;

    const gx0 = g.x0 - G.worldX, gx1 = g.x1 - G.worldX;
    const waterY = CFG.surfaceY + CFG.levelOne.waterDepth;
    const sil = pieceSilhouette(p, cx, cy, kk, roll);

    ctx.save();
    /* ONE LOOSE BOUND, and no silhouette clipping at all.

       There used to be two clips here: the slot's span, and the crevasse cavity. Both
       existed to contain a plug that had been grown far bigger than the hole it was
       in — and both therefore CUT THE SHAPE. That is what turned phase 1's triangle
       into a trapezoid and phase 6's pentagons into slabs.

       The plug is now sized to fit the cavity whole (see lockIn), so there is nothing
       to contain. What is left is a generous rectangle that only stops a plug painting
       over the rock below the water line if a shape ever comes out unexpectedly large.
       The silhouette itself is never touched, which is the entire point: the learner's
       answer stays the shape they cut. */
    ctx.beginPath();
    // down to the bottom of the STAGE, not to the water line. Bounding it at the water
    // is what cropped the apex off a triangle sized to fill the cavity.
    ctx.rect(gx0 - 80, CFG.surfaceY - 90, (gx1 - gx0) + 160, CFG.H - CFG.surfaceY + 92);
    ctx.clip();

    /* THE OPTION'S OWN MATERIAL, unchanged. This is the learner's answer, and it has
       to stay recognisable as the thing they cut — restyling it into the path's glacier
       banding made the strata line up and lost the shape. What hides the gap is the
       snow settling over the two joins, not disguising the answer as terrain. */
    ctx.translate(cx, cy);
    ctx.rotate(roll);
    ctx.scale(kk * (1 + sq * 0.03), kk * (1 - sq * 0.05));
    // rim divided by the seating scale, so it matches a hanging chunk on screen
    paintGlacierChunk(ctx, p, true, 1 / kk);
    ctx.restore();

    // while it is still growing, frost blooms along the leading edges
    if (e < 1) {
      ctx.save();
      ctx.strokeStyle = `rgba(255,255,255,${(0.9 * (1 - e)).toFixed(3)})`;
      ctx.lineWidth = 10;
      ctx.stroke(sil);
      ctx.restore();
    }


  }

  /** An offscreen canvas, for anything that is redrawn identically every frame. */
  function offscreen(w, h) {
    const c = document.createElement('canvas');
    c.width = Math.max(1, Math.ceil(w)); c.height = Math.max(1, Math.ceil(h));
    return c;
  }


  function drawRepairedPieces(ctx) {
    for (const g of ground.gaps) {
      if (!(g.pieces && g.pieces.length)) continue;
      /* Every plug that has landed is drawn, whether or not the crevasse is finished
         — that is what makes a half-answered "cut all the pentagons" read as progress.
         The snow waits for the crossing to be complete, so it is the seal that says
         "done" rather than each individual piece. */
      /* NOTHING IS DRAWN OVER OR AROUND THE PLUG. The opening is plug-wide (the neck of
         an undercut crevasse — see _ditchPath), so the shape's flat edge spans it exactly
         and rests on the lips; the slab is the walkway. A deck, a snow band and an ice
         collar were each tried here and each read as something added to the answer. */
      for (const p of g.pieces) drawKeystone(ctx, g, p);
    }
  }
  function drawCracks(ctx) {
    for (const g of ground.gaps) {
      if (g.repaired || g.crack <= 0 || g.open > 0.9) continue;
      const cx = (g.x0 + g.x1) / 2 - G.worldX;
      ctx.save();
      ctx.strokeStyle = 'rgba(20,70,120,0.85)'; ctx.lineWidth = 4; ctx.lineCap = 'round';
      ctx.beginPath();
      ctx.moveTo(cx, CFG.surfaceY - 4);
      for (let i = 0; i < g.crackPts.length; i++) {
        if ((i + 1) / g.crackPts.length > g.crack) break;
        ctx.lineTo(cx + g.crackPts[i].x, CFG.surfaceY - 4 + g.crackPts[i].y);
      }
      ctx.stroke();
      ctx.restore();
    }
  }

  /* THE NEAREST ROCK STILL AHEAD — the one a tutorial step about "a rock in the way" is
     about. The same rule the tutorial uses to decide the step is due, so the two agree. */
  function rockAhead() {
    let best = null, bx = Infinity;
    for (const o of obstacles.list) {
      if (o.passed || o.hits >= 3) continue;
      const sx = o.x - G.worldX;
      if (sx > 620 && sx < 1500 && sx < bx) { best = o; bx = sx; }
    }
    return best;
  }

  /* THE FOCUS RENDER — one subject, alone, on a transparent canvas the tutorial owns.

     The tutorial used to COPY a rectangle of the game canvas and lift it over its blur
     sheet. That lifted the sky and ice behind the subject along with it — a patch of
     picture with a shape of its own (an oval, a rounded square, whatever the mask was)
     that read as a spotlight or a panel however it was feathered. What was asked for
     is the SUBJECT lifted, and only the subject: the character glowing along his own
     outline, the rock along its, the row of blocks along theirs.

     So the engine draws the subject again here, by itself, with the same view transform
     as the frame under it. The stylesheet then glows the canvas by its ALPHA, which is
     exactly the subject's silhouette — no background comes with it because nothing but
     the subject was drawn. Shadows, fog, halos and vapour are switched off for the same
     reason: each is a soft shape with alpha, and each would have glowed as a shape.

     Once per step, not per frame: every step that shows this has frozen the game. */
  function renderFocus(target, kind) {
    if (!target || !target.getContext) return;
    const fx = target.getContext('2d');
    fx.clearRect(0, 0, CFG.W, CFG.H);
    if (!kind) return;
    fx.save();
    if (G.zoom > 1.0005) {
      fx.translate(G.zoomVX, G.zoomVY);
      fx.scale(G.zoom, G.zoom);
      fx.translate(-G.zoomVX, -G.zoomVY);
    }
    switch (kind) {
      case 'mammoth': mammoth.draw(fx, G.t, true); break;
      case 'rock': { const o = rockAhead(); if (o) obstacles.draw(fx, G.worldX, G.t, o); break; }
      case 'gap':
        ground.drawDitch(fx, G.worldX, G.t);
        ground.drawWaterFront(fx, G.worldX, G.t);
        ground.drawLips(fx, G.worldX);
        break;
      case 'blocks': if (G.l1) drawHangingShapes(fx, false, true); break;
    }
    fx.restore();
  }

  /* THE CELEBRATION SHEET. 36 frames of 754x434 in a 6x6 grid, authored at 100ms a frame
     (10fps). Measured off the frames: the feet sit on row 374, and the mammoth's centre
     is 184px in from the left; he is drawn 1.3x, which puts him at the size he runs at,
     with his x where he stopped. Frames are indexed off the state clock, so the dance
     runs at its authored rate on any display and never stutters with the frame rate.
     A little poof under whichever of them lands on each beat (frames 0/18 the mammoth,
     9/27 the bear) is the one thing added to the drawn animation. */
  const DUO = { cw: 754, ch: 434, cols: 6, n: 36, fps: 10, feet: 374, mammothCx: 184, bearCx: 610, scale: 1.22 };   // 1.22: air between the bear's raised paws and the banner
  function drawDuo(ctx, a) {
    const img = images.duo;
    if (!img) return;
    const f = Math.floor(G.st / (1000 / DUO.fps)) % DUO.n;
    const sx = (f % DUO.cols) * DUO.cw, sy = Math.floor(f / DUO.cols) * DUO.ch;
    const k = DUO.scale, w = DUO.cw * k, h = DUO.ch * k;
    const x = CFG.mammothX - DUO.mammothCx * k, y = CFG.surfaceY - DUO.feet * k;
    if (f !== G.duoFrame) {
      G.duoFrame = f;
      if (!reduced && f % 9 === 0) {
        const cx = x + (f % 18 === 0 ? DUO.mammothCx : DUO.bearCx) * k;
        particles.poof(cx, CFG.surfaceY, 3, 0.8);
      }
    }
    ctx.save();
    ctx.globalAlpha = a;
    ctx.imageSmoothingEnabled = true; ctx.imageSmoothingQuality = 'high';
    ctx.drawImage(img, sx, sy, DUO.cw, DUO.ch, Math.round(x), Math.round(y), Math.round(w), Math.round(h));
    ctx.restore();
  }

  function render() {
    ctx.clearRect(0, 0, CFG.W, CFG.H);
    // an impact is a random jolt; a quake is a rumble. They are different signals and
    // they are summed, so a bonk still punches through a quake.
    const sh = G.shake > 0 ? G.shake : 0;
    let ox = sh ? rand(-sh, sh) : 0, oy = sh ? rand(-sh, sh) : 0;
    const qa = G.quakeAt || 0;
    if (qa > 0.01) {
      const w = G.t * 6.2832;
      const jitter = reduced ? 0 : 0.1;
      const qx = qa * (0.62 * Math.sin(w * 7.4) + 0.28 * Math.sin(w * 13.1 + 1.7) + jitter * rand(-1, 1));
      const qy = qa * 0.52 * (0.58 * Math.sin(w * 9.3 + 0.6) + 0.30 * Math.sin(w * 17.9 + 2.2) + jitter * rand(-1, 1));
      ox += qx; oy += qy;
      G.quakeOx = qx; G.quakeOy = qy;    // readable, so the waveform can be checked
    }
    ctx.save();
    ctx.translate(ox, oy);
    /* THE PHASE ZOOM, applied before the punch so the two multiply rather than fight:
       the zoom is a slow sustained framing and the punch is a fast transient on top of
       whatever the framing currently is. */
    if (G.zoom > 1.0005) {
      ctx.translate(G.zoomVX, G.zoomVY);
      ctx.scale(G.zoom, G.zoom);
      ctx.translate(-G.zoomVX, -G.zoomVY);
    }
    /* The punch, applied about the point the impact happened so that point holds
       still while the frame swells around it. */
    if (G.punchAt > 0.0005) {
      const k = 1 + G.punchAt;
      ctx.translate(G.punchX, G.punchY);
      ctx.scale(k, k);
      ctx.translate(-G.punchX, -G.punchY);
    }

    /* ONE TARGET. There used to be two: the world was drawn into a full-size offscreen
       canvas whenever G.focus rose above 0, then blitted back through ctx.filter =
       blur() with a dim over it, to push the world back during a puzzle.

       G.focus IS NEVER ASSIGNED A NON-ZERO VALUE anywhere in the engine — the only
       lines that ever touched it were that test and the reset that puts it to 0. So the
       branch could not run, and what it cost was not nothing: a second 1920x1080
       canvas, 8.3MB of backing store allocated for every game instance, on a mobile
       budget where that is a real fraction of what a tab is allowed. ctx.filter is also
       one of the slowest calls in the 2D API and it sat in the hot path behind a branch
       nobody could take.

       Removed rather than wired up: the instruction card already owns the stage alone
       during PHASE_INTRO, which is the beat a blur would have been for. */
    bgm.draw(ctx, G.worldX, reduced);
    atmos.drawAurora(ctx, G.t, reduced);
    atmos.drawBack(ctx, G.worldX, G.t, reduced, bgm.light());
    ground.drawDitch(ctx, G.worldX, G.t);
    drawHangingShapes(ctx, true);
    // the pool surface closes over anything that fell into it
    ground.drawWaterFront(ctx, G.worldX, G.t);
    ground.draw(ctx, G.worldX, G.t);
    drawCracks(ctx);
    drawRepairedPieces(ctx);
    obstacles.draw(ctx, G.worldX, G.t);
    // behind the character, so the two never fight for the same pixels on arrival
    /* THE ENDING IS A DANCE. Once the journey is complete the standing pair cross-fades
       (300ms) into the delivered two-character celebration sheet — the mammoth bobbing,
       the bear up on his hind legs waving — so the last screen moves, rather than
       holding a pose next to a static friend. The mammoth's x is kept, so nothing
       jumps at the swap. */
    const duo = G.state === 'COMPLETE' && images.duo ? clamp(G.st / 300, 0, 1) : 0;
    if (duo < 1) {
      if (duo > 0) { ctx.save(); ctx.globalAlpha = 1 - duo; }
      drawBear(ctx);
      mammoth.draw(ctx, G.t);
      if (duo > 0) ctx.restore();
    }
    if (duo > 0) drawDuo(ctx, duo);
    drawDazeStars(ctx);
    atmos.drawFront(ctx, G.worldX, G.t, reduced);

    particles.draw(ctx);
    drawHitFx(ctx);
    if (G.l1) { drawHangingShapes(ctx, false); drawCutGuide(ctx); drawCutDemo(ctx); drawSlash(ctx); }
    drawTaps(ctx);                    // over everything: it is the player's own mark
    ctx.restore();
  }

  /* ---- loop ---- */
  function frame(ts) {
    if (destroyed) return;
    raf = requestAnimationFrame(frame);
    if (!last) last = ts;
    let dt = (ts - last) / 1000; last = ts;
    if (paused) return;
    dt = Math.min(dt, 1 / 30);
    /* Fast-forward STEPS the simulation; it does not scale dt. Multiplying dt would
       give the same game time with each step that much coarser, which changes the jump
       arc and everything that depends on it — a fast-forward that quietly alters
       physics is worse than none. Rendering once per frame is what makes it cheap:
       rendering is the expensive half. */
    for (let i = 0; i < fastForward; i++) update(dt);
    render();
  }

  function resetAll() {
    G.state = 'BOOT'; G.st = 0; G.worldX = 0; G.dist = 0; G.progress = 0; G.t = 0;
    G.speedFactor = 1; G.shake = 0; G.shakeT = 0; G.moving = true;
    G.instruction = ''; G.jumpEnabled = false; G.jumpPulse = false;
    G.complete = false; G.l1 = null; G.attempts = 0; G.idle = 0;
    G.phase = 0; G.phasesDone = 0; G.gapsThisPhase = null; G.phaseLayout = null; G.phaseJumped = false;
    G.oops = false; G.hitFx = 0; G.hitObstacle = null; G.hitReturn = null; G.hitCount = 0;
    G.handHint = null; G.idleHand = 0; G.dropReady = false;
    G.shakeAmp = 0; G.shakeLen = 0;
    G.quakeT = 0; G.quakeAmp = 0; G.quakeLen = 0; G.quakePeak = 0; G.quakeAt = 0;
    G.freeze = 0; G.punchAmp = 0; G.punchT = 0; G.punchLen = 0; G.punchAt = 0;
    G.bearAt = 0;                   // the friend is not placed until the run home
    slash = null; brk = null; taps.length = 0;
    ground.reset(); obstacles.reset(); particles.clear(); mammoth.reset(); bgm.reset();
    atmos.intensity = 0; atmos.flash = 0;
    audio.setDuck(1);
    setState('RUN_SEGMENT_1');
  }

  const api = {
    jump() {
      audio.start(); audio.resume();
      if (!G.jumpEnabled) return;
      mammoth.requestJump(performance.now());
    },
    restart() { resetAll(); },
    /** Hand over from the title/select screens into the run. */
    begin() { resetAll(); },
    /** Retry the obstacle just walked into. Never restarts the journey. */
    retryObstacle() { if (G.state === 'OBSTACLE_HIT') retryObstacle(); },
    /* setCharacter, _skid and _footline were removed. The roster has one entry so
       nothing can swap characters; _footline always returned null, because the
       per-frame footline measurement went when the slicer started baking every frame
       onto one shared line and there was nothing left to correct. */
    /** The playable roster, for the selection screen. */
    roster: () => CFG.characters.map(c => ({
      id: c.id, name: c.name, tag: c.tag, blurb: c.blurb,
      theme: c.theme, theme2: c.theme2, stats: c.stats
    })),
    character: () => characterId,
    /** Play one of the game's own sounds from the DOM screens, so the cover, the
        select screen and the HUD buttons share one palette. */
    sfx(name) { audio.start(); audio.resume(); if (typeof audio[name] === 'function') audio[name](); },
    /** A character's sheet URL + frame count, for portraits and DOM panels. */
    sheetFor(id, slot) {
      const cid = id || characterId;
      const img = images[cid + ':' + slot];
      if (!img) return null;
      const ch = CFG.characters.find(c => c.id === cid);
      return { src: img.src, frames: ch ? (ch.frames[slot] || 1) : 1 };
    },
    setPaused(v) { paused = v; if (!v) last = 0; },
    /* READABLE, so a test can tell a frozen simulation from a slow one. paused is a
       closure variable and there was no way to observe it: a harness had to infer the
       freeze from G.moving, which is the CHARACTER movement flag and is already false
       during a puzzle — so an explaining step that failed to pause looked identical to
       one that worked. */
    isPaused: () => paused,
    /* BACKGROUNDING SHOULD BE SILENT. setPaused stops the simulation and nothing else,
       so a hidden tab went on playing the music bed and holding an AudioContext open
       for a game that was frozen. main.js calls these alongside it. Both are safe to
       call when there is no context yet, and resumeAudio deliberately does NOT start
       one — the first gesture still owns that. */
    suspendAudio() {
      if (audio.music) audio.music.el.pause();
      if (audio.ctx && audio.ctx.state === 'running' && audio.ctx.suspend) {
        const p = audio.ctx.suspend(); if (p && p.catch) p.catch(() => {});
      }
    },
    resumeAudio() {
      if (!audio.enabled) return;
      audio.resume();
      if (audio.music) { const p = audio.music.el.play(); if (p && p.catch) p.catch(() => {}); }
    },
    /** Sound on/off from the HUD. Returns the new state. */
    toggleSound() {
      audio.start(); audio.resume();
      audio.enabled = !audio.enabled;
      if (audio.master) audio.master.gain.setTargetAtTime(audio.enabled ? 0.7 : 0, audio.ctx.currentTime, 0.05);
      audio.kitMute(!audio.enabled);
      /* The bed is PAUSED, not just turned down. Muting the bus silences it, but a
         five-megabyte track left running is still being decoded for nothing. */
      if (audio.music) {
        if (audio.enabled) { const p = audio.music.el.play(); if (p && p.catch) p.catch(() => {}); }
        else audio.music.el.pause();
      }
      if (audio.enabled) audio.ui();
      return audio.enabled;
    },
    soundOn: () => !!audio.enabled,
    /** Re-show the current instruction, for a learner who has forgotten it. */
    replayInstruction() {
      if (!G.instruction) return false;
      armInstruction(T.instructionHold);
      G.instrLast = '';               // forces the banner to re-enter
      audio.ui();
      return true;
    },
    setOptions(o) {
      if (o.sound !== undefined) {
        audio.enabled = !!o.sound;
        if (audio.master) audio.master.gain.value = o.sound ? 0.7 : 0;
        audio.kitMute(!o.sound);
        if (audio.music && !o.sound) audio.music.el.pause();
      }
      if (o.reduced !== undefined) reduced = !!o.reduced || mqReduced;
      if (o.speed) CFG.runSpeed = o.speed;
      if (o.fast !== undefined) fastForward = clamp(Math.round(o.fast) || 1, 1, 8);
    },
    get paused() { return paused; },
    destroy() {
      destroyed = true; cancelAnimationFrame(raf);
      if (audio.music) { audio.music.el.pause(); audio.music.el.src = ''; }
      canvas.removeEventListener('pointerdown', onDown);
      canvas.removeEventListener('pointermove', onMove);
      window.removeEventListener('pointerup', onUp);
      window.removeEventListener('pointercancel', onCancel);
      canvas.removeEventListener('lostpointercapture', onCancel);
      window.removeEventListener('keydown', onKey);
      window.removeEventListener('resize', invalidateRect);
      window.removeEventListener('orientationchange', invalidateRect);
      if (audio.ctx) audio.ctx.close();
    },
    state: () => G.state,
    /** Which animation state the character is in — handy when checking that a
        sequence (skid → tremble → look down) actually plays. */
    mammothState: () => mammoth && mammoth.state,
    mammothFrame: () => mammoth ? mammoth.lastSheet + ':' + mammoth.lastFrame : '-',
    debug: () => G,
    /** Create the audio graph and start decoding the recordings BEFORE the first gesture,
        so no cue is ever caught half-loaded. Nothing plays until a real tap resumes it. */
    warmAudio() { try { audio.start(); } catch (e) { /* no audio here */ } },
    /** Draw one tutorial subject alone onto `target` (a 1920x1080 canvas): 'mammoth',
        'rock', 'gap', 'blocks', or null to clear. See renderFocus. */
    renderFocus(target, kind) { renderFocus(target, kind); },
    /* THE IMPACT LAYER, drivable from outside. It is the one piece of polish in here
       that can stall the game rather than merely look wrong, so its tests have to be
       able to fire a hold and a punch directly — including several on one frame —
       instead of waiting for an impact to happen and hoping to catch the frame. */
    /* The decoded sfx table, so tools/bake-onsets.mjs can read the hit times the
       waveform analysis found and write them into the config — see that file. */
    _sfxTable: () => audio.sfx,
    _hitStop: ms => hitStop(ms),
    _punch: (amp, ms, x, y) => punch(amp, ms, x, y),
    _juice: () => CFG.juice,
    _ground: () => ground,
    _obstacles: () => obstacles,
    /* The live particle list, so a test or a capture harness can wait for the exact
       frame an effect exists on rather than guessing at a delay. */
    _particles: () => particles,
    _force(s) { obstacles.reset(); setState(s); },
    /** Slice a hanging option by shape name — lets a test drive a phase to the end. */
    _cut(kind) {
      if (!G.l1) return false;
      const sh = G.l1.shapes.find(s => s.state === 'hang' && s.kind === kind);
      if (!sh) return false;
      cutShape(sh); return true;
    },
    _skipTo(ms) { G.st += ms; },
    /** Drive the character's animation state directly, for an animation audit. */
    _anim(s) { mammoth.setState(s); },
    _player: () => mammoth
  };

  preload().then(() => {
    if (destroyed) return;
    ground = new GroundManager(images.path);
    ground.caps = { l: images.capL || null, r: images.capR || null };
    ground.rockBand = images.rockBand || null;
    obstacles = new ObstacleController(
      [images.rockWide, images.rockTall, ...OBSTACLE_ART.map(k => images['obs:' + k])],
      audio, particles);
    bgm = new BackgroundTimeManager(images);
    mammoth = new PlayerController(audio, particles, currentCharacter(), images);
    mammoth.onJump = () => atmos.pulse();
    // Wait on the title/select screens rather than dropping straight into the run,
    // so PLAY reframes into gameplay instead of cutting to it. Entered BEFORE the
    // ready hook, because a host that calls begin() from onReady must win.
    setState('TITLE');
    hooks.onReady && hooks.onReady();
    raf = requestAnimationFrame(frame);
  });

  return api;
}
